练习-求和需求：某公司全年四个季度（每个季度 3 个月）的营业额存入二维数组，分别统计每个季度的营业额总和，再累加出全年的总营业额。
public static void main(String[] args) &#123;    // 4 行分别代表四个季度，每行的 3 个数是该季度三个月的营业额    int[][] turnovers = &#123;            &#123;22, 66, 44&#125;,            &#123;77, 33, 88&#125;,            &#123;25, 45, 65&#125;,            &#123;11, 66, 99&#125;    &#125;;    int sum = 0;    for (int i = 0; i &lt; turnovers.length; i++) &#123;        // 注意：这里不能用 sum(...) 作为方法名调用，因为 main 中已定义了        // 同名局部变量 sum（变量名会遮蔽方法名），所以方法命名为 sumArray        int quarterSum = sumArray(turnovers[i]);        System.out.println(&quot;第&quot; + (i + 1) + &quot;季度的营业额总和为：&quot; + quarterSum);        sum += quarterSum;    &#125;    System.out.println(&quot;全年的营业额总和为：&quot; + sum);&#125;// 求一维数组的元素之和public static int sumArray(int[] arr) &#123;    int sum = 0;    for (int i = 0; i &lt; arr.length; i++) &#123;        sum += arr[i];    &#125;    return sum;&#125;

