// Role.java// 注意：Role 类的 attack 方法里用到了 Random，需要导入import java.util.Random;public class Role &#123;    private String name;   // 姓名    private int blood;     // 血量    public Role() &#123;    &#125;    public Role(String name, int blood) &#123;        this.name = name;        this.blood = blood;    &#125;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;    public int getBlood() &#123;        return blood;    &#125;    public void setBlood(int blood) &#123;        this.blood = blood;    &#125;    // 攻击方法：this（攻击方）攻击传入的 target（目标）    public void attack(Role target) &#123;        // 随机生成伤害值（0~19）        Random random = new Random();        int hurt = random.nextInt(20);        // 目标血量减去伤害值        int remainder = target.getBlood() - hurt;        // 防止血量被减成负数：小于 0 时归 0        remainder = Math.max(remainder, 0);        // 更新目标血量        target.setBlood(remainder);        // 输出本次攻击信息        System.out.println(this.getName() + &quot; 攻击 &quot; + target.getName() + &quot; 造成了 &quot; + hurt + &quot; 点伤害，&quot;                + target.getName() + &quot; 还剩余 &quot; + target.getBlood() + &quot; 滴血&quot;);    &#125;&#125;

public class Main &#123;    public static void main(String[] args) &#123;        // 创建两个角色        Role role1 = new Role(&quot;张三丰&quot;, 100);        Role role2 = new Role(&quot;乔峰&quot;, 100);        // 循环进行攻击        while (true) &#123;            // 张三丰攻击乔峰            role1.attack(role2);            // 若乔峰的血量为0，则张三丰获胜            if (role2.getBlood() == 0) &#123;                System.out.println(role1.getName() + &quot;获胜&quot;);                break;            &#125;            // 乔峰攻击张三丰            role2.attack(role1);            // 若张三丰的血量为0，则乔峰获胜            if (role1.getBlood() == 0) &#123;                System.out.println(role2.getName() + &quot;获胜&quot;);                break;            &#125;        &#125;    &#125;&#125;// 运行结果示例（每次运行随机数不同，实际输出略有差异）：// 张三丰 攻击 乔峰 造成了 5 点伤害，乔峰 还剩余 95 滴血// 乔峰 攻击 张三丰 造成了 7 点伤害，张三丰 还剩余 93 滴血// ...（中间对战过程省略）...// 乔峰获胜

