数组练习 5需求：用对象数组模拟一个简单的”学生管理系统”：先初始化 5 个学生，再支持①添加学生（学号不能重复，数组满了自动扩容）②按学号删除学生，每次操作后把当前全部学生打印出来。

提示：需要 import java.util.Scanner;。数组一旦创建长度就固定不变，本练习通过”复制到更长的新数组”来模拟动态扩容。

// Student.javapublic class Student &#123;    private int id;    private String name;    private int age;    public Student() &#123;    &#125;    public Student(int id, String name, int age) &#123;        this.id = id;        this.name = name;        this.age = age;    &#125;    public int getId() &#123;        return id;    &#125;    public void setId(int id) &#123;        this.id = id;    &#125;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;    public int getAge() &#123;        return age;    &#125;    public void setAge(int age) &#123;        this.age = age;    &#125;    @Override    public String toString() &#123;        return &quot;Student&#123;&quot; +                &quot;id=&quot; + id +                &quot;, name=&#x27;&quot; + name + &#x27;\&#x27;&#x27; +                &quot;, age=&quot; + age +                &#x27;&#125;&#x27;;    &#125;&#125;

// Main.javapublic class Main &#123;    public static void main(String[] args) &#123;        Student[] students = new Student[10];        for (int i = 0; i &lt; 5; i++) &#123;            students[i] = new Student(i, &quot;学生&quot; + i, 18 + i);        &#125;        for (Student student : students) &#123;            if (student != null) &#123;                System.out.println(student);            &#125;        &#125;        Scanner scanner = new Scanner(System.in);        while (true) &#123;            Student newStudent = new Student();            System.out.print(&quot;请输入学号：&quot;);            newStudent.setId(scanner.nextInt());            System.out.print(&quot;请输入姓名：&quot;);            newStudent.setName(scanner.next());            System.out.print(&quot;请输入年龄：&quot;);            newStudent.setAge(scanner.nextInt());            if (!contains(students, newStudent.getId())) &#123;                int realLength = getRealLength(students);   // 数组里实际存了几个学生                if (realLength == students.length) &#123;                    // 数组已满：先扩容（长度 +1），再把新学生放到末尾                    students = copy(students, students.length + 1);                    students[students.length - 1] = newStudent;                &#125; else &#123;                    // 没满：放到第一个空位上                    students[realLength] = newStudent;                &#125;                break;   // 添加成功，结束本次录入            &#125; else &#123;                System.out.println(&quot;该学生已存在，请重新输入&quot;);            &#125;        &#125;        for (Student student : students) &#123;            if (student != null) &#123;                System.out.println(student);            &#125;        &#125;        while (true) &#123;            System.out.print(&quot;请输入要删除学生的ID：&quot;);            int deleteId = scanner.nextInt();            if (contains(students, deleteId)) &#123;                int index = getIndexById(students, deleteId);                // 把 index 之后的所有元素整体前移一位，覆盖掉被删除的学生                for (int i = index; i &lt; students.length - 1; i++) &#123;                    students[i] = students[i + 1];                &#125;                // 前移后最后一个位置残留了重复引用，手动置 null 释放                students[students.length - 1] = null;                break;            &#125; else &#123;                System.out.print(&quot;该学生不存在，请重新输入&quot;);            &#125;        &#125;        for (Student student : students) &#123;            if (student != null) &#123;                System.out.println(student);            &#125;        &#125;    &#125;    public static boolean contains(Student[] students, int id) &#123;        for (Student student : students) &#123;            if (student != null &amp;&amp; student.getId() == id) &#123;                return true;            &#125;        &#125;        return false;    &#125;    public static int getRealLength(Student[] students) &#123;        int length = 0;        for (Student student : students) &#123;            if (student != null) &#123;                length++;            &#125;        &#125;        return length;    &#125;    // 把 students 中的内容复制到长度为 length 的新数组中（用于扩容）    public static Student[] copy(Student[] students, int length) &#123;        Student[] newStudents = new Student[length];        for (int i = 0; i &lt; students.length; i++) &#123;            if (students[i] != null) &#123;                newStudents[i] = students[i];            &#125;        &#125;        return newStudents;    &#125;    public static int getIndexById(Student[] students, int id) &#123;        for (int i = 0; i &lt; students.length; i++) &#123;            if (students[i] != null &amp;&amp; students[i].getId() == id) &#123;                return i;            &#125;        &#125;        return -1;    &#125;&#125;

static 静态变量static 是 静态修饰符，用于修饰 成员变量 和 成员方法。当一个 成员变量 被 static 修饰后，这个成员变量就被称为 静态成员变量。该类的所有实例化对象都会 共享 这个变量，并且可以通过类名直接访问，例如：Student.teacherName。
静态变量代码示例// Student.javapublic class Student &#123;    private String name;    private int age;    // 静态成员变量    public static String className;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;    public int getAge() &#123;        return age;    &#125;    public void setAge(int age) &#123;        this.age = age;    &#125;    @Override    public String toString() &#123;        return &quot;Student&#123;&quot; +                &quot;name=&#x27;&quot; + name + &#x27;\&#x27;&#x27; +                &quot;, age=&quot; + age +                &#x27;&#125;&#x27;;    &#125;&#125;

// Main.java// 使用类名访问静态变量，直接赋值Student.className = &quot;一班&quot;;Student s1 = new Student();s1.setName(&quot;zhangsan&quot;);s1.setAge(18);Student s2 = new Student();s2.setName(&quot;lisi&quot;);s2.setAge(19);// s1 和 s2 并未对 className 进行赋值操作，但是却有值，是因为所有对象共享这个变量System.out.println(s1);           // Student&#123;name=&#x27;zhangsan&#x27;, age=18&#125;System.out.println(s1.className); // 一班System.out.println(s2);           // Student&#123;name=&#x27;lisi&#x27;, age=19&#125;System.out.println(s2.className); // 一班

static 静态方法和工具类静态方法同理，被 static 修饰的方法称为静态方法，使用类名即可直接调用，无需先实例化对象，如：Math.abs()，多用于工具类中
工具类工具类是指一些静态方法的集合，通常不需要实例化对象即可使用。常见的工具类有：java.lang.Math、java.util.Collections 等。
练习一定义一个工具类，提供一个方法，用于格式化输出数组内容，提供一个方法，用于求数组平均值

提示：StringJoiner 在 java.util 包中，使用前需要 import java.util.StringJoiner;。把构造方法私有化可以杜绝外部 new 出工具类对象。

// ArrayUtil.javapublic class ArrayUtil &#123;    // 私有构造方法，防止实例化    private ArrayUtil()&#123;&#125;    // 公有静态方法，直接使用类名访问    public static String formatPrintArray(int[] arr)&#123;        StringJoiner sj = new StringJoiner(&quot;,&quot;, &quot;[&quot;, &quot;]&quot;);        for (int i = 0; i &lt; arr.length; i++) &#123;            sj.add(String.valueOf(arr[i]));        &#125;        return sj.toString();    &#125;    public static double getAverage(int[] arr)&#123;        double sum = 0.0;        for (int i = 0; i &lt; arr.length; i++) &#123;            sum += arr[i];        &#125;        return  sum / arr.length;    &#125;&#125;

public class Main &#123;    public static void main(String[] args) &#123;        int[] arr = &#123;1, 2, 3, 4, 5, 6&#125;;        // 调用工具类方法，直接使用类名访问，无需实例化对象        String result = ArrayUtil.formatPrintArray(arr);        System.out.println(result);     // [1,2,3,4,5,6]        double average = ArrayUtil.getAverage(arr);        System.out.println(average);    // 3.5    &#125;&#125;

