public class GameJFrame extends JFrame implements KeyListener &#123;    ......    // 记录空白图片的位置    private int emptyImgX;    private int emptyImgY;    ......&#125;

private void initData() &#123;    ......    // 保存空白图片的位置    for (int i = 0; i &lt; data.length; i++) &#123;        for (int j = 0; j &lt; data[i].length; j++) &#123;            if (data[i][j] == 15) &#123;                emptyImgX = i;                emptyImgY = j;                break;            &#125;        &#125;    &#125;&#125;

private void initImage() &#123;    // 清空图片    this.getContentPane().removeAll();    ......    // 刷新界面    this.getContentPane().repaint();&#125;

@Overridepublic void keyReleased(KeyEvent e) &#123;    // 获取按键的 code    int code = e.getKeyCode();    // 判断按键是否是上下左右    if (code == KeyEvent.VK_UP || code == KeyEvent.VK_DOWN || code == KeyEvent.VK_LEFT || code == KeyEvent.VK_RIGHT) &#123;        int temp = data[emptyImgX][emptyImgY];        // 根据按键类型进行 data 中数据的交换        // 注意数组边界检测        if (code == KeyEvent.VK_UP &amp;&amp; emptyImgX != LEVEL - 1) &#123;            data[emptyImgX][emptyImgY] = data[emptyImgX + 1][emptyImgY];            data[emptyImgX + 1][emptyImgY] = temp;            emptyImgX++;        &#125; else if (code == KeyEvent.VK_DOWN &amp;&amp; emptyImgX != 0) &#123;            data[emptyImgX][emptyImgY] = data[emptyImgX - 1][emptyImgY];            data[emptyImgX - 1][emptyImgY] = temp;            emptyImgX--;        &#125; else if (code == KeyEvent.VK_LEFT &amp;&amp; emptyImgY != LEVEL - 1) &#123;            data[emptyImgX][emptyImgY] = data[emptyImgX][emptyImgY + 1];            data[emptyImgX][emptyImgY + 1] = temp;            emptyImgY++;        &#125; else if (code == KeyEvent.VK_RIGHT &amp;&amp; emptyImgY != 0) &#123;            data[emptyImgX][emptyImgY] = data[emptyImgX][emptyImgY - 1];            data[emptyImgX][emptyImgY - 1] = temp;            emptyImgY--;        &#125;        // 移动完 data 中的数据，要重新绘制图片        initImage();    &#125;&#125;

