public class Frog extends Animal implements Swim &#123;    public Frog() &#123;    &#125;    public Frog(String name, int age) &#123;        super(name, age);    &#125;    @Override    public void eat() &#123;        System.out.println(&quot;Frog eat&quot;);    &#125;    @Override    public void swim() &#123;        System.out.println(&quot;Frog swim&quot;);    &#125;&#125;

