登录注册
说明：原文此处只写了”略”。登录&#x2F;注册与前面章节的窗口骨架对应，课程完整版一般还会把注册用户写入本地文件（需要 IO 流）、加图形验证码等。下面给出一个简化可运行的参考实现（只演示主流程），学完 IO 相关章节后可自行改成文件存储。

登录窗口的逻辑：用户在输入框里填写账号、密码，点击”登录”按钮后与”已注册用户”比对，一致就进入游戏主界面，不一致就弹窗提示。
package com.code_dog.ui;import javax.swing.*;import java.awt.*;import java.awt.event.ActionEvent;import java.awt.event.ActionListener;// 登录窗口（简化参考实现）public class LoginJFrame extends JFrame &#123;    // 模拟一个已注册用户（正式版应从本地文件或数据库中读取）    private static final String USERNAME = &quot;admin&quot;;    private static final String PASSWORD = &quot;123456&quot;;    public LoginJFrame() &#123;        init();    &#125;    private void init() &#123;        // 窗口基本设置（与前面章节一致）        this.setSize(488, 430);        this.setTitle(&quot;拼图 登录&quot;);        this.setLocationRelativeTo(null);        this.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);        // 简化布局：从上到下依次排列账号、密码、登录按钮        this.setLayout(new FlowLayout());        this.add(new JLabel(&quot;账号：&quot;));        JTextField usernameField = new JTextField(15);        this.add(usernameField);        this.add(new JLabel(&quot;密码：&quot;));        // 密码框输入的内容会显示为圆点，避免被旁人看到        JPasswordField passwordField = new JPasswordField(15);        this.add(passwordField);        JButton loginButton = new JButton(&quot;登录&quot;);        this.add(loginButton);        // 给登录按钮绑定点击事件        loginButton.addActionListener(new ActionListener() &#123;            @Override            public void actionPerformed(ActionEvent e) &#123;                // JPasswordField.getPassword() 返回的是 char 数组，转成字符串再比较                String username = usernameField.getText();                String password = new String(passwordField.getPassword());                if (USERNAME.equals(username) &amp;&amp; PASSWORD.equals(password)) &#123;                    // 登录成功：关掉登录窗口，进入游戏主界面                    LoginJFrame.this.dispose();                    new GameJFrame();                &#125; else &#123;                    JOptionPane.showMessageDialog(LoginJFrame.this, &quot;账号或密码错误&quot;);                &#125;            &#125;        &#125;);        this.setVisible(true);    &#125;&#125;

注册窗口的思路与前面”学生管理系统”里的注册校验一致：收集账号、密码、确认密码，校验两次密码一致且满足基本规则（如长度限制）后，把新用户保存起来（这里简化为只打印一行提示，正式版可存进集合或写入文件），再提示注册成功。校验逻辑部分可参考 Java13（学生管理系统）中的 checkUsername、checkPassword 等写法，这里不再重复展开。

查找基本查找基本查找也称为顺序查找，它是通过遍历整个数组或集合来查找目标元素。时间复杂度为 O(n)，空间复杂度为 O(1)。
public static int sequentialSearch(int[] arr, int value) &#123;    for (int i = 0; i &lt; arr.length; i++) &#123;        if (arr[i] == value) &#123;            return i;        &#125;    &#125;    return -1;&#125;

二分查找二分查找是基于有序数组的一种查找方式。它每次从中间位置开始比较，并排除掉一半元素，直到找到目标值。时间复杂度为 O(log n)，空间复杂度为 O(1)。二分查找要求数组必须是 有序 的。
public static int binarySearch(int[] arr, int value) &#123;    // 二分查找    int min = 0;    int max = arr.length - 1;    while (min &lt;= max) &#123;        int mid = (min + max) / 2;        if (arr[mid] == value) &#123;            return mid;        &#125; else if (arr[mid] &gt; value) &#123;            max = mid - 1;        &#125; else &#123;            min = mid + 1;        &#125;    &#125;    return -1;&#125;

插值查找插值查找是一种更高效的查找方式，它会根据目标值和数组范围的关系，估算目标元素大致的位置，然后再进行查找。时间复杂度通常为 O(log log n)，空间复杂度为 O(1)。它同样要求数组是 有序 的，并且数据量较大、分布比较均匀时效果才明显；如果数据分布极不均匀，可能比二分查找还慢。
public static int interpolationSearch(int[] arr, int value) &#123;    int min = 0;    int max = arr.length - 1;    while (min &lt;= max) &#123;        int mid = min + (value - arr[min]) / (arr[max] - arr[min]) * (max - min);        if (arr[mid] == value) &#123;            return mid;        &#125; else if (arr[mid] &gt; value) &#123;            max = mid - 1;        &#125; else &#123;            min = mid + 1;        &#125;    &#125;    return -1;&#125;

斐波那契查找斐波那契查找利用斐波那契数列来确定元素可能出现的位置，再进行比较和缩小范围。时间复杂度为 O(log n)，空间复杂度为 O(1)。它也要求数组是 有序 的。

说明：标准的斐波那契查找还需要把原数组”填充”到斐波那契数列对应的长度（多出的位置用最大值补上），代码会复杂不少。这里给出的是教学简化版，只演示核心思路，没有做数组填充，个别边界情况可能照顾不到，理解算法思想即可。

public static int fibonacciSearch(int[] arr, int value) &#123;    int n = arr.length;    // 找到最小的斐波那契数，使其大于等于数组长度    int k = 1;    while (fib(k) &lt; n) &#123;        k++;    &#125;    int min = 0;    int max = arr.length - 1;    while (min &lt;= max) &#123;        int mid = min + fib(k - 1) - 1;        if (arr[mid] == value) &#123;            return mid;        &#125; else if (arr[mid] &gt; value) &#123;            k -= 2;            max = mid - 1;        &#125; else &#123;            k -= 1;            min = mid + 1;        &#125;    &#125;    return -1;&#125;// 计算斐波那契数列private static int fib(int k) &#123;    if (k == 1 || k == 2) &#123;        return 1;    &#125;    return fib(k - 1) + fib(k - 2);&#125;

分块查找分块查找是把数组分成多个小块，并在每块中保存一个最大值。查找时，先确定目标元素可能在哪一块，再在该块中进行顺序查找。时间复杂度为 O(√n)，空间复杂度为 O(1)。
// 用来保存块的信息class Block &#123;    // 当前块的最大值    private int maxValue;    // 当前块的起始索引    private int startIndex;    // 当前块的结束索引    private int endIndex;    public Block(int maxValue, int startIndex, int endIndex) &#123;        this.maxValue = maxValue;        this.startIndex = startIndex;        this.endIndex = endIndex;    &#125;    public int getMaxValue() &#123;        return maxValue;    &#125;    public void setMaxValue(int maxValue) &#123;        this.maxValue = maxValue;    &#125;    public int getStartIndex() &#123;        return startIndex;    &#125;    public void setStartIndex(int startIndex) &#123;        this.startIndex = startIndex;    &#125;    public int getEndIndex() &#123;        return endIndex;    &#125;    public void setEndIndex(int endIndex) &#123;        this.endIndex = endIndex;    &#125;    @Override    public String toString() &#123;        return &quot;Block&#123;&quot; +                &quot;maxValue=&quot; + maxValue +                &quot;, startIndex=&quot; + startIndex +                &quot;, endIndex=&quot; + endIndex +                &#x27;&#125;&#x27;;    &#125;&#125;

// 分块private static Block[] splitBlock(int[] arr) &#123;    double sqrt = Math.sqrt(arr.length);    int blockCount = (int) Math.ceil(sqrt);    int blockSize = (int) Math.ceil((double) arr.length / blockCount);    Block[] blocks = new Block[blockCount];    for (int i = 0; i &lt; blocks.length; i++) &#123;        int startIndex = i * blockSize;        int endIndex = Math.min(startIndex + blockSize, arr.length);        int maxValue = arr[startIndex];        for (int j = startIndex; j &lt; endIndex; j++) &#123;            if (arr[j] &gt; maxValue) &#123;                maxValue = arr[j];            &#125;        &#125;        Block block = new Block(maxValue, startIndex, endIndex);        blocks[i] = block;    &#125;    return blocks;&#125;

// 查找目标元素所在的块private static int getBlockIndex(Block[] blocks, int value) &#123;    for (int i = 0; i &lt; blocks.length; i++) &#123;        Block block = blocks[i];        // 目标值小于等于某块的最大值时，说明它可能就在这块中        // 注意用 &lt;= 而不是 &lt;：如果 value 恰好等于某块的最大值，也应该进入这块查找        if (value &lt;= block.getMaxValue()) &#123;            return i;        &#125;    &#125;    // 所有块的最大值都比目标值小，说明目标值不在数组中    return -1;&#125;

// 分块查找public static int blockSearch(int[] arr, int value) &#123;    Block[] blocks = splitBlock(arr);    int blockIndex = getBlockIndex(blocks, value);    if (blockIndex &lt; 0) &#123;        return -1;    &#125;    Block block = blocks[blockIndex];    int startIndex = block.getStartIndex();    int endIndex = block.getEndIndex();    for (int i = startIndex; i &lt; endIndex; i++) &#123;        if (arr[i] == value) &#123;            return i;        &#125;    &#125;    return -1;&#125;

排序冒泡排序冒泡排序通过两两比较相邻元素，把最大（或最小）的元素一步步”冒”到数组末尾（或开头），然后重复上述过程，直到数组有序。时间复杂度为 O(n^2)，空间复杂度为 O(1)。
private static int[] bubbleSort(int[] arr) &#123;    for (int i = 0; i &lt; arr.length - 1; i++) &#123;        for (int j = 0; j &lt; arr.length - 1 - i; j++) &#123;            if (arr[j] &gt; arr[j + 1]) &#123;                int temp = arr[j];                arr[j] = arr[j + 1];                arr[j + 1] = temp;            &#125;        &#125;    &#125;    return arr;&#125;

选择排序选择排序通过每轮找出数组中的最小（或最大）元素，把它放到数组的起始位置，然后重复上述过程，直到数组有序。时间复杂度为 O(n^2)，空间复杂度为 O(1)。
private static int[] selectionSort(int[] arr) &#123;    for (int i = 0; i &lt; arr.length - 1; i++) &#123;        for (int j = i; j &lt; arr.length; j++) &#123;            if (arr[i] &gt; arr[j]) &#123;                int temp = arr[i];                arr[i] = arr[j];                arr[j] = temp;            &#125;        &#125;    &#125;    return arr;&#125;

插入排序插入排序把数组划分为”已排序”和”未排序”两部分，每一轮把未排序部分的第一个元素插入到已排序部分的正确位置，直到数组有序。时间复杂度为 O(n^2)，空间复杂度为 O(1)。
private static int[] insertionSort(int[] arr) &#123;    for (int i = 1; i &lt; arr.length; i++) &#123;        int key = arr[i];        int j = i - 1;        // 将大于key的元素向后移动        while (j &gt;= 0 &amp;&amp; arr[j] &gt; key) &#123;            arr[j + 1] = arr[j];            j--;        &#125;        // 将key插入到正确位置        arr[j + 1] = key;    &#125;    return arr;&#125;

递归递归通过把一个大问题分解成更小的同类子问题，直到子问题可以直接解决，再逐层返回、组合子问题的解，从而得到原问题的解。递归方法要特别注意”递归出口”，否则会无限调用、栈溢出。
public static void main(String[] args) &#123;    System.out.println(recursiveSum(100));    System.out.println(recursiveFactorial(5));&#125;// 计算1到num的和// 当 num = 100 时，需要求 100 + （1 ~ 99）的和// 当 num = 99 时，需要求 99 + （1 ~ 98）的和// ...// 当 num = 2 时，需要求 2 + （1 ~ 1）的和// 当 num = 1 时，返回 1private static int recursiveSum(int num) &#123;    if (num == 1) &#123;        return 1;    &#125;    return num + recursiveSum(num - 1);&#125;// 计算 num 的阶乘// 当 num = 5 时，需要求 5 * 4!// 当 num = 4 时，需要求 4 * 3!// ...// 当 num = 2 时，需要求 2 * 1!// 当 num = 1 时，返回 1private static int recursiveFactorial(int num) &#123;    if (num == 1) &#123;        return 1;    &#125;    return num * recursiveFactorial(num - 1);&#125;

快速排序快速排序先选定一个基准值（pivot），通过一趟交换把数组分成两部分：左边都小于等于基准，右边都大于基准；然后对左右两个子数组递归地重复这个过程，最终整体有序。平均时间复杂度为 O(n log n)，空间复杂度为 O(log n)（递归栈）。
private static void quickSort(int[] arr, int left, int right) &#123;    if (left &gt;= right) &#123;        return;    &#125;    int pivotValue = arr[left];    int pivotIndex = left;    for (int i = left + 1; i &lt;= right; i++) &#123;        if (arr[i] &lt; pivotValue) &#123;            pivotIndex++;            int temp = arr[i];            arr[i] = arr[pivotIndex];            arr[pivotIndex] = temp;        &#125;    &#125;    int temp = arr[left];    arr[left] = arr[pivotIndex];    arr[pivotIndex] = temp;    quickSort(arr, left, pivotIndex - 1);    quickSort(arr, pivotIndex + 1, right);&#125;

