&lt;c:param&gt;
用来给包含或重定向的页面传递参数


&lt;c:redirect&gt;
重定向至一个新的 URL


&lt;c:url&gt;
使用可选的查询参数来创建一个 URL


&lt;%@ page import=&quot;java.util.List&quot; %&gt;&lt;%@ page import=&quot;java.util.Map&quot; %&gt;&lt;%@ page import=&quot;java.util.HashMap&quot; %&gt;&lt;%@ taglib prefix=&quot;c&quot; uri=&quot;jakarta.tags.core&quot; %&gt;&lt;%@ page contentType=&quot;text/html;charset=UTF-8&quot; language=&quot;java&quot; %&gt;&lt;html&gt;&lt;head&gt;    &lt;title&gt;Title&lt;/title&gt;&lt;/head&gt;&lt;body&gt;&lt;%--c:set--%&gt;&lt;div&gt;    &lt;c:set scope=&quot;request&quot; var=&quot;name&quot; value=&quot;Tom&quot;/&gt;    $&#123;requestScope.name&#125;&lt;/div&gt;&lt;%--c:if--%&gt;&lt;div&gt;    &lt;c:if scope=&quot;request&quot; var=&quot;isTom&quot; test=&quot;$&#123;name == &#x27;Tom&#x27;&#125;&quot;/&gt;    $&#123;requestScope.isTom&#125;&lt;br&gt;    &lt;c:if test=&quot;$&#123;name == &#x27;Tom&#x27;&#125;&quot;&gt;        &lt;span&gt;I&#x27;m Tom!&lt;/span&gt;    &lt;/c:if&gt;&lt;/div&gt;&lt;%--c:choose--%&gt;&lt;div&gt;    &lt;c:set scope=&quot;request&quot; var=&quot;grade&quot; value=&quot;60&quot;/&gt;    &lt;c:choose&gt;        &lt;c:when test=&quot;$&#123;requestScope.grade ge 90&#125;&quot;&gt;优秀&lt;/c:when&gt;        &lt;c:when test=&quot;$&#123;requestScope.grade ge 80&#125;&quot;&gt;良好&lt;/c:when&gt;        &lt;c:when test=&quot;$&#123;requestScope.grade ge 70&#125;&quot;&gt;一般&lt;/c:when&gt;        &lt;c:when test=&quot;$&#123;requestScope.grade ge 60&#125;&quot;&gt;及格&lt;/c:when&gt;        &lt;c:otherwise&gt;不及格&lt;/c:otherwise&gt;    &lt;/c:choose&gt;&lt;/div&gt;&lt;%--c:forEach--%&gt;&lt;div&gt;    &lt;%--    1 ~ 10 --%&gt;    &lt;c:forEach var=&quot;i&quot; begin=&quot;1&quot; end=&quot;10&quot; step=&quot;1&quot;&gt;        $&#123;i&#125;    &lt;/c:forEach&gt;    &lt;br&gt;    &lt;%--    数组 --%&gt;    &lt;% request.setAttribute(&quot;array&quot;, new String[]&#123;&quot;Java&quot;, &quot;C++&quot;, &quot;Python&quot;&#125;); %&gt;    &lt;c:forEach var=&quot;item&quot; items=&quot;$&#123;requestScope.array&#125;&quot;&gt;        $&#123;item&#125;    &lt;/c:forEach&gt;    &lt;br&gt;    &lt;%--    List --%&gt;    &lt;% request.setAttribute(&quot;list&quot;, List.of(&quot;Java&quot;, &quot;C++&quot;, &quot;PHP&quot;)); %&gt;    &lt;c:forEach var=&quot;item&quot; items=&quot;$&#123;requestScope.list&#125;&quot;&gt;        $&#123;item&#125;    &lt;/c:forEach&gt;    &lt;br&gt;    &lt;%--    Map --%&gt;    &lt;%        Map&lt;String, Object&gt; map = new HashMap&lt;&gt;();        map.put(&quot;key1&quot;, &quot;Java&quot;);        map.put(&quot;key2&quot;, &quot;C++&quot;);        map.put(&quot;key3&quot;, &quot;JavaScript&quot;);        request.setAttribute(&quot;map&quot;, map);    %&gt;    &lt;c:forEach var=&quot;item&quot; items=&quot;$&#123;requestScope.map&#125;&quot;&gt;        $&#123;item.key&#125; = $&#123;item.value&#125;    &lt;/c:forEach&gt;&lt;/div&gt;&lt;/body&gt;&lt;/html&gt;

