文件下载public class DownloadServlet extends HttpServlet &#123;    @Override    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException &#123;        // 文件名        String fileName = &quot;1.jpg&quot;;        // ServletContext        ServletContext servletContext = getServletContext();        // 设置响应头        resp.setContentType(servletContext.getMimeType(&quot;/file/&quot; + fileName));        resp.setHeader(&quot;Content-Disposition&quot;, &quot;attachment; filename=&quot; + fileName);        // 获取输入流        InputStream inputStream = servletContext.getResourceAsStream(&quot;/file/&quot; + fileName);        // 获取输出流        ServletOutputStream outputStream = resp.getOutputStream();        // 读取全部内容        IOUtils.copy(inputStream, outputStream);    &#125;&#125;

中文文件名的处理当文件名是中文时，直接将文件名写入响应头会导致乱码，因此需要使用 URLEncoder 对文件名进行编码后再放入响应头。
public class DownloadServlet extends HttpServlet &#123;    @Override    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException &#123;        // 文件名        String fileName = &quot;微信截图.jpg&quot;;        // ServletContext        ServletContext servletContext = getServletContext();        // 设置响应头        resp.setContentType(servletContext.getMimeType(&quot;/file/&quot; + fileName));        resp.setHeader(&quot;Content-Disposition&quot;, &quot;attachment; filename=&quot; + URLEncoder.encode(fileName, StandardCharsets.UTF_8));        // 获取输入流        InputStream inputStream = servletContext.getResourceAsStream(&quot;/file/&quot; + fileName);        // 获取输出流        ServletOutputStream outputStream = resp.getOutputStream();        // 读取全部内容        IOUtils.copy(inputStream, outputStream);    &#125;&#125;

文件上传文件上传需要满足以下条件：

上传控件必须在 form 表单中，且请求方式必须为 post
form 标签中必须设置 enctype 属性，值为 multipart/form-data
在 form 标签中使用 input 标签，将 type 设置为 file，用于选择文件
在服务端接收文件并处理

&lt;form action=&quot;api/avatar&quot; method=&quot;post&quot; enctype=&quot;multipart/form-data&quot;&gt;  &lt;!-- 用于选择文件 --&gt;  &lt;input type=&quot;file&quot; name=&quot;avatar&quot; /&gt;  &lt;input type=&quot;submit&quot; /&gt;&lt;/form&gt;

public class UploadServlet extends HTMLServlet &#123;    @Override    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException &#123;        System.out.println(&quot;接收到请求&quot;);    &#125;&#125;

接收数据因为前端使用二进制流的形式发送数据，因此后端也需要使用流的形式来接收。
public class UploadServlet extends HTMLServlet &#123;    @Override    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException &#123;        ServletInputStream inputStream = req.getInputStream();        byte[] buffer = new byte[1024];        int len = -1;        StringBuilder stringBuilder = new StringBuilder();        while ((len = inputStream.read(buffer)) != -1) &#123;            stringBuilder.append(new String(buffer, 0, len));        &#125;        System.out.println(stringBuilder);    &#125;&#125;

解析数据可以使用 commons-fileupload-1.6.0.jar 和 commons-io-2.21.0.jar 两个第三方 jar 包来解析数据。
如果使用 Tomcat 10 及以上版本，则需要使用 fileupload2 系列，并导入 jakarta 和 core 两个 jar 包。
public class UploadServlet extends HTMLServlet &#123;    @Override    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException &#123;        // 判断文件是否使用 multipart/form-data 形式上传        boolean multipartContent = JakartaServletFileUpload.isMultipartContent(req);        if (multipartContent) &#123;            DiskFileItemFactory factory = DiskFileItemFactory.builder().get();            JakartaServletFileUpload&lt;?, ?&gt; upload = new JakartaServletFileUpload&lt;&gt;(factory);            // 解析请求            FileItemInputIterator itemIterator = upload.getItemIterator(req);            while (itemIterator.hasNext()) &#123;                // 获取请求中的每一项                FileItemInput fileItemInput = itemIterator.next();                boolean formField = fileItemInput.isFormField();                // 判断当前项是普通输入框还是文件                if (formField) &#123;                    System.out.println(&quot;输入框&quot;);                    String fieldName = fileItemInput.getFieldName();                    System.out.println(fieldName);                &#125; else &#123;                    System.out.println(&quot;文件&quot;);                    String name = fileItemInput.getName();                    System.out.println(name);                    String contentType = fileItemInput.getContentType();                    System.out.println(contentType);                    String fieldName = fileItemInput.getFieldName();                    System.out.println(fieldName);                    InputStream inputStream = fileItemInput.getInputStream();                    OutputStream outputStream = new FileOutputStream(&quot;E:&quot; + File.separator + name);                    outputStream.write(inputStream.readAllBytes());                &#125;            &#125;        &#125;    &#125;&#125;

Filter
Filter 过滤器是 Java Web 三大组件之一
Filter 过滤器是一个接口
Filter 过滤器作用：拦截请求，过滤响应

Filter 初体验背景：web 目录下有一个 admin 文件夹，其中的资源 a.html 必须要登录后才可以访问。

实现 Filter 接口
在 web.xml 中配置 Filter

public class CustomFilter implements Filter &#123;    @Override    public void doFilter(ServletRequest servletRequest, ServletResponse servletResponse, FilterChain filterChain) throws IOException, ServletException &#123;        // 强转        HttpServletRequest request = (HttpServletRequest) servletRequest;        // 获取 Session        HttpSession session = request.getSession();        // 判断是否登录        Object attribute = session.getAttribute(&quot;username&quot;);        if (Objects.isNull(attribute)) &#123;            // 未登录，转发到登录页，并结束当前方法，不再放行            servletRequest.getRequestDispatcher(&quot;/login.jsp&quot;).forward(servletRequest, servletResponse);            return;        &#125;        // 已登录，放行        filterChain.doFilter(servletRequest, servletResponse);    &#125;&#125;

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;web-app xmlns=&quot;http://xmlns.jcp.org/xml/ns/javaee&quot;         xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;         xsi:schemaLocation=&quot;http://xmlns.jcp.org/xml/ns/javaee http://xmlns.jcp.org/xml/ns/javaee/web-app_4_0.xsd&quot;         version=&quot;4.0&quot;&gt;    &lt;servlet&gt;        &lt;servlet-name&gt;LoginServlet&lt;/servlet-name&gt;        &lt;servlet-class&gt;com.lasyc.servlet.LoginServlet&lt;/servlet-class&gt;    &lt;/servlet&gt;    &lt;servlet-mapping&gt;        &lt;servlet-name&gt;LoginServlet&lt;/servlet-name&gt;        &lt;url-pattern&gt;/login&lt;/url-pattern&gt;    &lt;/servlet-mapping&gt;    &lt;filter&gt;        &lt;filter-name&gt;CustomFilter&lt;/filter-name&gt;        &lt;filter-class&gt;com.lasyc.filter.CustomFilter&lt;/filter-class&gt;    &lt;/filter&gt;    &lt;filter-mapping&gt;        &lt;filter-name&gt;CustomFilter&lt;/filter-name&gt;        &lt;!-- 对所有 URL 都做过滤 --&gt;        &lt;url-pattern&gt;/&lt;/url-pattern&gt;    &lt;/filter-mapping&gt;&lt;/web-app&gt;

// 登录用 Servlet，登录成功保存 username 到 Sessionpublic class LoginServlet extends BaseServlet &#123;    protected void login(HttpServletRequest res, HttpServletResponse rep) throws IOException, ServletException &#123;        String username = res.getParameter(&quot;username&quot;);        String password = res.getParameter(&quot;password&quot;);        if (&quot;admin&quot;.equals(username) &amp;&amp; &quot;123456&quot;.equals(password)) &#123;            HttpSession session = res.getSession();            session.setAttribute(&quot;username&quot;, &quot;admin&quot;);            rep.getWriter().write(&quot;登录成功&quot;);            res.getRequestDispatcher(&quot;/admin/a.html&quot;).forward(res, rep);        &#125; else &#123;            rep.getWriter().write(&quot;密码错误&quot;);        &#125;    &#125;&#125;

Filter 的生命周期
构造器方法
init 初始化方法
doFilter 过滤方法
destroy 销毁方法

Filter ConfigFilterConfig 是过滤器配置对象，用于获取 Filter 的初始化参数，以及获取 ServletContext 上下文对象。
&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;web-app xmlns=&quot;http://xmlns.jcp.org/xml/ns/javaee&quot;         xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;         xsi:schemaLocation=&quot;http://xmlns.jcp.org/xml/ns/javaee http://xmlns.jcp.org/xml/ns/javaee/web-app_4_0.xsd&quot;         version=&quot;4.0&quot;&gt;    &lt;filter&gt;        &lt;filter-name&gt;CustomFilter&lt;/filter-name&gt;        &lt;filter-class&gt;com.lasyc.filter.CustomFilter&lt;/filter-class&gt;        &lt;init-param&gt;            &lt;param-name&gt;username&lt;/param-name&gt;            &lt;param-value&gt;root&lt;/param-value&gt;        &lt;/init-param&gt;        &lt;init-param&gt;            &lt;param-name&gt;password&lt;/param-name&gt;            &lt;param-value&gt;123456&lt;/param-value&gt;        &lt;/init-param&gt;    &lt;/filter&gt;    &lt;filter-mapping&gt;        &lt;filter-name&gt;CustomFilter&lt;/filter-name&gt;        &lt;!-- 对所有 URL 都做过滤 --&gt;        &lt;!--&lt;url-pattern&gt;/&lt;/url-pattern&gt;--&gt;        &lt;!-- 针对 admin 路径下的所有请求都做过滤 --&gt;        &lt;url-pattern&gt;/admin/*&lt;/url-pattern&gt;    &lt;/filter-mapping&gt;&lt;/web-app&gt;

@Overridepublic void init(FilterConfig filterConfig) throws ServletException &#123;    Filter.super.init(filterConfig);    // 过滤器名    String filterName = filterConfig.getFilterName();    // web.xml 中配置的初始化参数    Enumeration&lt;String&gt; initParameterNames = filterConfig.getInitParameterNames();    Iterator&lt;String&gt; iterator = initParameterNames.asIterator();    while (iterator.hasNext()) &#123;        String next = iterator.next();        String initParameter = filterConfig.getInitParameter(next);        System.out.println(next + &quot; = &quot; + initParameter);    &#125;    // 获取 ServletContext 对象    ServletContext servletContext = filterConfig.getServletContext();&#125;

Filter ChainFilterChain 是过滤器链对象，表示 Filter 的执行链条。通过调用 doFilter 方法可以放行请求；当存在多个 Filter 时，FilterChain 会按照配置的顺序依次执行各个 Filter 的 doFilter 方法。
下面案例的执行结构是：Filter 1 前置代码 -&gt; Filter 2 前置代码 -&gt; target.jsp -&gt; Filter 2 后置代码 -&gt; Filter 1 后置代码。可以看出 FilterChain 的放行机制是：先执行前置代码，等所有过滤器的前置代码都执行结束后，再执行目标资源代码，最后再反向执行各个过滤器的后置代码，就像 Java 中方法的调用链一样。
在 FilterChain 中，过滤器的执行顺序取决于 web.xml 中定义的顺序。每一个 Filter 都必须执行 doFilter 方法来放行请求，否则请求就会被拦截在当前 Filter 中，无法继续向下执行。

所有过滤器以及访问的目标资源都在同一个线程中
所有过滤器以及访问的目标资源都是用的同一个 request 和 response 对象

public class Filter1 implements Filter &#123;    @Override    public void doFilter(ServletRequest servletRequest, ServletResponse servletResponse, FilterChain filterChain) throws IOException, ServletException &#123;        System.out.println(&quot;Filter 1 前置代码&quot;);        // 放行        filterChain.doFilter(servletRequest, servletResponse);        System.out.println(&quot;Filter 1 后置代码&quot;);    &#125;&#125;

public class Filter2 implements Filter &#123;    @Override    public void doFilter(ServletRequest servletRequest, ServletResponse servletResponse, FilterChain filterChain) throws IOException, ServletException &#123;        System.out.println(&quot;Filter 2 前置代码&quot;);        // 放行        filterChain.doFilter(servletRequest, servletResponse);        System.out.println(&quot;Filter 2 后置代码&quot;);    &#125;&#125;

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;web-app xmlns=&quot;http://xmlns.jcp.org/xml/ns/javaee&quot;         xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;         xsi:schemaLocation=&quot;http://xmlns.jcp.org/xml/ns/javaee http://xmlns.jcp.org/xml/ns/javaee/web-app_4_0.xsd&quot;         version=&quot;4.0&quot;&gt;    &lt;!-- Filter 的执行顺序取决于定义的顺序 --&gt;    &lt;filter&gt;        &lt;filter-name&gt;Filter1&lt;/filter-name&gt;        &lt;filter-class&gt;com.lasyc.utils.filter.Filter1&lt;/filter-class&gt;    &lt;/filter&gt;    &lt;filter-mapping&gt;        &lt;filter-name&gt;Filter1&lt;/filter-name&gt;        &lt;url-pattern&gt;/target.jsp&lt;/url-pattern&gt;    &lt;/filter-mapping&gt;    &lt;filter&gt;        &lt;filter-name&gt;Filter2&lt;/filter-name&gt;        &lt;filter-class&gt;com.lasyc.utils.filter.Filter2&lt;/filter-class&gt;    &lt;/filter&gt;    &lt;filter-mapping&gt;        &lt;filter-name&gt;Filter2&lt;/filter-name&gt;        &lt;url-pattern&gt;/target.jsp&lt;/url-pattern&gt;    &lt;/filter-mapping&gt;&lt;/web-app&gt;

&lt;%@ page contentType=&quot;text/html;charset=UTF-8&quot; language=&quot;java&quot; %&gt;&lt;html&gt;  &lt;head&gt;    &lt;title&gt;Title&lt;/title&gt;  &lt;/head&gt;  &lt;body&gt;    &lt;% System.out.println(&quot;target.jsp&quot;); %&gt;  &lt;/body&gt;&lt;/html&gt;

Filter 拦截路径Filter 的拦截路径可以通过 web.xml 中的 &lt;url-pattern&gt; 标签进行配置，常见的配置方式有以下几种：精确匹配、路径匹配、扩展名匹配。
精确匹配精确匹配：精确到某个资源，例如 /index.html，只有访问该资源时才会被 Filter 拦截。
路径匹配路径匹配：使用 /* 来表示，例如 /admin/*，表示拦截 /admin 目录下的所有资源，包括子目录中的资源。
扩展名匹配扩展名匹配：使用 *.jsp 这种形式来表示，例如 *.jsp 表示拦截所有以 .jsp 结尾的资源。

什么是 AJAXAJAX 是 Asynchronous JavaScript and XML（异步 JavaScript 和 XML）的缩写。它是一种在不重新加载整个页面的情况下，与服务器交换数据并更新部分网页内容的技术。
示例
创建 XMLHttpRequest 对象
设置请求参数
发送请求
获取响应数据

&lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;  &lt;head&gt;    &lt;meta charset=&quot;UTF-8&quot; /&gt;    &lt;title&gt;Title&lt;/title&gt;  &lt;/head&gt;  &lt;body&gt;    &lt;table&gt;      &lt;thead&gt;        &lt;tr&gt;          &lt;th&gt;ID&lt;/th&gt;          &lt;th&gt;Name&lt;/th&gt;          &lt;th&gt;Age&lt;/th&gt;        &lt;/tr&gt;      &lt;/thead&gt;      &lt;tbody id=&quot;person-table-tbody&quot;&gt;&lt;/tbody&gt;    &lt;/table&gt;    &lt;button onclick=&quot;ajaxRequest()&quot;&gt;发送 ajax 请求&lt;/button&gt;  &lt;/body&gt;  &lt;script&gt;    function ajaxRequest() &#123;      // 1. 创建 AJAX 对象      const xmlHttpRequest = new XMLHttpRequest();      // 2. 设置参数      // 第一个参数：请求方式      // 第二个参数：请求路径，如果是 GET 请求要拼接请求参数      // 第三个参数：是否异步，开启异步，不会阻塞其他代码的执行，否则要等服务器响应之后，其他代码才能执行      xmlHttpRequest.open(        &quot;GET&quot;,        &quot;http://localhost:8080/servlet_study/ajax?action=selectPerson&quot;,        true,      );      // 3. 注册回调函数：每当 readyState 改变时，就会触发 onreadystatechange 事件      xmlHttpRequest.onreadystatechange = function () &#123;        // ajax 有五个状态，分别是        // 0: 请求未初始化        // 1: 服务器连接已建立        // 2: 请求已接收        // 3: 请求处理中        // 4: 请求已完成，且响应已就绪        // 当请求已完成，并且响应为 200 时，处理返回数据        if (xmlHttpRequest.readyState === 4 &amp;&amp; xmlHttpRequest.status === 200) &#123;          // 将数据显示到画面上，需要先将 JSON 字符串转为 JSON 对象          const personList = JSON.parse(xmlHttpRequest.responseText);          console.log(personList);          const tbody = document.getElementById(&quot;person-table-tbody&quot;);          // 清空之前的数据          tbody.replaceChildren();          // 把新的数据以表格的形式显示在页面          personList.forEach((person) =&gt; &#123;            const idTd = document.createElement(&quot;td&quot;);            idTd.innerText = person.id;            const nameTd = document.createElement(&quot;td&quot;);            nameTd.innerText = person.name;            const ageTd = document.createElement(&quot;td&quot;);            ageTd.innerText = person.age;            const tr = document.createElement(&quot;tr&quot;);            tr.append(idTd, nameTd, ageTd);            tbody.append(tr);          &#125;);        &#125;      &#125;;      // 4. 发送请求      xmlHttpRequest.send();      console.log(        &quot;如果开启异步，不用等服务器响应我就可以执行，否则我要等服务器响应之后才可以执行&quot;,      );    &#125;  &lt;/script&gt;&lt;/html&gt;

public class AJAXServlet extends BaseServlet &#123;    protected void selectPerson(HttpServletRequest req, HttpServletResponse resp) throws IOException &#123;        // 模拟查询到的信息        Person person1 = new Person(&quot;ID001&quot;, &quot;张三&quot;, 20);        Person person2 = new Person(&quot;ID002&quot;, &quot;李四&quot;, 21);        Person person3 = new Person(&quot;ID003&quot;, &quot;王五&quot;, 22);        List&lt;Person&gt; personList = List.of(person1, person2, person3);        // 将信息返回到前端，需要转为 JSON 字符串        Gson gson = new Gson();        String json = gson.toJson(personList);        // 传回前端        resp.getWriter().write(json);    &#125;&#125;

jQuery 中的 AJAX在 jQuery 中，发送 AJAX 请求非常简单，可以使用 $.ajax() 方法，或者更简化的 $.get() 和 $.post() 方法。
&lt;!-- 引入 jQuery--&gt;&lt;script src=&quot;jquery/jquery-4.0.0.min.js&quot;&gt;&lt;/script&gt;&lt;script&gt;  function ajaxRequest() &#123;    $.ajax(&#123;      // 请求方式      type: &quot;GET&quot;,      // 请求地址      url: &quot;http://localhost:8080/servlet_study/ajax&quot;,      // 请求参数，即使是 GET 请求也可以写成对象的形式      // 会自动拼接成 name=value 的形式      data: &#123;        action: &quot;selectPerson&quot;,      &#125;,      // 返回值类型：text、xml、json      dataType: &quot;json&quot;,      // 请求成功后的回调函数      success: (res) =&gt; &#123;        console.log(res);      &#125;,    &#125;);  &#125;  function getRequest() &#123;    // 参数顺序：URL，data，callback，dataType    $.get(      &quot;http://localhost:8080/servlet_study/ajax&quot;,      &#123; action: &quot;selectPerson&quot; &#125;,      (res) =&gt; &#123;        console.log(res);      &#125;,      &quot;json&quot;,    );  &#125;  function postRequest() &#123;    // 参数顺序：URL，data，callback，dataType    $.post(      &quot;http://localhost:8080/servlet_study/ajax&quot;,      &#123; action: &quot;selectPerson&quot; &#125;,      (res) =&gt; &#123;        console.log(res);      &#125;,      &quot;json&quot;,    );  &#125;&lt;/script&gt;

在 $.get() 和 $.post() 方法的基础上，jQuery 还提供了 $.getJSON() 方法，专门用于获取 JSON 数据。$.getJSON() 的参数顺序与 $.get() 相同（URL、data、callback），且该方法只适用于 GET 请求。
function jsonRequest() &#123;  // 参数顺序：URL，data，callback  $.getJSON(    &quot;http://localhost:8080/servlet_study/ajax&quot;,    &#123; action: &quot;selectPerson&quot; &#125;,    (res) =&gt; &#123;      console.log(res);    &#125;,  );&#125;

序列化 serialize()在 jQuery 中，如果要发送表单数据，可以使用 serialize() 方法将表单数据序列化成 URL 编码的字符串，也就是 key=value&amp;key=value 的形式。
&lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;  &lt;head&gt;    &lt;meta charset=&quot;UTF-8&quot; /&gt;    &lt;title&gt;Title&lt;/title&gt;  &lt;/head&gt;  &lt;body&gt;    &lt;form id=&quot;userinfo-form&quot;&gt;      &lt;table&gt;        &lt;caption&gt;          用户信息表        &lt;/caption&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;username&quot;&gt;Username:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;&lt;input type=&quot;text&quot; id=&quot;username&quot; name=&quot;username&quot; /&gt;&lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;password&quot;&gt;Password:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;&lt;input type=&quot;password&quot; id=&quot;password&quot; name=&quot;password&quot; /&gt;&lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;gender&quot;&gt;Gender:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;            &lt;input type=&quot;radio&quot; id=&quot;male&quot; name=&quot;gender&quot; value=&quot;male&quot; checked /&gt;            &lt;label for=&quot;male&quot;&gt;Male&lt;/label&gt;            &lt;input type=&quot;radio&quot; id=&quot;female&quot; name=&quot;gender&quot; value=&quot;female&quot; /&gt;            &lt;label for=&quot;female&quot;&gt;Female&lt;/label&gt;          &lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;age&quot;&gt;Age:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;&lt;input type=&quot;number&quot; id=&quot;age&quot; name=&quot;age&quot; min=&quot;18&quot; max=&quot;65&quot; /&gt;&lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;phone&quot;&gt;Phone:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;&lt;input type=&quot;tel&quot; id=&quot;phone&quot; name=&quot;phone&quot; /&gt;&lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;email&quot;&gt;Email:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;&lt;input type=&quot;email&quot; id=&quot;email&quot; name=&quot;email&quot; /&gt;&lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;birthday&quot;&gt;Birthday:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;&lt;input type=&quot;date&quot; id=&quot;birthday&quot; name=&quot;birthday&quot; /&gt;&lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;hobbies&quot;&gt;Hobbies:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;            &lt;input              type=&quot;checkbox&quot;              id=&quot;football&quot;              name=&quot;hobbies&quot;              value=&quot;football&quot;            /&gt;            &lt;label for=&quot;football&quot;&gt;Football&lt;/label&gt;            &lt;input              type=&quot;checkbox&quot;              id=&quot;basketball&quot;              name=&quot;hobbies&quot;              value=&quot;basketball&quot;            /&gt;            &lt;label for=&quot;basketball&quot;&gt;Basketball&lt;/label&gt;          &lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;city&quot;&gt;City:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;            &lt;select name=&quot;city&quot; id=&quot;city&quot;&gt;              &lt;option value=&quot;&quot;&gt;&lt;/option&gt;              &lt;option value=&quot;beijing&quot;&gt;Beijing&lt;/option&gt;              &lt;option value=&quot;shanghai&quot;&gt;Shanghai&lt;/option&gt;              &lt;option value=&quot;guangzhou&quot;&gt;Guangzhou&lt;/option&gt;              &lt;option value=&quot;shenzhen&quot;&gt;Shenzhen&lt;/option&gt;              &lt;option value=&quot;hangzhou&quot;&gt;Hangzhou&lt;/option&gt;              &lt;option value=&quot;wuhan&quot;&gt;Wuhan&lt;/option&gt;              &lt;option value=&quot;chongqing&quot;&gt;Chongqing&lt;/option&gt;            &lt;/select&gt;          &lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;introduce&quot;&gt;Introduce:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;&lt;textarea id=&quot;introduce&quot; name=&quot;introduce&quot;&gt;&lt;/textarea&gt;&lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;label for=&quot;avatar&quot;&gt;Avatar:&lt;/label&gt;&lt;/td&gt;          &lt;td&gt;&lt;input type=&quot;file&quot; id=&quot;avatar&quot; name=&quot;avatar&quot; accept=&quot;.jpg&quot; /&gt;&lt;/td&gt;        &lt;/tr&gt;        &lt;tr&gt;          &lt;td&gt;&lt;input type=&quot;button&quot; id=&quot;Submit&quot; value=&quot;Submit&quot; /&gt;&lt;/td&gt;          &lt;td&gt;&lt;input type=&quot;reset&quot; value=&quot;Reset&quot; /&gt;&lt;/td&gt;        &lt;/tr&gt;      &lt;/table&gt;    &lt;/form&gt;  &lt;/body&gt;  &lt;!-- 引入 jQuery--&gt;  &lt;script src=&quot;jquery/jquery-4.0.0.min.js&quot;&gt;&lt;/script&gt;  &lt;script&gt;    $(&quot;#Submit&quot;).click(() =&gt; &#123;      // 获取表单元素      const form = $(&quot;#userinfo-form&quot;);      // 序列化表单元素中的每个字段 =&gt; name=value&amp;name=value      const data = form.serialize();      $.getJSON(        &quot;http://localhost:8080/servlet_study/ajax?action=submitForm&quot;,        data,        (res) =&gt; &#123;          console.log(res);        &#125;,      );    &#125;);  &lt;/script&gt;&lt;/html&gt;

protected void submitForm(HttpServletRequest req, HttpServletResponse resp) throws IOException &#123;    // 获取表单信息    Enumeration&lt;String&gt; parameterNames = req.getParameterNames();    Iterator&lt;String&gt; iterator = parameterNames.asIterator();    while (iterator.hasNext()) &#123;        String name = iterator.next();        String value = req.getParameter(name);        System.out.println(name + &quot; = &quot; + value);    &#125;&#125;

CookieCookie 是一种由服务器发起、由浏览器保存的键值对数据。浏览器会将这些数据存储下来，当再次向服务器发送请求时，会携带 Cookie 信息，服务器以此来识别用户。
每个 Cookie 大小不能超过 4KB。
创建 CookieCookie 由服务器创建，服务器通过响应头 Set-Cookie 通知浏览器对 Cookie 进行存储。
public class CookieServlet extends BaseServlet &#123;    protected void createCookie(HttpServletRequest req, HttpServletResponse rep) throws ServletException, IOException &#123;        // 创建 Cookie        Cookie cookie = new Cookie(&quot;key&quot;, &quot;value&quot;);        // 通知浏览器保存 Cookie        rep.addCookie(cookie);        // 文字提示        rep.getWriter().write(&quot;Cookie 创建成功&quot;);    &#125;&#125;

public class BaseServlet extends HttpServlet &#123;    @Override    protected void doGet(HttpServletRequest req, HttpServletResponse rep) throws ServletException, IOException &#123;        doPost(req, rep);    &#125;    @Override    protected void doPost(HttpServletRequest req, HttpServletResponse rep) throws ServletException, IOException &#123;        req.setCharacterEncoding(&quot;UTF-8&quot;);        rep.setCharacterEncoding(&quot;UTF-8&quot;);        rep.setContentType(&quot;text/html; charset=utf-8&quot;);        try &#123;            Method method = this.getClass().getDeclaredMethod(req.getParameter(&quot;action&quot;), HttpServletRequest.class, HttpServletResponse.class);            method.invoke(this, req, rep);        &#125; catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException e) &#123;            e.printStackTrace();            throw new RuntimeException(e.getMessage());        &#125;    &#125;&#125;

获取 Cookie通过 req.getCookies() 即可获取请求携带的全部 Cookie。
protected void getCookie(HttpServletRequest req, HttpServletResponse rep) throws ServletException, IOException &#123;    // 获取 Cookie    Cookie[] cookies = req.getCookies();    PrintWriter writer = rep.getWriter();    // 存储需要的 key    String[] cookieArray = new String[]&#123;&quot;key&quot;&#125;;    for (Cookie cookie : cookies) &#123;        String name = cookie.getName();        String value = cookie.getValue();        // 遍历全部 cookie 获取自己需要的 key        if (Arrays.asList(cookieArray).contains(name)) &#123;            writer.write(name + &quot; = &quot; + value + &quot; &lt;br/&gt;&quot;);        &#125;    &#125;&#125;

修改 Cookieprotected void updateCookie(HttpServletRequest req, HttpServletResponse rep) throws ServletException, IOException &#123;    // 1. 创建一个新的 Cookie 覆盖    // Cookie cookie = new Cookie(&quot;key&quot;, &quot;newValue&quot;);    // rep.addCookie(cookie);    // rep.getWriter().write(&quot;Cookie 修改成功&quot;);    // 2. 修改原 Cookie    Cookie cookie = CookieUtils.getCookie(req, &quot;key&quot;);    cookie.setValue(&quot;newValue2&quot;);    rep.addCookie(cookie);    rep.getWriter().write(&quot;Cookie 修改成功&quot;);&#125;

public class CookieUtils &#123;    private CookieUtils() &#123;    &#125;    public static Object getValue(HttpServletRequest request, String key) &#123;        Cookie cookie = getCookie(request, key);        return cookie.getValue();    &#125;    public static Cookie getCookie(HttpServletRequest request, String key) &#123;        if (request == null || key == null || key.isEmpty()) return null;        Cookie[] cookies = request.getCookies();        if (cookies == null) return null;        for (Cookie cookie : cookies) &#123;            if (key.equals(cookie.getName())) return cookie;        &#125;        return null;    &#125;&#125;

Cookie 的存活时间通过 setMaxAge 方法可以控制 Cookie 在浏览器端的存活时间，单位为秒。若设置的值为正数，表示 Cookie 存活指定时间后过期；若为负数（默认值为 -1），表示浏览器关闭后 Cookie 才会过期；若为 0，则表示立刻删除 Cookie。
// 默认时间为 -1，会话级别，只有浏览器关闭才会删除protected void defaultLife(HttpServletRequest req, HttpServletResponse rep) &#123;    Cookie cookie = new Cookie(&quot;key2&quot;, &quot;value2&quot;);    // 设置存活时间，默认就是 -1    cookie.setMaxAge(-1);    rep.addCookie(cookie);&#125;// 立刻删除protected void deleteNow(HttpServletRequest req, HttpServletResponse rep) throws IOException &#123;    Cookie cookie = CookieUtils.getCookie(req, &quot;key&quot;);    if(cookie != null) &#123;        // 设置存活时间，0 为立刻删除        cookie.setMaxAge(0);        rep.addCookie(cookie);    &#125;    rep.getWriter().write(&quot;Cookie 删除成功&quot;);&#125;// 10 秒后删除；即使浏览器关闭，只要在存活时间内，再次打开浏览器 Cookie 仍在protected void customTime(HttpServletRequest req, HttpServletResponse rep) throws IOException &#123;    Cookie cookie = new Cookie(&quot;key3&quot;, &quot;value3&quot;);    // 设置存活时间，10 秒后删除    cookie.setMaxAge(10);    rep.addCookie(cookie);&#125;

Cookie Path可以通过 Path 属性来选择性地向服务器发送 Cookie。当浏览器中存在大量 Cookie 时，每个 Cookie 可能来自于不同的工程或路径，比如 /project1、/project2、/project2/path1、/project2/path2 等。当我们访问指定的工程或路径时，只需要携带对应的 Cookie 即可，不需要全部携带。
protected void customPath(HttpServletRequest req, HttpServletResponse rep) &#123;    Cookie cookie = new Cookie(&quot;key4&quot;, &quot;value4&quot;);    // 浏览器地址必须和 Path 值匹配才可以查看对应的 Cookie    // 所以要在 /servlet_study/cookie.html 中添加 test    // 修改为 /servlet_study/test/cookie.html    cookie.setPath(&quot;/servlet_study/test&quot;);    rep.addCookie(cookie);&#125;

练习登录成功后，下次登录时，通过 Cookie 实现用户名免输入。
&lt;%@ page contentType=&quot;text/html;charset=UTF-8&quot; language=&quot;java&quot; %&gt;&lt;html&gt;  &lt;head&gt;    &lt;title&gt;Title&lt;/title&gt;  &lt;/head&gt;  &lt;body&gt;    &lt;form action=&quot;login?action=login&quot; method=&quot;post&quot;&gt;      &lt;div&gt;        &lt;label for=&quot;username&quot;&gt;&lt;/label&gt;        &lt;!-- 通过 $&#123;cookie.username.value&#125; 读取 cookie  --&gt;        &lt;input          type=&quot;text&quot;          id=&quot;username&quot;          name=&quot;username&quot;          value=&quot;$&#123;cookie.username.value&#125;&quot;        /&gt;      &lt;/div&gt;      &lt;div&gt;        &lt;label for=&quot;password&quot;&gt;&lt;/label&gt;        &lt;input type=&quot;password&quot; id=&quot;password&quot; name=&quot;password&quot; /&gt;      &lt;/div&gt;      &lt;div&gt;&lt;input type=&quot;submit&quot; /&gt;&lt;/div&gt;    &lt;/form&gt;  &lt;/body&gt;&lt;/html&gt;

public class LoginServlet extends BaseServlet &#123;    protected void login(HttpServletRequest res, HttpServletResponse rep) throws IOException &#123;        String username = res.getParameter(&quot;username&quot;);        String password = res.getParameter(&quot;password&quot;);        if (&quot;admin&quot;.equals(username) &amp;&amp; &quot;123456&quot;.equals(password)) &#123;            // 登录成功后设置 Cookie            Cookie cookie = new Cookie(&quot;username&quot;, username);            cookie.setMaxAge(60 * 60 * 24 * 7);            rep.addCookie(cookie);            rep.getWriter().write(&quot;登录成功&quot;);        &#125; else &#123;            rep.getWriter().write(&quot;密码错误&quot;);        &#125;    &#125;&#125;

什么是 I18NI18N 是 Internationalization（国际化）的缩写，18 表示首字母 I 和尾字母 N 之间省略了 18 个字母。国际化是指在软件开发过程中，使软件能够适应不同语言、文化和地区的需求，以便在全球范围内使用。
I18N 的三要素
Locale（语言环境）：表示特定的语言、国家或地区，例如 en_US 表示美国英语，zh_CN 表示中国汉语
Resource Bundle（资源包）：用于存储不同语言环境下的文本和数据，通常以 messages_&lt;locale&gt;.properties 文件的形式存在。例如 messages_en_US.properties 存储美国英语的文本，messages_zh_CN.properties 存储中文（中国）的文本
Resource Bundle Control（资源包控制）：用于控制资源包的加载和使用，例如指定默认语言环境、设置资源包的加载路径等。通过 ResourceBundle.getBundle() 方法加载资源包，通过 ResourceBundle.getString(key) 方法获取资源包中的文本

I18N 的实现# messages_en_US.propertiesusername=Usernamepassword=Password

# messages_zh_CN.propertiesusername=用户名password=密码

public static void testLocale() &#123;    // 获取默认 Locale    Locale aDefault = Locale.getDefault();    System.out.println(aDefault);   // zh_CN    // 查看全部可用的 Locale    Locale[] availableLocales = Locale.getAvailableLocales();    System.out.println(Arrays.toString(availableLocales));  // 太多了，省略    // 获取指定 Locale    System.out.println(Locale.CHINA);   // zh_CN    System.out.println(Locale.US);      // en_US&#125;public static void testResourceBundle() &#123;    ResourceBundle usBundle = ResourceBundle.getBundle(&quot;messages&quot;, Locale.US);    System.out.println(usBundle.getString(&quot;username&quot;));   // Username    ResourceBundle chinaBundle = ResourceBundle.getBundle(&quot;messages&quot;, Locale.CHINA);    System.out.println(chinaBundle.containsKey(&quot;username&quot;));    // true    // 注意：中文可能出现乱码，因为 .properties 文件默认按 ISO-8859-1 编码读取，中文无法被正确解析    System.out.println(chinaBundle.getString(&quot;username&quot;));   // 用户名&#125;

在页面上实现 I18N&lt;%@ page import=&quot;java.util.Locale&quot; %&gt;&lt;%@ page import=&quot;java.util.ResourceBundle&quot; %&gt;&lt;%@ page contentType=&quot;text/html;charset=UTF-8&quot; language=&quot;java&quot; %&gt;&lt;html&gt;&lt;head&gt;    &lt;title&gt;Title&lt;/title&gt;&lt;/head&gt;&lt;body&gt;&lt;%  // 获取 Locale  Locale locale = Locale.getDefault();  // 创建 ResourceBundle  ResourceBundle resourceBundle = ResourceBundle.getBundle(&quot;messages&quot;, locale);%&gt;&lt;div&gt;  &lt;a href=&quot;&quot;&gt;中文&lt;/a&gt;|&lt;a href=&quot;&quot;&gt;English&lt;/a&gt;&lt;/div&gt;&lt;form id=&quot;userinfo-form&quot;&gt;  &lt;table&gt;    &lt;caption&gt;      &lt;%=resourceBundle.getString(&quot;formTitle&quot;)%&gt;    &lt;/caption&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;username&quot;&gt;&lt;%=resourceBundle.getString(&quot;username&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;text&quot; id=&quot;username&quot; name=&quot;username&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;password&quot;&gt;&lt;%=resourceBundle.getString(&quot;password&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;password&quot; id=&quot;password&quot; name=&quot;password&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;gender&quot;&gt;&lt;%=resourceBundle.getString(&quot;gender&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;        &lt;input type=&quot;radio&quot; id=&quot;male&quot; name=&quot;gender&quot; value=&quot;male&quot; checked /&gt;        &lt;label for=&quot;male&quot;&gt;&lt;%=resourceBundle.getString(&quot;male&quot;)%&gt;&lt;/label&gt;        &lt;input type=&quot;radio&quot; id=&quot;female&quot; name=&quot;gender&quot; value=&quot;female&quot; /&gt;        &lt;label for=&quot;female&quot;&gt;&lt;%=resourceBundle.getString(&quot;female&quot;)%&gt;&lt;/label&gt;      &lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;age&quot;&gt;&lt;%=resourceBundle.getString(&quot;age&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;number&quot; id=&quot;age&quot; name=&quot;age&quot; min=&quot;18&quot; max=&quot;65&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;phone&quot;&gt;&lt;%=resourceBundle.getString(&quot;phone&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;tel&quot; id=&quot;phone&quot; name=&quot;phone&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;email&quot;&gt;&lt;%=resourceBundle.getString(&quot;email&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;email&quot; id=&quot;email&quot; name=&quot;email&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;input type=&quot;button&quot; id=&quot;Submit&quot; value=&quot;&lt;%=resourceBundle.getString(&quot;submit&quot;)%&gt;&quot; /&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;reset&quot; value=&quot;&lt;%=resourceBundle.getString(&quot;reset&quot;)%&gt;&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;  &lt;/table&gt;&lt;/form&gt;&lt;/body&gt;&lt;/html&gt;

通过 URL 参数实现 I18N&lt;%@ page import=&quot;java.util.Locale&quot; %&gt;&lt;%@ page import=&quot;java.util.ResourceBundle&quot; %&gt;&lt;%@ page import=&quot;java.util.Arrays&quot; %&gt;&lt;%@ page import=&quot;java.util.Optional&quot; %&gt;&lt;%@ page contentType=&quot;text/html;charset=UTF-8&quot; language=&quot;java&quot; %&gt;&lt;html&gt;&lt;head&gt;    &lt;title&gt;Title&lt;/title&gt;&lt;/head&gt;&lt;body&gt;&lt;%  // 获取 Locale  Locale locale = Locale.getDefault();  String localeParam = request.getParameter(&quot;locale&quot;);  Locale[] availableLocales = Locale.getAvailableLocales();  Optional&lt;Locale&gt; first = Arrays.stream(availableLocales).filter(availableLocale -&gt; availableLocale.toString().equals(localeParam)).findFirst();  if (first.isPresent()) &#123;    locale = first.get();  &#125;  // 创建 ResourceBundle  ResourceBundle resourceBundle = ResourceBundle.getBundle(&quot;messages&quot;, locale);%&gt;&lt;div&gt;  &lt;a href=&quot;i18n.jsp?locale=zh_CN&quot;&gt;中文&lt;/a&gt;|&lt;a href=&quot;i18n.jsp?locale=en_US&quot;&gt;English&lt;/a&gt;&lt;/div&gt;&lt;form id=&quot;userinfo-form&quot;&gt;  &lt;table&gt;    &lt;caption&gt;      &lt;%=resourceBundle.getString(&quot;formTitle&quot;)%&gt;    &lt;/caption&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;username&quot;&gt;&lt;%=resourceBundle.getString(&quot;username&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;text&quot; id=&quot;username&quot; name=&quot;username&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;password&quot;&gt;&lt;%=resourceBundle.getString(&quot;password&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;password&quot; id=&quot;password&quot; name=&quot;password&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;gender&quot;&gt;&lt;%=resourceBundle.getString(&quot;gender&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;        &lt;input type=&quot;radio&quot; id=&quot;male&quot; name=&quot;gender&quot; value=&quot;male&quot; checked /&gt;        &lt;label for=&quot;male&quot;&gt;&lt;%=resourceBundle.getString(&quot;male&quot;)%&gt;&lt;/label&gt;        &lt;input type=&quot;radio&quot; id=&quot;female&quot; name=&quot;gender&quot; value=&quot;female&quot; /&gt;        &lt;label for=&quot;female&quot;&gt;&lt;%=resourceBundle.getString(&quot;female&quot;)%&gt;&lt;/label&gt;      &lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;age&quot;&gt;&lt;%=resourceBundle.getString(&quot;age&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;number&quot; id=&quot;age&quot; name=&quot;age&quot; min=&quot;18&quot; max=&quot;65&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;phone&quot;&gt;&lt;%=resourceBundle.getString(&quot;phone&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;tel&quot; id=&quot;phone&quot; name=&quot;phone&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;email&quot;&gt;&lt;%=resourceBundle.getString(&quot;email&quot;)%&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;email&quot; id=&quot;email&quot; name=&quot;email&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;input type=&quot;button&quot; id=&quot;Submit&quot; value=&quot;&lt;%=resourceBundle.getString(&quot;submit&quot;)%&gt;&quot; /&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;reset&quot; value=&quot;&lt;%=resourceBundle.getString(&quot;reset&quot;)%&gt;&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;  &lt;/table&gt;&lt;/form&gt;&lt;/body&gt;&lt;/html&gt;

使用 JSTL 标签库实现 I18N&lt;!-- 导入对应的 JSTL 标签库 --&gt;&lt;%@ taglib prefix=&quot;fmt&quot; uri=&quot;http://java.sun.com/jsp/jstl/fmt&quot; %&gt;&lt;%@ page contentType=&quot;text/html;charset=UTF-8&quot; language=&quot;java&quot; %&gt;&lt;html&gt;&lt;head&gt;    &lt;title&gt;Title&lt;/title&gt;&lt;/head&gt;&lt;body&gt;&lt;fmt:setLocale value=&quot;$&#123;param.locale&#125;&quot; /&gt;&lt;fmt:setBundle basename=&quot;messages&quot; /&gt;&lt;div&gt;  &lt;a href=&quot;i18n.jsp?locale=zh_CN&quot;&gt;中文&lt;/a&gt;|&lt;a href=&quot;i18n.jsp?locale=en_US&quot;&gt;English&lt;/a&gt;&lt;/div&gt;&lt;form id=&quot;userinfo-form&quot;&gt;  &lt;table&gt;    &lt;caption&gt;      &lt;fmt:message key=&quot;formTitle&quot; /&gt;    &lt;/caption&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;username&quot;&gt;&lt;fmt:message key=&quot;username&quot; /&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;text&quot; id=&quot;username&quot; name=&quot;username&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;password&quot;&gt;&lt;fmt:message key=&quot;password&quot; /&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;password&quot; id=&quot;password&quot; name=&quot;password&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;gender&quot;&gt;&lt;fmt:message key=&quot;gender&quot; /&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;        &lt;input type=&quot;radio&quot; id=&quot;male&quot; name=&quot;gender&quot; value=&quot;male&quot; checked /&gt;        &lt;label for=&quot;male&quot;&gt;&lt;fmt:message key=&quot;male&quot; /&gt;&lt;/label&gt;        &lt;input type=&quot;radio&quot; id=&quot;female&quot; name=&quot;gender&quot; value=&quot;female&quot; /&gt;        &lt;label for=&quot;female&quot;&gt;&lt;fmt:message key=&quot;female&quot; /&gt;&lt;/label&gt;      &lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;age&quot;&gt;&lt;fmt:message key=&quot;age&quot; /&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;number&quot; id=&quot;age&quot; name=&quot;age&quot; min=&quot;18&quot; max=&quot;65&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;phone&quot;&gt;&lt;fmt:message key=&quot;phone&quot; /&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;tel&quot; id=&quot;phone&quot; name=&quot;phone&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;label for=&quot;email&quot;&gt;&lt;fmt:message key=&quot;email&quot; /&gt;:&lt;/label&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;email&quot; id=&quot;email&quot; name=&quot;email&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;    &lt;tr&gt;      &lt;td&gt;&lt;input type=&quot;button&quot; id=&quot;Submit&quot; value=&quot;&lt;fmt:message key=&quot;submit&quot; /&gt;&quot; /&gt;&lt;/td&gt;      &lt;td&gt;&lt;input type=&quot;reset&quot; value=&quot;&lt;fmt:message key=&quot;reset&quot; /&gt;&quot; /&gt;&lt;/td&gt;    &lt;/tr&gt;  &lt;/table&gt;&lt;/form&gt;&lt;/body&gt;&lt;/html&gt;

什么是 JSONJSON 是 JavaScript Object Notation 的缩写，中文名称为 JavaScript 对象表示法，是一种轻量级的数据交换格式。它以文本的形式存储和传输数据，具有易于阅读和编写的特点。

轻量级：早期数据交换使用的是 XML 格式，XML 格式冗长、解析复杂，而 JSON 格式简洁、易于解析
数据交换：JSON 主要用于客户端和服务器之间的数据交换，特别是在 Web 应用中，JSON 已成为主流的数据格式

在 JavaScript 中使用 JSONJSON 结构JSON 是由键值对组成的数据结构，类似于 JavaScript 中的对象
&#123;  &quot;name&quot;: &quot;张三&quot;,  &quot;age&quot;: 20,  &quot;hobbies&quot;: [&quot;篮球&quot;, &quot;足球&quot;],  &quot;address&quot;: &#123;    &quot;city&quot;: &quot;北京&quot;,    &quot;street&quot;: &quot;朝阳区&quot;  &#125;&#125;

创建 JavaScript 对象const person = &#123;  name: &quot;张三&quot;,  age: 20,  hobbies: [&quot;篮球&quot;, &quot;足球&quot;],  address: &#123;    city: &quot;北京&quot;,    street: &quot;朝阳区&quot;,  &#125;,&#125;;

访问 JavaScript 对象的属性console.log(person.name); // 输出: 张三console.log(person.age); // 输出: 20console.log(person.hobbies[0]); // 输出: 篮球console.log(person.address.city); // 输出: 北京

JavaScript 对象与 JSON 字符串的转换JavaScript 中内置了 JSON 对象，提供了两个主要方法：JSON.stringify() 和 JSON.parse()。

JSON.stringify()：将 JavaScript 对象转换为 JSON 字符串
JSON.parse()：将 JSON 字符串解析为 JavaScript 对象

// 创建 JavaScript 对象const person = &#123;  name: &quot;张三&quot;,  age: 20,  hobbies: [&quot;篮球&quot;, &quot;足球&quot;],  address: &#123;    city: &quot;北京&quot;,    street: &quot;朝阳区&quot;,  &#125;,&#125;;// 访问 JavaScript 对象的属性console.log(person.name); // 输出: 张三console.log(person.age); // 输出: 20console.log(person.hobbies[0]); // 输出: 篮球console.log(person.address.city); // 输出: 北京// 将 JavaScript 对象转为 JSON 字符串const personStr = JSON.stringify(person);console.log(personStr); // &#123;&quot;name&quot;:&quot;张三&quot;,&quot;age&quot;:20,&quot;hobbies&quot;:[&quot;篮球&quot;,&quot;足球&quot;],&quot;address&quot;:&#123;&quot;city&quot;:&quot;北京&quot;,&quot;street&quot;:&quot;朝阳区&quot;&#125;&#125;// 将 JSON 字符串转为 JavaScript 对象const studentStr =  &#x27;&#123;&quot;name&quot;:&quot;李四&quot;,&quot;age&quot;:30,&quot;hobbies&quot;:[&quot;篮球&quot;,&quot;足球&quot;],&quot;address&quot;:&#123;&quot;city&quot;:&quot;北京&quot;,&quot;street&quot;:&quot;朝阳区&quot;&#125;&#125;&#x27;;const student = JSON.parse(studentStr);console.log(student);// &#123;//     &quot;name&quot;: &quot;李四&quot;,//     &quot;age&quot;: 30,//     &quot;hobbies&quot;: [//     &quot;篮球&quot;,//     &quot;足球&quot;// ],//     &quot;address&quot;: &#123;//     &quot;city&quot;: &quot;北京&quot;,//         &quot;street&quot;: &quot;朝阳区&quot;// &#125;// &#125;

在 Java 中使用 JSONJava 中没有内置的 JSON 处理库，但有很多第三方库可以使用，如 Jackson、Gson、Fastjson 等。这里使用 Gson 库来演示如何在 Java 中处理 JSON 数据。
gson-2.14.0.jar
public static void jsonToString() &#123;    Person person = new Person(&quot;ID001&quot;, &quot;张三&quot;, 20);    Gson gson = new Gson();    String json = gson.toJson(person);    System.out.println(json);    // &#123;&quot;id&quot;:&quot;ID001&quot;,&quot;name&quot;:&quot;张三&quot;,&quot;age&quot;:20&#125;&#125;public static void stringToJSON() &#123;    String json = &quot;&#123;\&quot;id\&quot;:\&quot;ID002\&quot;,\&quot;name\&quot;:\&quot;李四\&quot;,\&quot;age\&quot;:21&#125;&quot;;    Gson gson = new Gson();    Person person = gson.fromJson(json, Person.class);    System.out.println(person.toString());    // Person&#123;id=&#x27;ID002&#x27;, name=&#x27;李四&#x27;, age=21&#125;&#125;public static void listToString() &#123;    Person person1 = new Person(&quot;ID001&quot;, &quot;张三&quot;, 20);    Person person2 = new Person(&quot;ID002&quot;, &quot;李四&quot;, 21);    Person person3 = new Person(&quot;ID003&quot;, &quot;王五&quot;, 22);    List&lt;Person&gt; personList = List.of(person1, person2, person3);    Gson gson = new Gson();    String json = gson.toJson(personList);    System.out.println(json);    // [&#123;&quot;id&quot;:&quot;ID001&quot;,&quot;name&quot;:&quot;张三&quot;,&quot;age&quot;:20&#125;,&#123;&quot;id&quot;:&quot;ID002&quot;,&quot;name&quot;:&quot;李四&quot;,&quot;age&quot;:21&#125;,&#123;&quot;id&quot;:&quot;ID003&quot;,&quot;name&quot;:&quot;王五&quot;,&quot;age&quot;:22&#125;]    // 若想将 JSON 字符串形式的 List 数据解析为 List 对象，需要定义一个类来继承 TypeToken，并传入目标类型    class PersonListType extends TypeToken&lt;List&lt;Person&gt;&gt; &#123;    &#125;    // 然后传入该类的 type    List&lt;Person&gt; newPersonList = gson.fromJson(json, new PersonListType().getType());    System.out.println(newPersonList.toString());    // [Person&#123;id=&#x27;ID001&#x27;, name=&#x27;张三&#x27;, age=20&#125;, Person&#123;id=&#x27;ID002&#x27;, name=&#x27;李四&#x27;, age=21&#125;, Person&#123;id=&#x27;ID003&#x27;, name=&#x27;王五&#x27;, age=22&#125;]&#125;public static void mapToString() &#123;    Person person1 = new Person(&quot;ID001&quot;, &quot;张三&quot;, 20);    Person person2 = new Person(&quot;ID002&quot;, &quot;李四&quot;, 21);    Person person3 = new Person(&quot;ID003&quot;, &quot;王五&quot;, 22);    Map&lt;String, Person&gt; personMap = Map.of(person1.getId(), person1, person2.getId(), person2, person3.getId(), person3);    Gson gson = new Gson();    String json = gson.toJson(personMap);    System.out.println(json);    // &#123;&quot;ID003&quot;:&#123;&quot;id&quot;:&quot;ID003&quot;,&quot;name&quot;:&quot;王五&quot;,&quot;age&quot;:22&#125;,&quot;ID002&quot;:&#123;&quot;id&quot;:&quot;ID002&quot;,&quot;name&quot;:&quot;李四&quot;,&quot;age&quot;:21&#125;,&quot;ID001&quot;:&#123;&quot;id&quot;:&quot;ID001&quot;,&quot;name&quot;:&quot;张三&quot;,&quot;age&quot;:20&#125;&#125;    // 若想将 JSON 字符串形式的 Map 数据解析为 Map 对象，需要定义一个类来继承 TypeToken，并传入目标类型    class PersonMapType extends TypeToken&lt;Map&lt;String, Person&gt;&gt; &#123;    &#125;    // 然后传入该类的 type    Map&lt;String, Person&gt; newPersonMap = gson.fromJson(json, new PersonMapType().getType());    System.out.println(newPersonMap.toString());    // &#123;ID003=Person&#123;id=&#x27;ID003&#x27;, name=&#x27;王五&#x27;, age=22&#125;, ID002=Person&#123;id=&#x27;ID002&#x27;, name=&#x27;李四&#x27;, age=21&#125;, ID001=Person&#123;id=&#x27;ID001&#x27;, name=&#x27;张三&#x27;, age=20&#125;&#125;&#125;

