测试编写测试代码
@Testpublic void insertTestDemo01() throws IOException &#123;    // 1. 加载配置文件    InputStream inputStream = Resources.getResourceAsStream(&quot;mybatis-config.xml&quot;);    // 2. 获取 SqlSessionFactoryBuilder    SqlSessionFactoryBuilder builder = new SqlSessionFactoryBuilder();    // 3. 获取 SqlSessionFactory    SqlSessionFactory factory = builder.build(inputStream);    // 4. 获取 SqlSession，代表 Java 程序和 SQL 之间的一个会话，通过该会话即可操作数据库    SqlSession session = factory.openSession();    // 5. 获取 Mapper 接口的实例化对象    UserMapper mapper = session.getMapper(UserMapper.class);    // 6. 执行对应的方法    Integer count = mapper.insertUser();    System.out.println(&quot;受影响行数：&quot; + count); // 受影响行数：1    // 7. 因为在配置文件中使用了 JDBC 来管理事务，因此这里需要手动提交    session.commit();    // 8. 关闭流    session.close();    inputStream.close();&#125;

自动提交在获取 SqlSession 的时候，在 openSession() 方法中传入 true，即可实现自动提交事务。
@Testpublic void insertTestDemo01() throws IOException &#123;    // 1. 加载配置文件    InputStream inputStream = Resources.getResourceAsStream(&quot;mybatis-config.xml&quot;);    // 2. 获取 SqlSessionFactoryBuilder    SqlSessionFactoryBuilder builder = new SqlSessionFactoryBuilder();    // 3. 获取 SqlSessionFactory    SqlSessionFactory factory = builder.build(inputStream);    // 4. 获取 SqlSession，传入 true 实现自动提交事务    SqlSession session = factory.openSession(true);    // 5. 获取 Mapper 接口的实例化对象    UserMapper mapper = session.getMapper(UserMapper.class);    // 6. 执行对应的方法    Integer count = mapper.insertUser();    System.out.println(&quot;受影响行数：&quot; + count); // 受影响行数：1    // 7. 关闭流    session.close();    inputStream.close();&#125;

