@Testpublic void selectAll() &#123;    SqlSession sqlSession = SqlSessionUtils.getSqlSession(&quot;mybatis-config.xml&quot;);    EmpMapper mapper = sqlSession.getMapper(EmpMapper.class);    List&lt;Emp&gt; emps = mapper.selectAll();    emps.forEach(System.out::println);    // Emp&#123;id=1, empName=&#x27;张三&#x27;, age=20, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=1&#125;    // Emp&#123;id=2, empName=&#x27;李四&#x27;, age=21, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=2&#125;    // Emp&#123;id=3, empName=&#x27;王五&#x27;, age=22, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=1&#125;    // Emp&#123;id=4, empName=&#x27;赵六&#x27;, age=23, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=2&#125;    // Emp&#123;id=5, empName=&#x27;孙七&#x27;, age=24, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=3&#125;&#125;

解决方法二（mapUnderscoreToCamelCase 配置）通过上面的案例可以发现，数据库中的字段名统一使用下划线命名，而 Java 中则使用驼峰命名，这并非特例，而是普遍现象。因此 MyBatis 为我们提供了一个配置，可以在字段映射时自动将下划线转为驼峰。
参考文档
在 mybatis-config.xml 配置文件中添加如下配置
&lt;settings&gt;    &lt;setting name=&quot;logImpl&quot; value=&quot;STDOUT_LOGGING&quot;/&gt;    &lt;!--        开启驼峰命名自动映射，即从经典数据库列名 A_COLUMN 映射到经典 Java 属性名 aColumn    --&gt;    &lt;setting name=&quot;mapUnderscoreToCamelCase&quot; value=&quot;true&quot;/&gt;&lt;/settings&gt;

删除别名
&lt;select id=&quot;selectAll&quot; resultType=&quot;Emp&quot;&gt;    SELECT * FROM t_emp&lt;/select&gt;

再次查询，发现配置生效了。
@Testpublic void selectAll() &#123;    SqlSession sqlSession = SqlSessionUtils.getSqlSession(&quot;mybatis-config.xml&quot;);    EmpMapper mapper = sqlSession.getMapper(EmpMapper.class);    List&lt;Emp&gt; emps = mapper.selectAll();    emps.forEach(System.out::println);    // Emp&#123;id=1, empName=&#x27;张三&#x27;, age=20, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=1&#125;    // Emp&#123;id=2, empName=&#x27;李四&#x27;, age=21, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=2&#125;    // Emp&#123;id=3, empName=&#x27;王五&#x27;, age=22, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=1&#125;    // Emp&#123;id=4, empName=&#x27;赵六&#x27;, age=23, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=2&#125;    // Emp&#123;id=5, empName=&#x27;孙七&#x27;, age=24, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=3&#125;&#125;

解决方法三（resultMap）方法二虽然可以解决问题，但前提是数据库字段名和实体类属性名必须满足下划线转驼峰的规则。如果两个字段名之间毫无对应关系，该怎么办呢？此时可以使用 resultMap 来自定义映射规则。
&lt;!--    resultMap 自定义映射规则    属性：        id：唯一标识，在 select 标签中通过 resultMap=&quot;id&quot; 使用该映射规则        type：映射关系中实体类的类型--&gt;&lt;resultMap id=&quot;empResultMap&quot; type=&quot;Emp&quot;&gt;    &lt;!--        id 标签用来设置主键的映射关系        属性：            property：实体类字段名            column：数据库字段名    --&gt;    &lt;id property=&quot;id&quot; column=&quot;id&quot;/&gt;    &lt;!--        result 标签用来设置普通字段的映射关系    --&gt;    &lt;result property=&quot;empName&quot; column=&quot;emp_name&quot;/&gt;    &lt;result property=&quot;age&quot; column=&quot;age&quot;/&gt;    &lt;result property=&quot;sex&quot; column=&quot;sex&quot;/&gt;    &lt;result property=&quot;email&quot; column=&quot;email&quot;/&gt;    &lt;result property=&quot;deptId&quot; column=&quot;dept_id&quot;/&gt;&lt;/resultMap&gt;&lt;!--    使用自定义的映射规则--&gt;&lt;select id=&quot;selectAll&quot; resultMap=&quot;empResultMap&quot;&gt;    SELECT * FROM t_emp&lt;/select&gt;

依旧可以生效，记得把配置 mapUnderscoreToCamelCase 注释掉，或者设置为 false。
@Testpublic void selectAll() &#123;    SqlSession sqlSession = SqlSessionUtils.getSqlSession(&quot;mybatis-config.xml&quot;);    EmpMapper mapper = sqlSession.getMapper(EmpMapper.class);    List&lt;Emp&gt; emps = mapper.selectAll();    emps.forEach(System.out::println);    // Emp&#123;id=1, empName=&#x27;张三&#x27;, age=20, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=1&#125;    // Emp&#123;id=2, empName=&#x27;李四&#x27;, age=21, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=2&#125;    // Emp&#123;id=3, empName=&#x27;王五&#x27;, age=22, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=1&#125;    // Emp&#123;id=4, empName=&#x27;赵六&#x27;, age=23, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=2&#125;    // Emp&#123;id=5, empName=&#x27;孙七&#x27;, age=24, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=3&#125;&#125;

动态 SQL参考文档
在实际开发中，SQL 有时并不是固定的，而是动态的，比如某个查询字段，存在就作为查询条件，不存在就不作为条件。在 JDBC 阶段，我们可以通过分支判断、循环等语法来动态地生成 SQL 语句，而 MyBatis 也为我们提供了对应的标签来实现这些功能。
if 标签if 标签同 Java 中的 if 语句逻辑一样：在 test 属性中编写表达式，表达式结果为 true 就拼接标签内的 SQL，反之则不拼接。
创建一个查询员工信息的 SQL 语句，根据传入的参数动态拼接 SQL。
List&lt;Emp&gt; selectAllByCondition(Emp emp);

&lt;select id=&quot;selectAllByCondition&quot; resultType=&quot;Emp&quot;&gt;    SELECT * FROM t_emp WHERE    &lt;if test=&quot;empName != null and empName != &#x27;&#x27;&quot;&gt;        emp_name = #&#123;empName&#125;    &lt;/if&gt;    &lt;if test=&quot;age != null and age != &#x27;&#x27;&quot;&gt;        AND age = #&#123;age&#125;    &lt;/if&gt;    &lt;if test=&quot;sex != null and sex != &#x27;&#x27;&quot;&gt;        AND sex = #&#123;sex&#125;    &lt;/if&gt;    &lt;if test=&quot;email != null and email != &#x27;&#x27;&quot;&gt;        AND email = #&#123;email&#125;    &lt;/if&gt;&lt;/select&gt;

通过测试我们可以发现：当我们传入了 empName 时，SQL 中就拼接了对应的条件，反之其他字段不会被拼接。
@Testpublic void selectEmpWithDept() &#123;    SqlSession sqlSession = SqlSessionUtils.getSqlSession(&quot;mybatis-config.xml&quot;);    DynamicSQLMapper mapper = sqlSession.getMapper(DynamicSQLMapper.class);    Emp emp = new Emp();    emp.setEmpName(&quot;张三&quot;);    List&lt;Emp&gt; emps = mapper.selectAllByCondition(emp);    emps.forEach(System.out::println);    // ==&gt;  Preparing: SELECT * FROM t_emp WHERE emp_name = ?    // ==&gt; Parameters: 张三(String)    // &lt;==    Columns: id, emp_name, age, sex, email, dept_id    // &lt;==        Row: 1, 张三, 20, 男, 1234567890@qq.com, 1    // &lt;==      Total: 1    // Emp&#123;id=1, empName=&#x27;张三&#x27;, age=20, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=1, dept=null&#125;&#125;

但是，当我们把 empName 设置为空，用其他条件查询时，就会报错。可以看到生成的 SQL 语句很奇怪：WHERE 后面直接拼接了 AND。这正是因为 empName 为空，跳过了第一个条件，WHERE 直接和后面的 SQL 拼接了。
Emp emp = new Emp();emp.setSex(&quot;男&quot;);List&lt;Emp&gt; emps = mapper.selectAllByCondition(emp);emps.forEach(System.out::println);// ==&gt;  Preparing: SELECT * FROM t_emp WHERE AND sex = ?// ==&gt; Parameters: 男(String)

解决办法也很简单：只需要在 WHERE 后面添加 1 = 1，这样即使 empName 为 null，拼接后的 SQL 也会是 WHERE 1 = 1 AND age = &#39;男&#39;。
&lt;select id=&quot;selectAllByCondition&quot; resultType=&quot;Emp&quot;&gt;    SELECT * FROM t_emp WHERE 1 = 1    &lt;if test=&quot;empName != null and empName != &#x27;&#x27;&quot;&gt;        AND emp_name = #&#123;empName&#125;    &lt;/if&gt;    &lt;if test=&quot;age != null and age != &#x27;&#x27;&quot;&gt;        AND age = #&#123;age&#125;    &lt;/if&gt;    &lt;if test=&quot;sex != null and sex != &#x27;&#x27;&quot;&gt;        AND sex = #&#123;sex&#125;    &lt;/if&gt;    &lt;if test=&quot;email != null and email != &#x27;&#x27;&quot;&gt;        AND email = #&#123;email&#125;    &lt;/if&gt;&lt;/select&gt;

// ==&gt;  Preparing: SELECT * FROM t_emp WHERE 1 = 1 AND sex = ?// ==&gt; Parameters: 男(String)// &lt;==    Columns: id, emp_name, age, sex, email, dept_id// &lt;==        Row: 1, 张三, 20, 男, 1234567890@qq.com, 1// &lt;==        Row: 4, 赵六, 23, 男, 1234567890@qq.com, 2// &lt;==      Total: 2// Emp&#123;id=1, empName=&#x27;张三&#x27;, age=20, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=1, dept=null&#125;// Emp&#123;id=4, empName=&#x27;赵六&#x27;, age=23, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=2, dept=null&#125;

where 标签上述方式虽然可以实现多条件的动态拼接，但还是比较麻烦的：为了防止拼接出错，还需要额外写上 WHERE 1 = 1。MyBatis 为我们提供了 where 标签，搭配 if 标签使用即可解决该问题：在 where 标签中拼接 SQL 时，如果开头有多余的 AND 或者 OR，它会帮我们删除，就不会再出现 WHERE AND age = &#39;男&#39; 的情况了。
&lt;select id=&quot;selectAllByCondition&quot; resultType=&quot;Emp&quot;&gt;    SELECT * FROM t_emp    &lt;where&gt;        &lt;if test=&quot;empName != null and empName != &#x27;&#x27;&quot;&gt;            AND emp_name = #&#123;empName&#125;        &lt;/if&gt;        &lt;if test=&quot;age != null and age != &#x27;&#x27;&quot;&gt;            AND age = #&#123;age&#125;        &lt;/if&gt;        &lt;if test=&quot;sex != null and sex != &#x27;&#x27;&quot;&gt;            AND sex = #&#123;sex&#125;        &lt;/if&gt;        &lt;if test=&quot;email != null and email != &#x27;&#x27;&quot;&gt;            AND email = #&#123;email&#125;        &lt;/if&gt;    &lt;/where&gt;&lt;/select&gt;

// ==&gt;  Preparing: SELECT * FROM t_emp WHERE sex = ?// ==&gt; Parameters: 男(String)// &lt;==    Columns: id, emp_name, age, sex, email, dept_id// &lt;==        Row: 1, 张三, 20, 男, 1234567890@qq.com, 1// &lt;==        Row: 4, 赵六, 23, 男, 1234567890@qq.com, 2// &lt;==      Total: 2// Emp&#123;id=1, empName=&#x27;张三&#x27;, age=20, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=1, dept=null&#125;// Emp&#123;id=4, empName=&#x27;赵六&#x27;, age=23, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=2, dept=null&#125;

trim 标签如果 where 标签还不能满足需求，那么可以使用 trim 标签，它的自由度更高，允许我们更自由地拼接 SQL。
trim 标签提供了四个属性：



属性
值
作用



prefix
前缀
在整体内容前面添加的字符串


suffix
后缀
在整体内容后面添加的字符串


prefixOverrides
覆盖掉的前缀
如果内容以指定字符串开头，删掉它


suffixOverrides
覆盖掉的后缀
如果内容以指定字符串结尾，删掉它


这样我们便可以写出等价于 where 标签的 SQL 拼接方式。当然，trim 标签的功能不仅于此。
&lt;select id=&quot;selectAllByCondition&quot; resultType=&quot;Emp&quot;&gt;    SELECT * FROM t_emp    &lt;!--        通过 prefix 拼接一个 WHERE        并且去除开头的 AND 或者 OR，避免出现 WHERE AND 的问题     --&gt;    &lt;trim prefix=&quot;WHERE&quot; prefixOverrides=&quot;AND|OR&quot;&gt;        &lt;if test=&quot;empName != null and empName != &#x27;&#x27;&quot;&gt;            AND emp_name = #&#123;empName&#125;        &lt;/if&gt;        &lt;if test=&quot;age != null and age != &#x27;&#x27;&quot;&gt;            AND age = #&#123;age&#125;        &lt;/if&gt;        &lt;if test=&quot;sex != null and sex != &#x27;&#x27;&quot;&gt;            AND sex = #&#123;sex&#125;        &lt;/if&gt;        &lt;if test=&quot;email != null and email != &#x27;&#x27;&quot;&gt;            AND email = #&#123;email&#125;        &lt;/if&gt;    &lt;/trim&gt;&lt;/select&gt;

// ==&gt;  Preparing: SELECT * FROM t_emp WHERE emp_name = ? AND sex = ?// ==&gt; Parameters: 张三(String), 男(String)// &lt;==    Columns: id, emp_name, age, sex, email, dept_id// &lt;==        Row: 1, 张三, 20, 男, 1234567890@qq.com, 1// &lt;==      Total: 1// Emp&#123;id=1, empName=&#x27;张三&#x27;, age=20, sex=&#x27;男&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=1, dept=null&#125;

choose、when、otherwisechoose、when、otherwise 这三个标签需要一起使用，相当于 Java 中的 switch...case...default：当我们编写多个条件时，只要有一个 when 标签中的表达式成立，其余的条件就不会再进行判断；如果所有的 when 标签都不满足，则使用 otherwise。
&lt;select id=&quot;selectAllByCondition&quot; resultType=&quot;Emp&quot;&gt;    SELECT * FROM t_emp    &lt;where&gt;        &lt;choose&gt;            &lt;when test=&quot;empName != null and empName != &#x27;&#x27;&quot;&gt;                AND emp_name = #&#123;empName&#125;            &lt;/when&gt;            &lt;when test=&quot;age != null and age != &#x27;&#x27;&quot;&gt;                AND age = #&#123;age&#125;            &lt;/when&gt;            &lt;when test=&quot;sex != null and sex != &#x27;&#x27;&quot;&gt;                AND sex = #&#123;sex&#125;            &lt;/when&gt;            &lt;when test=&quot;email != null and email != &#x27;&#x27;&quot;&gt;                AND email = #&#123;email&#125;            &lt;/when&gt;            &lt;otherwise&gt;                AND dept_id = 1            &lt;/otherwise&gt;        &lt;/choose&gt;    &lt;/where&gt;&lt;/select&gt;

foreachforeach 标签相当于 Java 中的 for 语句，可以根据传入的 List 集合循环拼接 SQL 语句。



