Integer deleteAll(@Param(&quot;deptIdList&quot;) List&lt;Integer&gt; deptIdList);

&lt;delete id=&quot;deleteAll&quot;&gt;    DELETE FROM t_emp WHERE id IN    &lt;foreach collection=&quot;deptIdList&quot; item=&quot;deptId&quot; open=&quot;(&quot; close=&quot;)&quot; separator=&quot;,&quot;&gt;        #&#123;deptId&#125;    &lt;/foreach&gt;&lt;/delete&gt;

@Testpublic void deleteAll() &#123;    SqlSession sqlSession = SqlSessionUtils.getSqlSession(&quot;mybatis-config.xml&quot;);    DynamicSQLMapper mapper = sqlSession.getMapper(DynamicSQLMapper.class);    Integer i = mapper.deleteAll(List.of(6, 7, 8, 9));    System.out.println(i);  // 4&#125;

注意：使用这种方式，一定要先判断集合是否为空。在下面的写法中，如果集合为空，&lt;where&gt; 中就没有任何内容，SQL 会退化成 DELETE FROM t_emp，造成全表删除，所以最好在 Java 层面判断集合为空时就不执行删除。
&lt;delete id=&quot;deleteAll&quot;&gt;    DELETE FROM t_emp    &lt;where&gt;        &lt;foreach collection=&quot;deptIdList&quot; item=&quot;deptId&quot; open=&quot;id IN (&quot; close=&quot;)&quot; separator=&quot;,&quot;&gt;            #&#123;deptId&#125;        &lt;/foreach&gt;    &lt;/where&gt;&lt;/delete&gt;

// ==&gt;  Preparing: DELETE FROM t_emp// ==&gt; Parameters:// &lt;==    Updates: 6

