@Testpublic void insertBatch() &#123;    SqlSession sqlSession = SqlSessionUtils.getSqlSession(&quot;mybatis-config.xml&quot;);    DynamicSQLMapper mapper = sqlSession.getMapper(DynamicSQLMapper.class);    Emp emp1 = new Emp(null, &quot;1&quot;, 1, &quot;1&quot;, &quot;1&quot;, 1);    Emp emp2 = new Emp(null, &quot;1&quot;, 1, &quot;1&quot;, &quot;1&quot;, 1);    Emp emp3 = new Emp(null, &quot;1&quot;, 1, &quot;1&quot;, &quot;1&quot;, 1);    Emp emp4 = new Emp(null, &quot;1&quot;, 1, &quot;1&quot;, &quot;1&quot;, 1);    Emp emp5 = new Emp(null, &quot;1&quot;, 1, &quot;1&quot;, &quot;1&quot;, 1);    Integer i = mapper.insertBatch(List.of(emp1, emp2, emp3, emp4, emp5));    System.out.println(i);    // ==&gt;  Preparing: INSERT INTO t_emp VALUES ( NULL, ?, ?, ?, ?, ? ) , ( NULL, ?, ?, ?, ?, ? ) , ( NULL, ?, ?, ?, ?, ? ) , ( NULL, ?, ?, ?, ?, ? ) , ( NULL, ?, ?, ?, ?, ? )    // ==&gt; Parameters: 1(String), 1(Integer), 1(String), 1(String), 1(Integer), 1(String), 1(Integer), 1(String), 1(String), 1(Integer), 1(String), 1(Integer), 1(String), 1(String), 1(Integer), 1(String), 1(Integer), 1(String), 1(String), 1(Integer), 1(String), 1(Integer), 1(String), 1(String), 1(Integer)    // &lt;==    Updates: 5&#125;

sql、includesql 标签可以将我们常用的 SQL 语句定义为 SQL 片段，当我们编写 SQL 时可以通过 include 标签来引用该片段，减少工作量。
&lt;sql id=&quot;empColumns&quot;&gt;id, emp_name, age, sex, email&lt;/sql&gt;&lt;select id=&quot;selectAllByCondition&quot; resultType=&quot;Emp&quot;&gt;    SELECT    &lt;include refid=&quot;empColumns&quot;/&gt;    FROM t_emp&lt;/select&gt;

// SELECT id, emp_name, age, sex, email FROM t_emp

多对一在多对一的情况下，只需要在多的那一方（Emp）的实体类中，添加一个一方（Dept）的对象即可。
public class Emp &#123;    private Integer id;    private String empName;    private Integer age;    private String sex;    private String email;    private Integer deptId;    // 创建一个部门对象    private Dept dept;    // Getter And Setter......&#125;

解决方法一（对象.属性名）使用连接查询将员工信息和对应的部门信息都查出来。
&lt;select id=&quot;selectEmpWithDept&quot; resultMap=&quot;empWithDeptResultMap&quot;&gt;    SELECT        *    FROM        t_emp    LEFT OUTER JOIN t_dept        ON t_dept.id = t_emp.dept_id    WHERE        t_emp.id = #&#123;id&#125;&lt;/select&gt;

&lt;resultMap id=&quot;empWithDeptResultMap&quot; type=&quot;Emp&quot;&gt;    &lt;id property=&quot;id&quot; column=&quot;id&quot;/&gt;    &lt;result property=&quot;empName&quot; column=&quot;emp_name&quot;/&gt;    &lt;result property=&quot;age&quot; column=&quot;age&quot;/&gt;    &lt;result property=&quot;sex&quot; column=&quot;sex&quot;/&gt;    &lt;result property=&quot;email&quot; column=&quot;email&quot;/&gt;    &lt;result property=&quot;deptId&quot; column=&quot;dept_id&quot;/&gt;    &lt;!--        通过 对象.属性名 的方式来为实体类中的对象定义映射规则     --&gt;    &lt;result property=&quot;dept.deptId&quot; column=&quot;dept_id&quot;/&gt;    &lt;result property=&quot;dept.deptName&quot; column=&quot;dept_name&quot;/&gt;&lt;/resultMap&gt;

@Testpublic void selectEmpWithDept() &#123;    SqlSession sqlSession = SqlSessionUtils.getSqlSession(&quot;mybatis-config.xml&quot;);    EmpMapper mapper = sqlSession.getMapper(EmpMapper.class);    Emp emp = mapper.selectEmpWithDept(5);    System.out.println(emp);    // Emp&#123;id=5, empName=&#x27;孙七&#x27;, age=24, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=3, dept=Dept&#123;deptId=3, deptName=&#x27;C&#x27;&#125;&#125;&#125;

解决方法二（association）使用 association 标签来为实体类中的对象创建映射关系。
&lt;resultMap id=&quot;empWithDeptResultMap&quot; type=&quot;Emp&quot;&gt;    &lt;id property=&quot;id&quot; column=&quot;id&quot;/&gt;    &lt;result property=&quot;empName&quot; column=&quot;emp_name&quot;/&gt;    &lt;result property=&quot;age&quot; column=&quot;age&quot;/&gt;    &lt;result property=&quot;sex&quot; column=&quot;sex&quot;/&gt;    &lt;result property=&quot;email&quot; column=&quot;email&quot;/&gt;    &lt;result property=&quot;deptId&quot; column=&quot;dept_id&quot;/&gt;    &lt;!--        association 为实体类中的对象创建映射关系        属性：            property：实体类中该对象的变量名            javaType：实体类中该对象的类型    --&gt;    &lt;association property=&quot;dept&quot; javaType=&quot;Dept&quot;&gt;        &lt;result property=&quot;deptId&quot; column=&quot;dept_id&quot;/&gt;        &lt;result property=&quot;deptName&quot; column=&quot;dept_name&quot;/&gt;    &lt;/association&gt;&lt;/resultMap&gt;

@Testpublic void selectEmpWithDept() &#123;    SqlSession sqlSession = SqlSessionUtils.getSqlSession(&quot;mybatis-config.xml&quot;);    EmpMapper mapper = sqlSession.getMapper(EmpMapper.class);    Emp emp = mapper.selectEmpWithDept(5);    System.out.println(emp);    // Emp&#123;id=5, empName=&#x27;孙七&#x27;, age=24, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=3, dept=Dept&#123;deptId=3, deptName=&#x27;C&#x27;&#125;&#125;&#125;

解决方法三（association + 分步查询）上述案例都只使用了一条 SQL。除此之外，我们还可以把 SQL 拆分，分别查询员工信息和对应的部门信息，这种方式称之为分步查询。
需要先在 DeptMapper 中定义好查询方法。
public interface DeptMapper &#123;    Dept selectOne(@Param(&quot;deptId&quot;) Integer deptId);&#125;

&lt;resultMap id=&quot;deptResultMap&quot; type=&quot;Dept&quot;&gt;    &lt;id property=&quot;deptId&quot; column=&quot;dept_id&quot;/&gt;    &lt;result property=&quot;deptName&quot; column=&quot;dept_name&quot;/&gt;&lt;/resultMap&gt;&lt;select id=&quot;selectOne&quot; resultMap=&quot;deptResultMap&quot;&gt;    SELECT * FROM t_dept WHERE dept_id = #&#123;deptId&#125;&lt;/select&gt;

然后在 EmpMapper 中只查询员工信息，再通过 association 标签的 select 属性去调用 DeptMapper 中查询部门的方法即可。
&lt;!--    在 EmpMapper 中只查询员工信息 --&gt;&lt;resultMap id=&quot;empWithDeptResultMap&quot; type=&quot;Emp&quot;&gt;    &lt;id property=&quot;id&quot; column=&quot;id&quot;/&gt;    &lt;result property=&quot;empName&quot; column=&quot;emp_name&quot;/&gt;    &lt;result property=&quot;age&quot; column=&quot;age&quot;/&gt;    &lt;result property=&quot;sex&quot; column=&quot;sex&quot;/&gt;    &lt;result property=&quot;email&quot; column=&quot;email&quot;/&gt;    &lt;result property=&quot;deptId&quot; column=&quot;dept_id&quot;/&gt;    &lt;!--        属性：            select：通过全类名调用另一个 Mapper 中的方法，使用返回值填充对象     --&gt;    &lt;association property=&quot;dept&quot; column=&quot;dept_id&quot; javaType=&quot;Dept&quot; select=&quot;com.lasyc.mapper.DeptMapper.selectOne&quot;/&gt;&lt;/resultMap&gt;&lt;select id=&quot;selectEmpWithDept&quot; resultMap=&quot;empWithDeptResultMap&quot;&gt;    SELECT * FROM t_emp WHERE id = #&#123;id&#125;&lt;/select&gt;

@Testpublic void selectEmpWithDept() &#123;    SqlSession sqlSession = SqlSessionUtils.getSqlSession(&quot;mybatis-config.xml&quot;);    EmpMapper mapper = sqlSession.getMapper(EmpMapper.class);    Emp emp = mapper.selectEmpWithDept(5);    // ==&gt;  Preparing: SELECT * FROM t_emp WHERE id = ?    // ==&gt; Parameters: 5(Integer)    // &lt;==    Columns: id, emp_name, age, sex, email, dept_id    // &lt;==        Row: 5, 孙七, 24, 女, 1234567890@qq.com, 3    // ====&gt;  Preparing: SELECT * FROM t_dept WHERE dept_id = ?    // ====&gt; Parameters: 3(Integer)    // &lt;====    Columns: dept_id, dept_name    // &lt;====        Row: 3, C    // &lt;====      Total: 1    // &lt;==      Total: 1    System.out.println(emp);    // Emp&#123;id=5, empName=&#x27;孙七&#x27;, age=24, sex=&#x27;女&#x27;, email=&#x27;1234567890@qq.com&#x27;, deptId=3, dept=Dept&#123;deptId=3, deptName=&#x27;C&#x27;&#125;&#125;&#125;

延迟加载在上面的多对一中，我们通过分步查询解决了问题。这种方式还可以降低 SQL 之间的耦合：将一个 SQL 拆分为两个，提高了 SQL 的复用性，两个 SQL 都可以独立执行，既能查询员工信息，也能查询部门信息。
但前提是必须在 MyBatis 中开启延迟加载。开启后，执行查询员工信息的 SQL 时只会查询员工信息；当代码中调用了 emp.getDept() 来获取部门信息时，才会触发延迟加载，此时才去查询部门信息。



