JDBCUtils 完整版package com.xxxxxx.utils;import java.io.IOException;import java.io.InputStream;import java.lang.reflect.Field;import java.sql.*;import java.util.ArrayList;import java.util.List;import java.util.Properties;/** * 数据库工具类 * * @author Lasyc * @version 1.0 * @since 2025-12-17 */public class JDBCUtils &#123;    /**     * 数据库URL     */    private static final String url;    /**     * 数据库用户名     */    private static final String user;    /**     * 数据库密码     */    private static final String password;    /**     * 数据库驱动类名     */    private static final String driver;    static &#123;        try &#123;            // 读取配置文件            InputStream inputStream = ClassLoader.getSystemClassLoader().getResourceAsStream(&quot;jdbc.properties&quot;);            // 加载配置文件中的参数            Properties properties = new Properties();            properties.load(inputStream);            // 设置数据库连接信息            url = properties.getProperty(&quot;url&quot;);            user = properties.getProperty(&quot;user&quot;);            password = properties.getProperty(&quot;password&quot;);            driver = properties.getProperty(&quot;driver&quot;);            // 加载数据库驱动            Class.forName(driver);        &#125; catch (IOException | ClassNotFoundException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;    /**     * 私有构造方法，防止实例化     */    private JDBCUtils() &#123;    &#125;    /**     * 获取数据库连接对象     *     * @return 数据库连接对象     */    public static Connection getConnection() &#123;        try &#123;            // 通过DriverManager获取数据库连接并返回            return DriverManager.getConnection(url, user, password);        &#125; catch (SQLException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;    /**     * 关闭数据库连接和 Statement 资源     *     * @param connection 数据库连接     * @param statement  Statement 或 PreparedStatement 对象     */    public static void close(Connection connection, Statement statement) &#123;        close(connection, statement, null);    &#125;    /**     * 关闭数据库连接、Statement 和 ResultSet 资源     *     * @param connection 数据库连接     * @param statement  Statement 或 PreparedStatement 对象     * @param resultSet  结果集对象     */    public static void close(Connection connection, Statement statement, ResultSet resultSet) &#123;        try &#123;            // 关闭资源            if (resultSet != null) resultSet.close();            if (statement != null) statement.close();            if (connection != null) connection.close();        &#125; catch (SQLException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;    /**     * 执行更新操作（INSERT、UPDATE、DELETE）     *     * @param sql    SQL语句，可以包含占位符&quot;?&quot;     * @param params 参数数组，用于替换 SQL 中的占位符     * @return 受影响的行数     */    public static int executeUpdate(String sql, Object... params) &#123;        Connection connection = null;        PreparedStatement preparedStatement = null;        try &#123;            // 获取连接            connection = getConnection();            // 创建 SQL            preparedStatement = connection.prepareStatement(sql);            // 设置参数            for (int i = 0; i &lt; params.length; i++) &#123;                preparedStatement.setObject(i + 1, params[i]);            &#125;            // 返回结果            return preparedStatement.executeUpdate();        &#125; catch (SQLException e) &#123;            throw new RuntimeException(e);        &#125; finally &#123;            // 关闭资源            close(connection, preparedStatement);        &#125;    &#125;    /**     * 执行查询操作     *     * @param clazz  查询结果对应类     * @param sql    SQL语句，可以包含占位符&quot;?&quot;     * @param params 参数数组，用于替换 SQL 中的占位符     * @param &lt;T&gt;    泛型     * @return 查询结果     */    public static &lt;T&gt; List&lt;T&gt; executeQuery(Class&lt;T&gt; clazz, String sql, Object... params) &#123;        Connection connection = null;        PreparedStatement preparedStatement = null;        ResultSet resultSet = null;        try &#123;            // 获取连接            connection = getConnection();            // 创建 SQL            preparedStatement = connection.prepareStatement(sql);            // 设置参数            for (int i = 0; i &lt; params.length; i++) &#123;                preparedStatement.setObject(i + 1, params[i]);            &#125;            // 执行 SQL 并获取结果集            resultSet = preparedStatement.executeQuery();            // 通过结果集获取元数据            ResultSetMetaData metaData = resultSet.getMetaData();            // 获取结果集的列数            int columnCount = metaData.getColumnCount();            // 创建集合，用于保存结果            List&lt;T&gt; list = new ArrayList&lt;&gt;();            // 遍历结果集            while (resultSet.next()) &#123;                // 通过反射创建对象                T obj = clazz.getDeclaredConstructor().newInstance();                // 遍历所有列                for (int i = 0; i &lt; columnCount; i++) &#123;                    // 获取列名                    String columnName = metaData.getColumnLabel(i + 1);                    // 将列名转换为属性名                    String fieldName = convertColumnNameToFieldName(columnName);                    // 通过属性名获取属性                    Field field = obj.getClass().getDeclaredField(fieldName);                    // 设置可以访问                    field.setAccessible(true);                    // 获取该列的值                    Object value = resultSet.getObject(i + 1);                    // 通过反射设置值                    field.set(obj, value);                &#125;                // 将记录添加到集合                list.add(obj);            &#125;            // 返回结果            return list;        &#125; catch (Exception e) &#123;            throw new RuntimeException(e);        &#125; finally &#123;            // 关闭资源            close(connection, preparedStatement, resultSet);        &#125;    &#125;    /**     * 下划线转为小驼峰     *     * @param columnName 列名     * @return 字段名     */    private static String convertColumnNameToFieldName(String columnName) &#123;        if (columnName == null || columnName.isEmpty()) return null;        if (!columnName.contains(&quot;_&quot;)) return columnName;        String[] split = columnName.split(&quot;_&quot;);        StringBuilder fieldName = new StringBuilder(split[0]);        for (int i = 1; i &lt; split.length; i++) &#123;            fieldName.append(split[i].substring(0, 1).toUpperCase()).append(split[i].substring(1));        &#125;        return fieldName.toString();    &#125;&#125;

