CREATE TABLE tb_user(    id          INT AUTO_INCREMENT PRIMARY KEY,    username    VARCHAR(10) NOT NULL,    password    VARCHAR(30) NOT NULL,    create_time DATETIME    NOT NULL);

// User.javapackage com.xxxxxx.preparedStatement;import java.time.LocalDateTime;public class User &#123;    private int id;    private String username;    private String password;    private LocalDateTime createTime;    public User() &#123;    &#125;    public User(int id, String username, String password, LocalDateTime createTime) &#123;        this.id = id;        this.username = username;        this.password = password;        this.createTime = createTime;    &#125;    public int getId() &#123;        return id;    &#125;    public void setId(int id) &#123;        this.id = id;    &#125;    public String getUsername() &#123;        return username;    &#125;    public void setUsername(String username) &#123;        this.username = username;    &#125;    public String getPassword() &#123;        return password;    &#125;    public void setPassword(String password) &#123;        this.password = password;    &#125;    public LocalDateTime getCreateTime() &#123;        return createTime;    &#125;    public void setCreateTime(LocalDateTime createTime) &#123;        this.createTime = createTime;    &#125;    @Override    public String toString() &#123;        return &quot;User&#123;&quot; +                &quot;id=&quot; + id +                &quot;, username=&#x27;&quot; + username + &#x27;\&#x27;&#x27; +                &quot;, password=&#x27;&quot; + password + &#x27;\&#x27;&#x27; +                &quot;, createTime=&quot; + createTime +                &#x27;&#125;&#x27;;    &#125;&#125;

查询我们可以尝试编写一个简单的查询语句，只是针对于 tb_user 这个表
// 查询数据User user = JDBCUtils.executeQuery(&quot;select * from tb_user&quot;);System.out.println(user);

public static User executeQuery(String sql, Object... params) &#123;    Connection connection = null;    PreparedStatement preparedStatement = null;    ResultSet resultSet = null;    try &#123;        // 获取连接        connection = getConnection();        // 创建 SQL        preparedStatement = connection.prepareStatement(sql);        // 设置参数        for (int i = 0; i &lt; params.length; i++) &#123;            preparedStatement.setObject(i + 1, params[i]);        &#125;        // 执行 SQL 并获取结果集        resultSet = preparedStatement.executeQuery();        User user = null;        if (resultSet.next()) &#123;            int id = resultSet.getInt(&quot;id&quot;);            String username = resultSet.getString(&quot;username&quot;);            String password = resultSet.getString(&quot;password&quot;);            // 这里获取到的类型是 LocalDateTime，所以用 Object 接收并强转            Object createTime = resultSet.getObject(&quot;create_time&quot;);            user = new User(id, username, password, (LocalDateTime)createTime);        &#125;        // 返回结果        return user;    &#125; catch (Exception e) &#123;        throw new RuntimeException(e);    &#125; finally &#123;        // 关闭资源        close(connection, preparedStatement, resultSet);    &#125;&#125;

在上边的代码中，我们已知返回 id、username、password、createTime 四个字段，因此可以执行四次 resultSet.getXXX() 方法来获取每列的值，但是如果我们不知道 SQL 语句中具体查询了哪几列呢？
这是，我们可以通过 ResultSet 来获取元数据，在元数据中，保存了具体的列数和列名
 // 获取元数据ResultSetMetaData metaData = resultSet.getMetaData();// 获取列数int columnCount = metaData.getColumnCount();User user = null;if (resultSet.next()) &#123;    user = new User();    // 遍历每一列    for (int i = 0; i &lt; columnCount; i++) &#123;        // 获取值，因为不知道每一列的类型，所以使用 Object        Object object = resultSet.getObject(i + 1);        // ......    &#125;&#125;

新的问题出现了：我们虽然能拿到列的个数和值，但不知道每一列对应哪个属性、值该设置到哪个属性上。
前面提到过，列名和属性名是存在对应关系的，如 id → id、username → username、create_time → createTime。因此可以先获取列名，再通过反射把值设置到对应的属性中
User user = null;if (resultSet.next()) &#123;    user = new User();    // 遍历每一列    for (int i = 0; i &lt; columnCount; i++) &#123;        // 获取值，因为不知道每一列的类型，所以使用 Object        Object value = resultSet.getObject(i + 1);        // 获取列名        String columnName = metaData.getColumnName(i + 1);        // 通过列名获取属性        Field declaredField = user.getClass().getDeclaredField(columnName);        // 设置可以访问        declaredField.setAccessible(true);        // 设置值        declaredField.set(user, value);    &#125;&#125;

此时，执行程序时会报错：java.lang.NoSuchFieldException: create_time，因为需要先把 create_time 转成 createTime 才能匹配到属性，这时有两种办法：

在 SQL 中给列起别名（如 create_time AS createTime），同时用 getColumnLabel 代替 getColumnName 获取列名——前者获取的是别名
// 起别名User user= JDBCUtils.executeQuery(&quot;select id, username, create_time AS createTime from tb_user&quot;);

// 改为 getColumnLabel 获取列名String columnName = metaData.getColumnLabel(i + 1);

自己编写一个方法，把 xxx_xxx 下划线命名转为 xxxXxx 小驼峰命名
 // 获取列名String columnName = metaData.getColumnLabel(i + 1);// 获取属性名String fieldName = convertColumnNameToFieldName(columnName);// 通过列名获取属性Field declaredField = user.getClass().getDeclaredField(fieldName);

/** * 下划线转为小驼峰 * * @param columnName 列名 * @return 字段名 */private static String convertColumnNameToFieldName(String columnName) &#123;    if (columnName == null || columnName.isEmpty()) return null;    if (!columnName.contains(&quot;_&quot;)) return columnName;    String[] split = columnName.split(&quot;_&quot;);    StringBuilder fieldName = new StringBuilder(split[0]);    for (int i = 1; i &lt; split.length; i++) &#123;        fieldName.append(split[i].substring(0, 1).toUpperCase()).append(split[i].substring(1));    &#125;    return fieldName.toString();&#125;

但上面的方法只能查询 tb_user、返回 User，太局限。返回值不应仅限于某一个类，所以可以借助泛型 + 反射来动态创建对象：传入哪个类，就返回哪个类型的对象
User user = JDBCUtils.executeQuery(User.class, &quot;select * from tb_user&quot;);System.out.println(user);

public static &lt;T&gt; T executeQuery(Class&lt;T&gt; clazz, String sql, Object... params) &#123;    Connection connection = null;    PreparedStatement preparedStatement = null;    ResultSet resultSet = null;    try &#123;        // 获取连接        connection = getConnection();        // 创建 SQL        preparedStatement = connection.prepareStatement(sql);        // 设置参数        for (int i = 0; i &lt; params.length; i++) &#123;            preparedStatement.setObject(i + 1, params[i]);        &#125;        // 执行 SQL 并获取结果集        resultSet = preparedStatement.executeQuery();        // 获取元数据        ResultSetMetaData metaData = resultSet.getMetaData();        // 获取列数        int columnCount = metaData.getColumnCount();        T obj = null;        if (resultSet.next()) &#123;            obj = clazz.getDeclaredConstructor().newInstance();            // 遍历每一列            for (int i = 0; i &lt; columnCount; i++) &#123;                // 获取值，因为不知道每一列的类型，所以使用 Object                Object value = resultSet.getObject(i + 1);                // 获取列名                String columnName = metaData.getColumnLabel(i + 1);                // 获取属性名                String fieldName = convertColumnNameToFieldName(columnName);                // 通过列名获取属性                Field declaredField = obj.getClass().getDeclaredField(fieldName);                // 设置可以访问                declaredField.setAccessible(true);                // 设置值                declaredField.set(obj, value);            &#125;        &#125;        // 返回结果        return obj;    &#125; catch (Exception e) &#123;        throw new RuntimeException(e);    &#125; finally &#123;        // 关闭资源        close(connection, preparedStatement, resultSet);    &#125;&#125;

以上的查询通用代码已经接近完美，但是只能返回一个对象，此时再使用 List&lt;T&gt; 来接收结果并返回，便可以实现查询多个结果的功能
List&lt;User&gt; users = JDBCUtils.executeQuery(User.class, &quot;select * from tb_user&quot;);for (User user : users) &#123;    System.out.println(user);&#125;

/** * 执行查询操作 * * @param clazz  查询结果对应类 * @param sql    SQL语句，可以包含占位符&quot;?&quot; * @param params 参数数组，用于替换 SQL 中的占位符 * @param &lt;T&gt;    泛型 * @return 查询结果 */public static &lt;T&gt; List&lt;T&gt; executeQuery(Class&lt;T&gt; clazz, String sql, Object... params) &#123;    Connection connection = null;    PreparedStatement preparedStatement = null;    ResultSet resultSet = null;    try &#123;        // 获取连接        connection = getConnection();        // 创建 SQL        preparedStatement = connection.prepareStatement(sql);        // 设置参数        for (int i = 0; i &lt; params.length; i++) &#123;            preparedStatement.setObject(i + 1, params[i]);        &#125;        // 执行 SQL 并获取结果集        resultSet = preparedStatement.executeQuery();        // 通过结果集获取元数据        ResultSetMetaData metaData = resultSet.getMetaData();        // 获取结果集的列数        int columnCount = metaData.getColumnCount();        // 创建集合，用于保存结果        List&lt;T&gt; list = new ArrayList&lt;&gt;();        // 遍历结果集        while (resultSet.next()) &#123;            // 通过反射创建对象            T obj = clazz.getDeclaredConstructor().newInstance();            // 遍历所有列            for (int i = 0; i &lt; columnCount; i++) &#123;                // 获取列名                String columnName = metaData.getColumnLabel(i + 1);                // 将列名转换为属性名                String fieldName = convertColumnNameToFieldName(columnName);                // 通过属性名获取属性                Field field = obj.getClass().getDeclaredField(fieldName);                // 设置可以访问                field.setAccessible(true);                // 获取该列的值                Object value = resultSet.getObject(i + 1);                // 通过反射设置值                field.set(obj, value);            &#125;            // 将记录添加到集合            list.add(obj);        &#125;        // 返回结果        return list;    &#125; catch (Exception e) &#123;        throw new RuntimeException(e);    &#125; finally &#123;        // 关闭资源        close(connection, preparedStatement, resultSet);    &#125;&#125;

事务介绍事务（Transaction）是一组操作的集合，是不可分割的工作单位：事务中的操作要么全部成功，要么全部失败。JDBC 中默认是自动提交模式，每执行一条 SQL 都会立即提交；但当一组操作需要作为一个整体（比如转账）时，就必须手动控制事务的提交与回滚。ACID 特性、隔离级别等完整概念可以回顾本系列《MySQL 事务》一文
JDBC 引入事务在介绍事务的时候，使用最多的问题就是转账问题，在理想状态下，A 向 B 转账 1000 元，需要两步操作，即扣除 A 1000 元，增加 B 1000 元
// A -&gt; B 转账String sql1 = &quot;UPDATE tb_user SET balance = balance - ? WHERE username = ?&quot;;int updateFlag1 = JDBCUtils.executeUpdate(sql1, 1000, &quot;AAA&quot;);System.out.println(updateFlag1);    // 1// B 接收String sql2 = &quot;UPDATE tb_user SET balance = balance + ? WHERE username = ?&quot;;int updateFlag2 = JDBCUtils.executeUpdate(sql2, 1000, &quot;BBB&quot;);System.out.println(updateFlag2);    // 1

然而上述代码只是理想情况，并没有引入事务。转账必须保证”扣 A”与”加 B”要么都成功、要么都失败，否则只要两步之间出现任何问题（比如第一步执行后程序异常中断、第二步没执行），就会出现”钱扣了却没到账”的业务问题，下面用异常来模拟这种情况：
// A -&gt; B 转账String sql1 = &quot;UPDATE tb_user SET balance = balance - ? WHERE username = ?&quot;;int updateFlag1 = JDBCUtils.executeUpdate(sql1, 1000, &quot;AAA&quot;);System.out.println(updateFlag1);    // 1// 假设转帐中出现问题int a = 1 / 0;  // Exception in thread &quot;main&quot; java.lang.ArithmeticException: / by zero// B 接收String sql2 = &quot;UPDATE tb_user SET balance = balance + ? WHERE username = ?&quot;;int updateFlag2 = JDBCUtils.executeUpdate(sql2, 1000, &quot;BBB&quot;);System.out.println(updateFlag2);

因此，需要把上面两步操作放进同一个事务中。默认情况下执行 DML 是自动提交的——每一条 UPDATE 都自成事务，无法把两步绑在一起。所以我们需要关闭自动提交（setAutoCommit(false)），并让两步操作在同一次连接中执行，最后统一提交或回滚
为此给 JDBCUtils 添加一个接收连接的重载方法：事务要求使用同一个连接对象，所以要把连接作为参数传进来；同时在这个方法里不要关闭连接（连接要留到事务提交&#x2F;回滚之后统一关闭）
/** * 带事务执行更新操作（INSERT、UPDATE、DELETE） * * @param connection 数据库连接对象 * @param sql        SQL语句，可以包含占位符&quot;?&quot; * @param params     参数数组，用于替换 SQL 中的占位符 * @return 受影响的行数 */public static int executeUpdate(Connection connection, String sql, Object... params) &#123;    PreparedStatement preparedStatement = null;    try &#123;        // 创建 SQL        preparedStatement = connection.prepareStatement(sql);        // 设置参数        for (int i = 0; i &lt; params.length; i++) &#123;            preparedStatement.setObject(i + 1, params[i]);        &#125;        // 返回结果        return preparedStatement.executeUpdate();    &#125; catch (SQLException e) &#123;        throw new RuntimeException(e);    &#125; finally &#123;        // 关闭资源，不要关闭连接        close(null, preparedStatement);    &#125;&#125;

调用方自己获取连接、关闭自动提交，再把连接传给上面的事务版方法；全部成功后手动 commit()，任何一步抛异常则在 catch 中 rollback()。注意：直接 close() 连接时，未提交的事务会被回滚而不是提交，所以不要指望”关连接来提交”，提交&#x2F;回滚必须显式完成
Connection connection = null;try &#123;    // 获取连接    connection = JDBCUtils.getConnection();    // 关闭自动提交    connection.setAutoCommit(false);    // A -&gt; B 转账    String sql1 = &quot;UPDATE tb_user SET balance = balance - ? WHERE username = ?&quot;;    int updateFlag1 = JDBCUtils.executeUpdate(connection, sql1, 1000, &quot;AAA&quot;);    System.out.println(updateFlag1);    // 假设转帐中出现问题    int a = 1 / 0;    // B 接收    String sql2 = &quot;UPDATE tb_user SET balance = balance + ? WHERE username = ?&quot;;    int updateFlag2 = JDBCUtils.executeUpdate(connection, sql2, 1000, &quot;BBB&quot;);    System.out.println(updateFlag2);    // 提交事务    connection.commit();&#125; catch (Exception e) &#123;    // 发生异常回滚    try &#123;        if (connection != null) connection.rollback();    &#125; catch (SQLException ex) &#123;        throw new RuntimeException(ex);    &#125;    throw new RuntimeException(e);&#125; finally &#123;    // 恢复自动提交    try &#123;        if (connection != null) connection.setAutoCommit(true);    &#125; catch (SQLException e) &#123;        throw new RuntimeException(e);    &#125;    // 关闭连接    JDBCUtils.close(connection);&#125;

ACID
原子性（Atomicity）：事务是一个不可分割的最小工作单位，事务中的操作要么全部成功，要么全部失败
一致性（Consistency）：事务必须使数据从一个状态到另一个状态，且始终保持一致
隔离性（Isolation）：多个事务之间互不干扰
持久性（Durability）：事务一旦提交，对数据的修改就是永久性的，不会因为系统崩溃等原因而丢失

事务并发问题
脏读：事务 A 修改了数据但未提交，事务 B 读到了这份”半成品”数据；随后 A 回滚，B 之前读到的就是不存在的数据
不可重复读：事务 B 内两次读取同一行数据，期间事务 A 修改并提交了该行，导致 B 两次读到的结果不一致
幻读：事务 B 内两次查询同一范围的数据，期间事务 A 插入了满足条件的新行并提交，导致 B 第二次查询多出一些”凭空出现”的行

隔离级别MySQL 默认隔离级别为可重复读，隔离级别越高，越安全，但是并发性能越差



隔离级别
问题



READ UNCOMMITTED（读未提交）
会发生脏读、不可重复读、幻读


READ COMMITTED（读已提交）
解决脏读问题，但会发生不可重复读、幻读


REPEATABLE READ（可重复读）
解决脏读、不可重复读问题，但会发生幻读


SERIALIZABLE（串行化）
解决全部问题，不会发生任何问题


