不可重复读通过 JDBC 将隔离级别修改为 READ COMMITTED，可以避免脏读问题，但是还会有不可重复读问题
// 解决脏读public static void main(String[] args) &#123;    // 在代码中通过 JDBC 将隔离级别修改为 READ COMMITTED（见 transaction01）    // 开启两个线程分别执行两个事务    new Thread(Isolation02::transaction01).start();    new Thread(Isolation02::transaction02).start();&#125;private static void transaction01() &#123;    // 事务 T1    Connection connection = null;    try &#123;        // 获取连接        connection = JDBCUtils.getConnection();        // 关闭自动提交        connection.setAutoCommit(false);        // 修改隔离级别        connection.setTransactionIsolation(Connection.TRANSACTION_READ_COMMITTED);        // 查看当前的隔离级别        // System.out.println(connection.getTransactionIsolation());        // SQL        String sql = &quot;SELECT username, password, create_time, balance FROM tb_user WHERE username = ?&quot;;        // 执行 SQL        List&lt;User&gt; users = JDBCUtils.executeQuery(connection, User.class, sql, &quot;AAA&quot;);        users.forEach(System.out::println);        // 等待事务 T2 修改数据        Thread.sleep(1000);        // 执行 SQL        List&lt;User&gt; newUsers = JDBCUtils.executeQuery(connection, User.class, sql, &quot;AAA&quot;);        newUsers.forEach(System.out::println);        // 提交事务        // connection.commit();    &#125; catch (Exception e) &#123;        throw new RuntimeException(e);    &#125; finally &#123;        // JDBCUtils.close(connection);    &#125;&#125;private static void transaction02() &#123;    // 事务 T2    Connection connection = null;    try &#123;        // 等待事务 T1 查询        Thread.sleep(500);        // 获取连接        connection = JDBCUtils.getConnection();        // 关闭自动提交        connection.setAutoCommit(false);        // SQL        String sql = &quot;UPDATE tb_user SET balance = balance - ? WHERE username = ?&quot;;        // 执行 SQL        int i = JDBCUtils.executeUpdate(connection, sql, 100, &quot;AAA&quot;);        System.out.println(i);        // 提交事务        // connection.commit();    &#125; catch (Exception e) &#123;        throw new RuntimeException(e);    &#125; finally &#123;        // JDBCUtils.close(connection);    &#125;&#125;

// User&#123;id=0, username=&#x27;AAA&#x27;, password=&#x27;123456&#x27;, createTime=2025-12-19T20:47:35, balance=500&#125;// 1// User&#123;id=0, username=&#x27;AAA&#x27;, password=&#x27;123456&#x27;, createTime=2025-12-19T20:47:35, balance=500&#125;

// 不可重复读public static void main(String[] args) &#123;    // 在代码中通过 JDBC 将隔离级别修改为 READ COMMITTED（见 transaction01）    // 开启两个线程分别执行两个事务    new Thread(Isolation03::transaction01).start();    new Thread(Isolation03::transaction02).start();&#125;private static void transaction01() &#123;    // 事务 T1    Connection connection = null;    try &#123;        // 获取连接        connection = JDBCUtils.getConnection();        // 关闭自动提交        connection.setAutoCommit(false);        // 修改隔离级别        connection.setTransactionIsolation(Connection.TRANSACTION_READ_COMMITTED);        // 查看当前的隔离级别        // System.out.println(connection.getTransactionIsolation());        // SQL        String sql = &quot;SELECT username, password, create_time, balance FROM tb_user WHERE username = ?&quot;;        // 执行 SQL        List&lt;User&gt; users = JDBCUtils.executeQuery(connection, User.class, sql, &quot;AAA&quot;);        users.forEach(System.out::println);        // 等待事务 T2 修改数据        Thread.sleep(1000);        // 执行 SQL        List&lt;User&gt; newUsers = JDBCUtils.executeQuery(connection, User.class, sql, &quot;AAA&quot;);        newUsers.forEach(System.out::println);        // 提交事务        // connection.commit();    &#125; catch (Exception e) &#123;        throw new RuntimeException(e);    &#125; finally &#123;        // JDBCUtils.close(connection);    &#125;&#125;private static void transaction02() &#123;    // 事务 T2    Connection connection = null;    try &#123;        // 等待事务 T1 查询        Thread.sleep(500);        // 获取连接        connection = JDBCUtils.getConnection();        // 关闭自动提交        connection.setAutoCommit(false);        // SQL        String sql = &quot;UPDATE tb_user SET balance = balance - ? WHERE username = ?&quot;;        // 执行 SQL        int i = JDBCUtils.executeUpdate(connection, sql, 100, &quot;AAA&quot;);        System.out.println(i);        // 提交事务            connection.commit();    &#125; catch (Exception e) &#123;        throw new RuntimeException(e);    &#125; finally &#1