幻读将隔离级别修改为 REPEATABLE READ（代码中通过 setTransactionIsolation 设置）可以解决不可重复读的问题：示例中两次查询结果一致，说明读到了同一个快照。这也是 MySQL 默认的隔离级别，能满足绝大部分场景。

补充：真正的幻读指事务内两次查询同一范围，期间其他事务插入了新行并提交，导致第二次查询多出数据。在 InnoDB 的 RR 级别下，快照读 + 间隙锁已经能基本避免幻读，这里主要演示”可重复读”的效果。

public static void main(String[] args) &#123;    // 在代码中通过 JDBC 将隔离级别修改为 REPEATABLE READ（见 transaction01）    // 开启两个线程分别执行两个事务    new Thread(Isolation03::transaction01).start();    new Thread(Isolation03::transaction02).start();&#125;private static void transaction01() &#123;    // 事务 T1    Connection connection = null;    try &#123;        // 获取连接        connection = JDBCUtils.getConnection();        // 关闭自动提交        connection.setAutoCommit(false);        // 修改隔离级别        connection.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);        // 查看当前的隔离级别        // System.out.println(connection.getTransactionIsolation());        // SQL        String sql = &quot;SELECT username, password, create_time, balance FROM tb_user WHERE username = ?&quot;;        // 执行 SQL        List&lt;User&gt; users = JDBCUtils.executeQuery(connection, User.class, sql, &quot;AAA&quot;);        users.forEach(System.out::println);        // 等待事务 T2 修改数据        Thread.sleep(1000);        // 执行 SQL        List&lt;User&gt; newUsers = JDBCUtils.executeQuery(connection, User.class, sql, &quot;AAA&quot;);        newUsers.forEach(System.out::println);        // 提交事务        // connection.commit();    &#125; catch (Exception e) &#123;        throw new RuntimeException(e);    &#125; finally &#123;        // JDBCUtils.close(connection);    &#125;&#125;private static void transaction02() &#123;    // 事务 T2    Connection connection = null;    try &#123;        // 等待事务 T1 查询        Thread.sleep(500);        // 获取连接        connection = JDBCUtils.getConnection();        // 关闭自动提交        connection.setAutoCommit(false);        // SQL        String sql = &quot;UPDATE tb_user SET balance = balance - ? WHERE username = ?&quot;;        // 执行 SQL        int i = JDBCUtils.executeUpdate(connection, sql, 100, &quot;AAA&quot;);        System.out.println(i);        // 提交事务            connection.commit();    &#125; catch (Exception e) &#123;        throw new RuntimeException(e);    &#125; finally &#123;            JDBCUtils.close(connection);    &#125;&#125;

// User&#123;id=0, username=&#x27;AAA&#x27;, password=&#x27;123456&#x27;, createTime=2025-12-19T20:47:35, balance=200&#125;// 1// User&#123;id=0, username=&#x27;AAA&#x27;, password=&#x27;123456&#x27;, createTime=2025-12-19T20:47:35, balance=200&#125;

