// JDBCUtils.javapackage com.xxxxxx.utils;import java.io.IOException;import java.io.InputStream;import java.sql.*;import java.util.Properties;/** * 数据库工具类 * * @author xxxxxx * @version 1.0 * @since 2025-12-17 */public class JDBCUtils &#123;    /**     * 数据库URL     */    private static final String url;    /**     * 数据库用户名     */    private static final String user;    /**     * 数据库密码     */    private static final String password;    /**     * 数据库驱动类名     */    private static final String driver;    static &#123;        try &#123;            // 读取配置文件            InputStream inputStream = ClassLoader.getSystemClassLoader().getResourceAsStream(&quot;jdbc.properties&quot;);            // 加载配置文件中的参数            Properties properties = new Properties();            properties.load(inputStream);            // 设置数据库连接信息            url = properties.getProperty(&quot;url&quot;);            user = properties.getProperty(&quot;user&quot;);            password = properties.getProperty(&quot;password&quot;);            driver = properties.getProperty(&quot;driver&quot;);            // 加载数据库驱动            Class.forName(driver);        &#125; catch (IOException | ClassNotFoundException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;    /**     * 私有构造方法，防止实例化     */    private JDBCUtils() &#123;    &#125;    /**     * 获取数据库连接对象     *     * @return 数据库连接对象     */    public static Connection getConnection() &#123;        try &#123;            // 通过DriverManager获取数据库连接并返回            return DriverManager.getConnection(url, user, password);        &#125; catch (SQLException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;    /**     * 关闭数据库连接     *     * @param connection 数据库连接     */    public static void close(Connection connection) &#123;        close(connection, null, null);    &#125;    /**     * 关闭数据库连接和 Statement 资源     *     * @param connection 数据库连接     * @param statement  Statement 或 PreparedStatement 对象     */    public static void close(Connection connection, Statement statement) &#123;        close(connection, statement, null);    &#125;    /**     * 关闭数据库连接、Statement 和 ResultSet 资源     *     * @param connection 数据库连接     * @param statement  Statement 或 PreparedStatement 对象     * @param resultSet  结果集对象     */    public static void close(Connection connection, Statement statement, ResultSet resultSet) &#123;        try &#123;            // 关闭资源            if (resultSet != null) resultSet.close();            if (statement != null) statement.close();            if (connection != null) connection.close();        &#125; catch (SQLException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;&#125;

// BaseDao.javapackage com.xxxxxx.basedao;import com.xxxxxx.utils.JDBCUtils;import java.lang.reflect.Field;import java.lang.reflect.ParameterizedType;import java.lang.reflect.Type;import java.sql.*;import java.util.ArrayList;import java.util.List;/** * 提供数据库表的通用操作（CRUD） * * @author xxxxxx * @version 1.0 * @since 2025-12-20 */public abstract class BaseDao&lt;E&gt; &#123;    private final Class&lt;E&gt; clazz;    public BaseDao() &#123;        // 虽然写在父类中，但是这里的 this 指向的是子类        Type genericSuperclass = this.getClass().getGenericSuperclass();        ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();        clazz = (Class&lt;E&gt;) actualTypeArguments[0];    &#125;    /**     * 带事务执行更新操作     *     * @param connection 数据库连接对象     * @param sql        SQL语句，可以包含占位符&quot;?&quot;     * @param params     参数数组，用于替换 SQL 中的占位符     * @return 受影响的行数     */    public int update(Connection connection, String sql, Object... params) &#123;        PreparedStatement preparedStatement = null;        try &#123;            // 创建 SQL            preparedStatement = connection.prepareStatement(sql);            // 设置参数            for (int i = 0; i &lt; params.length; i++) &#123;                preparedStatement.setObject(i + 1, params[i]);            &#125;            // 返回结果            return preparedStatement.executeUpdate();        &#125; catch (SQLException e) &#123;            throw new RuntimeException(e);        &#125; finally &#123;            // 关闭资源，不要关闭连接            JDBCUtils.close(null, preparedStatement);        &#125;    &#125;    /**     * 查询操作（单条记录）     *     * @param connection 数据库连接对象     * @param sql        SQL语句，可以包含占位符&quot;?&quot;     * @param params     参数数组，用于替换 SQL 中的占位符     * @return 查询结果     */    public E selectOne(Connection connection, String sql, Object... params) &#123;        List&lt;E&gt; resultList = selectList(connection, sql, params);        // get(0)：返回第一条记录（getFirst() 需要 Java 21+，这里用 get(0) 兼容性更好）        return resultList.isEmpty() ? null : resultList.get(0);    &#125;    /**     * 查询操作（多条记录）     *     * @param connection 数据库连接对象     * @param sql        SQL语句，可以包含占位符&quot;?&quot;     * @param params     参数数组，用于替换 SQL 中的占位符     * @return 查询结果     */    public List&lt;E&gt; selectList(Connection connection, String sql, Object... params) &#123;        PreparedStatement preparedStatement = null;        ResultSet resultSet = null;        try &#123;            // 创建 SQL            preparedStatement = connection.prepareStatement(sql);            // 设置参数            for (int i = 0; i &lt; params.length; i++) &#123;                preparedStatement.setObject(i + 1, params[i]);            &#125;            // 执行 SQL 并获取结果集            resultSet = preparedStatement.executeQuery();            // 通过结果集获取元数据            ResultSetMetaData metaData = resultSet.getMetaData();            // 获取结果集的列数            int columnCount = metaData.getColumnCount();            // 创建集合，用于保存结果            List&lt;E&gt; list = new ArrayList&lt;&gt;();            // 遍历结果集            while (resultSet.next()) &#123;                // 通过反射创建对象                E obj = clazz.getDeclaredConstructor().newInstance();                // 遍历所有列                for (int i = 0; i &lt; columnCount; i++) &#123;                    // 获取列名                    String columnName = metaData.getColumnLabel(i + 1);                    // 将列名转换为属性名                    String fieldName = convertColumnNameToFieldName(columnName);                    // 通过属性名获取属性                    Field field = obj.getClass().getDeclaredField(fieldName);                    // 设置可以访问                    field.setAccessible(true);                    // 获取该列的值                    Object value = resultSet.getObject(i + 1);                    // 通过反射设置值                    field.set(obj, value);                &#125;                // 将记录添加到集合                list.add(obj);            &#125;            // 返回结果            return list;        &#125; catch (Exception e) &#123;            throw new RuntimeException(e);        &#125; finally &#123;            // 关闭资源            JDBCUtils.close(null, preparedStatement, resultSet);        &#125;    &#125;    /**     * 聚合查询     *     * @param connection 数据库连接对象     * @param sql        SQL语句，可以包含占位符&quot;?&quot;     * @param params     参数数组，用于替换 SQL 中的占位符     * @param &lt;T&gt;        返回值类型     * @return 查询结果     */    public &lt;T&gt; T scalar(Connection connection, Class&lt;T&gt; clazz, String sql, Object... params) &#123;        PreparedStatement preparedStatement = null;        ResultSet resultSet = null;        try &#123;            // 创建 SQL            preparedStatement = connection.prepareStatement(sql);            // 设置参数            for (int i = 0; i &lt; params.length; i++) &#123;                preparedStatement.setObject(i + 1, params[i]);            &#125;            // 执行 SQL 并获取结果集            resultSet = preparedStatement.executeQuery();            // 遍历结果集            if (resultSet.next()) &#123;                Object object = resultSet.getObject(1);                return clazz.isInstance(object) ? clazz.cast(object) : null;            &#125;        &#125; catch (Exception e) &#123;            throw new RuntimeException(e);        &#125; finally &#123;            // 关闭资源（resultSet 也要关闭）            JDBCUtils.close(null, preparedStatement, resultSet);        &#125;        return null;    &#125;    /**     * 下划线转为小驼峰     *     * @param columnName 列名     * @return 字段名     */    private String convertColumnNameToFieldName(String columnName) &#123;        if (columnName == null || columnName.isEmpty()) return null;        if (!columnName.contains(&quot;_&quot;)) return columnName;        String[] split = columnName.split(&quot;_&quot;);        StringBuilder fieldName = new StringBuilder(split[0]);        for (int i = 1; i &lt; split.length; i++) &#123;            fieldName.append(split[i].substring(0, 1).toUpperCase()).append(split[i].substring(1));        &#125;        return fieldName.toString();    &#125;&#125;

// UserDao.javapackage com.xxxxxx.basedao;import java.math.BigDecimal;import java.sql.Connection;import java.util.List;public interface UserDao &#123;    /**     * 插入用户     *     * @param connection 数据库连接对象     * @param user       用户对象     */    int insert(Connection connection, User user);    /**     * 删除用户     *     * @param connection 数据库连接对象     * @param id         删除对象 ID     */    int delete(Connection connection, Integer id);    /**     * 修改用户     *     * @param connection 数据库连接对象     * @param user       用户对象     */    int update(Connection connection, User user);    /**     * 查询用户通过 ID     *     * @param connection 数据库连接对象     * @param id         用户 ID     * @return 查询结果     */    User selectOneById(Connection connection, Integer id);    /**     * 查询用户通过用户名     *     * @param connection 数据库连接对象     * @param username   用户名     * @return 查询结果     */    User selectOneByUsername(Connection connection, String username);    /**     * 查询用户     *     * @param connection 数据库连接对象     * @return 查询结果     */    List&lt;User&gt; selectList(Connection connection);    /**     * 查询表中记录数     *     * @param connection 数据库连接对象     * @return 记录数     */    Long count(Connection connection);    /**     * 获取最大存款金额     *     * @param connection 数据库连接对象     * @return 最大存款金额     */    Integer getMaxBalance(Connection connection);    /**     * 获取平均存款金额     *     * @param connection 数据库连接对象     * @return 平均存款金额     */    BigDecimal getAvgBalance(Connection connection);&#125;

// UserDaoImpl.javapackage com.xxxxxx.basedao.impl;import com.xxxxxx.basedao.BaseDao;import com.xxxxxx.basedao.User;import com.xxxxxx.basedao.UserDao;import java.math.BigDecimal;import java.sql.Connection;import java.util.List;public class UserDaoImpl extends BaseDao&lt;User&gt; implements UserDao &#123;    @Override    public int insert(Connection connection, User user) &#123;        String sql = &quot;INSERT INTO tb_user(username, password, create_time, balance) VALUES(?, ?, ?, ?)&quot;;        return update(connection, sql, user.getUsername(), user.getPassword(), user.getCreateTime(), user.getBalance());    &#125;    @Override    public int delete(Connection connection, Integer id) &#123;        String sql = &quot;DELETE FROM tb_user WHERE id = ?&quot;;        return update(connection, sql, id);    &#125;    @Override    public int update(Connection connection, User user) &#123;        String sql = &quot;UPDATE tb_user SET username = ?, password = ?, create_time = ?, balance = ? WHERE id = ?&quot;;        return update(connection, sql, user.getUsername(), user.getPassword(), user.getCreateTime(), user.getBalance(), user.getId());    &#125;    @Override    public User selectOneById(Connection connection, Integer id) &#123;        String sql = &quot;SELECT id, username, password, create_time, balance FROM tb_user WHERE id = ?&quot;;        return selectOne(connection, sql, id);    &#125;    @Override    public User selectOneByUsername(Connection connection, String username) &#123;        String sql = &quot;SELECT id, username, password, create_time, balance FROM tb_user WHERE username = ?&quot;;        return selectOne(connection, sql, username);    &#125;    @Override    public List&lt;User&gt; selectList(Connection connection) &#123;        String sql = &quot;SELECT id, username, password, create_time, balance FROM tb_user;&quot;;        return selectList(connection, sql);    &#125;    @Override    public Long count(Connection connection) &#123;        String sql = &quot;SELECT COUNT(*) FROM tb_user;&quot;;        return scalar(connection, Long.class, sql);    &#125;    @Override    public Integer getMaxBalance(Connection connection) &#123;        String sql = &quot;SELECT MAX(balance) FROM tb_user;&quot;;        return scalar(connection, Integer.class, sql);    &#125;    @Override    public BigDecimal getAvgBalance(Connection connection) &#123;        String sql = &quot;SELECT AVG(balance) FROM tb_user;&quot;;        return scalar(connection, BigDecimal.class, sql);    &#125;&#125;

