package com.xxxxxx.utils;import com.mchange.v2.c3p0.ComboPooledDataSource;import java.sql.Connection;import java.sql.ResultSet;import java.sql.SQLException;import java.sql.Statement;/** * 数据库工具类 * * @author xxxxxx * @version 1.0 * @since 2025-12-17 */public class JDBCUtils &#123;    /**     * 数据库连接池     */    private static final ComboPooledDataSource comboPooledDataSource;    static &#123;        // 使用配置文件创建数据库连接池        comboPooledDataSource = new ComboPooledDataSource();    &#125;    /**     * 私有构造方法，防止实例化     */    private JDBCUtils() &#123;    &#125;    /**     * 获取数据库连接对象     *     * @return 数据库连接对象     */    public static Connection getConnection() &#123;        // C3P0        try &#123;            // 获取连接            return comboPooledDataSource.getConnection();        &#125; catch (Exception e) &#123;            throw new RuntimeException(e);        &#125;    &#125;    /**     * 关闭数据库连接和 Statement 资源     *     * @param connection 数据库连接     */    public static void close(Connection connection) &#123;        close(connection, null, null);    &#125;    /**     * 关闭数据库连接和 Statement 资源     *     * @param connection 数据库连接     * @param statement  Statement 或 PreparedStatement 对象     */    public static void close(Connection connection, Statement statement) &#123;        close(connection, statement, null);    &#125;    /**     * 关闭数据库连接、Statement 和 ResultSet 资源     *     * @param connection 数据库连接     * @param statement  Statement 或 PreparedStatement 对象     * @param resultSet  结果集对象     */    public static void close(Connection connection, Statement statement, ResultSet resultSet) &#123;        try &#123;            // 关闭资源            if (resultSet != null) resultSet.close();            if (statement != null) statement.close();            if (connection != null) connection.close();        &#125; catch (SQLException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;&#125;

