esultSet) &#123;        try &#123;            // 关闭资源            if (resultSet != null) resultSet.close();            if (statement != null) statement.close();            if (connection != null) connection.close();        &#125; catch (SQLException e) &#123;            throw new RuntimeException(e);        &#125;    &#125;&#125;

