查看 SQL 语句的执行频次：SHOW [SESSION|GLOBAL] STATUS LIKE &#39;Com______&#39;;
查看慢查询日志：SHOW VARIABLES LIKE &#39;%slow_query_log%&#39;;、cat /var/log/mysql/mysql-slow.log
查看 Profile 详情：SHOW PROFILES;、SHOW PROFILE FOR QUERY [QUERY_ID];
查看 SQL 语句的执行计划：EXPLAIN 查询语句;

IFIF 语句用于判断某个条件，并执行相应的语句
IF 条件1 THEN    语句1;[ELSEIF 条件2 THEN]    语句2;[ELSEIF 条件3 THEN]    语句3;......[ELSE]    语句n;END IF;

CREATE PROCEDURE p3()BEGIN    DECLARE score INT DEFAULT 58;    DECLARE level VARCHAR(10);    IF score &gt;= 85 THEN        SET level := &#x27;优秀&#x27;;    ELSEIF score &gt;= 60 THEN        SET level := &#x27;合格&#x27;;    ELSE        SET level := &#x27;不合格&#x27;;    END IF;    SELECT level;END;CALL p3();

存储过程传参


参数类型
参数方向



IN
输入参数


OUT
输出参数


INOUT
输入输出参数


-- 创建存储过程CREATE PROCEDURE p4(IN score INT, OUT level VARCHAR(10))BEGIN    IF score &gt;= 85 THEN        SET level := &#x27;优秀&#x27;;    ELSEIF score &gt;= 60 THEN        SET level := &#x27;合格&#x27;;    ELSE        SET level := &#x27;不合格&#x27;;    END IF;END;-- 调用存储过程，并传递参数，然后将返回结果放入 @level 中CALL p4(60, @level);-- 查看 @levelSELECT @level;

CASECASE 语句用于判断某个条件，并执行相应的语句
CASE valueWHEN 值1 THEN 语句1;WHEN 值2 THEN 语句2;WHEN 值3 THEN 语句3;...WHEN 值n THEN 语句n;ELSE 语句n+1;END CASE;

CASE    WHEN 表达式1 THEN 语句1;    WHEN 表达式2 THEN 语句2;    WHEN 表达式3 THEN 语句3;    ...    WHEN 表达式n THEN 语句n;    ELSE 语句n+1;END CASE;

CREATE PROCEDURE p5(IN month INT, OUT season VARCHAR(10))BEGIN    CASE month        WHEN 1 THEN SET season = &#x27;第一季度&#x27;;        WHEN 2 THEN SET season = &#x27;第一季度&#x27;;        WHEN 3 THEN SET season = &#x27;第一季度&#x27;;        WHEN 4 THEN SET season = &#x27;第二季度&#x27;;        WHEN 5 THEN SET season = &#x27;第二季度&#x27;;        WHEN 6 THEN SET season = &#x27;第二季度&#x27;;        WHEN 7 THEN SET season = &#x27;第三季度&#x27;;        WHEN 8 THEN SET season = &#x27;第三季度&#x27;;        WHEN 9 THEN SET season = &#x27;第三季度&#x27;;        WHEN 10 THEN SET season = &#x27;第四季度&#x27;;        WHEN 11 THEN SET season = &#x27;第四季度&#x27;;        WHEN 12 THEN SET season = &#x27;第四季度&#x27;;        ELSE SET season = NULL;        END CASE;END;CALL p5(1, @season);SELECT @season;

WHILEWHILE 循环用于重复执行一段代码，直到条件为假
WHILE 条件 DO    语句;END WHILE;

CREATE PROCEDURE p6(IN num INT, OUT res INT)BEGIN    SET res := 0;    WHILE num &gt; 0        DO            SET res := res + num;            SET num := num - 1;        END WHILE;END;CALL p6(100, @res);SELECT @res;

REPEATREPEAT 循环用于重复执行一段代码，直到条件为真但是 REPEAT 循环至少会执行一次
REPEAT    语句;    UNTIL 条件    END REPEAT;

CREATE PROCEDURE p7(IN num INT, OUT res INT)BEGIN    SET res := 0;    REPEAT        SET res := res + num;        SET num := num - 1;    UNTIL num = 0        END REPEAT;END;CALL p7(10, @res);SELECT @res;

LOOPLOOP 循环用于重复执行一段代码，直到条件为假但是 LOOP 必须配合 LEAVE 和 ITERATE 使用

LEAVE 用于退出循环
ITERATE 用于跳过当前循环，继续下一次循环

[label:] LOOP    语句;    [LEAVE label;] -- 退出循环    [ITERATE label;] -- 跳过当前循环，继续下一次循环END LOOP [label];

CREATE PROCEDURE p8(IN num INT, OUT res INT)BEGIN    SET res := 0;    loop_sum:    LOOP        IF num &lt;= 0 THEN            LEAVE loop_sum;        END IF;        IF MOD(num, 2) &lt;&gt; 1 THEN            SET num = num - 1;            ITERATE loop_sum;        END IF;        SET res = res + num;        SET num = num - 1;    END LOOP loop_sum;END;CALL p8(100, @res);SELECT @res;

CURSOR（游标）普通的变量一次只能存一个值。当查询结果有多行、需要逐行处理时（例如把查询出的每一行都插入另一张表），就要用到游标（CURSOR）：它像一个指针，可以一行一行地遍历查询结果

创建 CURSOR

DECLARE 游标名 CURSOR FOR 查询语句;


打开 CURSOR

OPEN 游标名;


获取 CURSOR 的结果

FETCH 游标名 INTO 变量;


关闭 CURSOR

CLOSE 游标名;



CREATE PROCEDURE p1(IN user_age INT)BEGIN    DECLARE user_name VARCHAR(10);    DECLARE user_profession VARCHAR(10);    DECLARE user_cursor CURSOR FOR SELECT tb_user.name, tb_user.profession FROM tb_user WHERE age &lt;= user_age;    DROP TABLE IF EXISTS tb_user_profession;    CREATE TABLE IF NOT EXISTS tb_user_profession    (        id         INT AUTO_INCREMENT PRIMARY KEY COMMENT &#x27;ID&#x27;,        name       VARCHAR(10) UNIQUE COMMENT &#x27;姓名&#x27;,        profession VARCHAR(10) COMMENT &#x27;专业&#x27;    );    OPEN user_cursor;    -- 注意：这里是死循环！FETCH 取完所有数据后还会继续取，直到报错，需要用下面的&quot;条件处理&quot;来终止循环    WHILE TRUE        DO            FETCH user_cursor INTO user_name, user_profession;            INSERT INTO tb_user_profession(name, profession) VALUES (user_name, user_profession);        END WHILE;    CLOSE user_cursor;END;CALL p1(25);

条件处理（Handler）条件处理程序（Handler）用来处理 SQL 运行过程中出现的错误或特殊状态，作用类似 Java 的 try-catch：当语句出错（或取不到数据）时，可以选择忽略错误继续执行，也可以提前退出。

创建条件处理程序

DECLARE {CONTINUE | EXIT} HANDLER FOR 错误条件 处理语句;


处理方式（二选一）：

CONTINUE：发生错误&#x2F;状态后忽略它，继续执行后面的语句
EXIT：发生错误&#x2F;状态后立即退出当前的 BEGIN…END 块（存储过程&#x2F;函数）


错误条件（多个用逗号分隔）：

SQLSTATE &#39;状态码&#39;：匹配指定的 SQLSTATE 状态码，如 &#39;02000&#39; 表示”没有找到数据”
SQLWARNING：匹配所有以 01 开头的警告
NOT FOUND：匹配所有以 02 开头的状态（典型就是 FETCH 游标取不到数据）
SQLEXCEPTION：匹配除警告、NOT FOUND 以外的其他所有错误



CREATE PROCEDURE p1(IN user_age INT)BEGIN    DECLARE user_name VARCHAR(10);    DECLARE user_profession VARCHAR(10);    DECLARE user_cursor CURSOR FOR SELECT tb_user.name, tb_user.profession FROM tb_user WHERE age &lt;= user_age;    -- 当 FETCH 取不到数据（SQLSTATE &#x27;02000&#x27;，即 NOT FOUND）时，先关闭游标再退出存储过程，从而终止上面的死循环    DECLARE EXIT HANDLER FOR SQLSTATE &#x27;02000&#x27; CLOSE user_cursor;    DROP TABLE IF EXISTS tb_user_profession;    CREATE TABLE IF NOT EXISTS tb_user_profession    (        id         INT AUTO_INCREMENT PRIMARY KEY COMMENT &#x27;ID&#x27;,        name       VARCHAR(10) UNIQUE COMMENT &#x27;姓名&#x27;,        profession VARCHAR(10) COMMENT &#x27;专业&#x27;    );    OPEN user_cursor;    WHILE TRUE        DO            FETCH user_cursor INTO user_name, user_profession;            INSERT INTO tb_user_profession(name, profession) VALUES (user_name, user_profession);        END WHILE;    CLOSE user_cursor;END;CALL p1(25);

存储函数存储函数和存储过程类似，但是存储函数返回一个值，且存储函数只能有输入参数
CREATE FUNCTION 存储函数名(参数列表) RETURNS 返回值数据类型 [DETERMINISTIC | NO SQL | READS SQL DATA | MODIFIES SQL DATA]BEGIN    函数体;    RETURN 返回值;END;-- DETERMINISTIC：声明函数是确定性的——同样的输入一定产生同样的输出-- NO SQL：函数不会执行任何 SQL 语句-- READS SQL DATA：函数只读取数据库中的数据，不会修改数据-- MODIFIES SQL DATA：函数会修改数据库中的数据

CREATE FUNCTION fun_sum(num INT) RETURNS INT DETERMINISTICBEGIN    DECLARE res INT DEFAULT 0;    WHILE num &gt; 0        DO            SET res := res + num;            SET num := num - 1;        END WHILE;    RETURN res;END;SELECT fun_sum(100);

触发器触发器（Trigger）是一种与表关联的数据库对象：在指定的表上执行 INSERT、UPDATE、DELETE 之前（BEFORE）或之后（AFTER），触发器会自动执行一段 SQL，不需要手动调用
使用触发器
创建触发器

CREATE TRIGGER 触发器名 [BEFORE | AFTER] [INSERT | UPDATE | DELETE] ON 表名 FOR EACH ROW BEGIN 触发器体; END;


查看触发器

SHOW TRIGGERS;


删除触发器

DROP TRIGGER [表名.]触发器名;



练习创建 user_log 表，记录用户操作日志
-- 创建 user_log 表CREATE TABLE user_logs(    id               INT(11)     NOT NULL AUTO_INCREMENT PRIMARY KEY COMMENT &#x27;ID&#x27;,    operation_type   VARCHAR(20) NOT NULL COMMENT &#x27;操作类型&#x27;,    operation_time   DATETIME    NOT NULL COMMENT &#x27;操作时间&#x27;,    operation_id     INT(11)     NOT NULL COMMENT &#x27;操作ID&#x27;,    operation_params VARCHAR(512) COMMENT &#x27;操作参数&#x27;);-- 创建触发器CREATE TRIGGER insert_trigger    BEFORE INSERT    ON tb_user    FOR EACH ROWBEGIN    INSERT INTO user_logs(operation_type, operation_time, operation_id, operation_params)    VALUES (&#x27;INSERT&#x27;,            NOW(),            new.id,            CONCAT(new.id, new.name, new.phone, new.email, new.profession, new.age, new.gender, new.status,                   new.create_time));END;-- 查看触发器SHOW TRIGGERS;-- 删除触发器DROP TRIGGER insert_trigger;-- 测试触发器INSERT INTO tb_user(name, phone, email, profession, age, gender, status, create_time)VALUES (&#x27;哪吒&#x27;, 17799990025, &#x27;nezha666@sina.com&#x27;, &#x27;计算机科学&#x27;, 22, 2, 0, &#x27;2025-11-26 19:32:30&#x27;);-- 查看日志表SELECT * FROM user_logs;-- 1,INSERT,2025-12-08 19:42:50,0,0哪吒17799990025nezha666@sina.com计算机科学22202025-11-26 19:32:30

-- UPDATECREATE TRIGGER update_trigger    BEFORE UPDATE    ON tb_user    FOR EACH ROWBEGIN    INSERT INTO user_logs(operation_type, operation_time, operation_id, operation_params)    VALUES (&#x27;UPDATE&#x27;,            NOW(),            new.id,            CONCAT(old.id, old.name, old.phone, old.email, old.profession, old.age, old.gender, old.status,                   old.create_time, new.id, new.name, new.phone, new.email, new.profession, new.age, new.gender,                   new.status,                   new.create_time));END;UPDATE tb_user SET profession = &#x27;软件工程&#x27; WHERE id = 27;-- 影响了两条数据，所以触发器会执行两次UPDATE tb_user SET profession = &#x27;化工&#x27; WHERE id &lt; 3;

-- DELETECREATE TRIGGER delete_trigger    BEFORE DELETE    ON tb_user    FOR EACH ROWBEGIN    INSERT INTO user_logs(operation_type, operation_time, operation_id, operation_params)    VALUES (&#x27;DELETE&#x27;,            NOW(),            old.id,            CONCAT(old.id, old.name, old.phone, old.email, old.profession, old.age, old.gender, old.status,                   old.create_time));END;DELETEFROM tb_userWHERE id = 27;

总结
视图（VIEW）：数据库中的虚拟表，本身不存数据，查询时动态从基础表取数
存储过程（PROCEDURE）：事先封装好的一组 SQL，用 CALL 调用，可接收 IN&#x2F;OUT&#x2F;INOUT 参数、包含流程控制
存储函数（FUNCTION）：与存储过程类似，但必须返回一个值，且只有输入参数，常用于封装计算逻辑
触发器（TRIGGER）：与表绑定，在 INSERT &#x2F; UPDATE &#x2F; DELETE 前后自动触发执行

视图视图介绍视图（View）是一种虚拟存在的表，它本身不存储数据，本质上是基于一条 SQL 查询语句的结果集：每次查询视图时，都会动态地从基础表中取最新数据。使用视图可以简化复杂的查询、提高数据安全性（隐藏敏感字段），相当于给数据加了一层抽象
视图基本使用
创建视图

CREATE [OR REPLACE] VIEW 视图名 AS 查询语句 [WITH [CASCADED | LOCAL] CHECK OPTION];


查看全部视图

SHOW FULL TABLES WHERE Table_type &#x3D; ‘VIEW’;


查看指定视图的定义

SHOW CREATE VIEW 视图名;


查看视图数据

SELECT * FROM 视图名;


修改视图

CREATE OR REPLACE VIEW 视图名 AS 新的查询语句 [WITH [CASCADED | LOCAL] CHECK OPTION];


ALTER VIEW 视图名 AS 新的查询语句 [WITH [CASCADED | LOCAL] CHECK OPTION];


删除视图

DROP VIEW [IF EXISTS] 视图名;



-- 创建视图CREATE OR REPLACE VIEW user_view_1 ASSELECT *FROM tb_userWHERE profession = &#x27;软件工程&#x27;WITH LOCAL CHECK OPTION;-- 查看全部视图SHOW FULL TABLES WHERE Table_type = &#x27;VIEW&#x27;;-- 查看指定视图SHOW CREATE VIEW user_view_1;-- 查看视图数据SELECT *FROM user_view_1;SELECT *FROM user_view_1WHERE age = 23;-- 修改视图，相当于用新的视图覆盖原视图CREATE OR REPLACE VIEW user_view_1 ASSELECT *FROM tb_userWHERE profession = &#x27;城市规划&#x27;WITH LOCAL CHECK OPTION;-- 修改原视图ALTER VIEW user_view_1 AS SELECT *                          FROM tb_user                          WHERE profession = &#x27;化工&#x27; WITH LOCAL CHECK OPTION;-- 删除视图DROP VIEW IF EXISTS user_view_1;

检查选项通过视图操作数据，本质上就是在操作视图对应的基础表。向视图中插入或更新数据时，MySQL 可以根据视图定义的查询条件来检查数据是否合规。为了控制这种检查行为，可以在创建视图时使用 WITH [CASCADED | LOCAL] CHECK OPTION：

如果创建视图时没有使用 WITH CHECK OPTION，那么通过视图插入、更新数据时不做任何检查：不满足视图条件的数据也能成功插入基础表，只是插入后在这个视图中看不到而已（见下方”未开启”演示）；若视图是基于其他视图创建的，也不会检查上层视图的条件
如果创建视图时使用了 WITH CASCADED CHECK OPTION（级联），那么插入&#x2F;更新的数据必须满足当前视图的条件；若当前视图是基于其他视图创建的，即使那些上层视图没开检查选项，也必须满足上层视图的查询条件
如果创建视图时使用了 WITH LOCAL CHECK OPTION（局部），那么插入&#x2F;更新的数据必须满足当前视图的条件；若基于其他视图创建，则只有那些同样开启了检查选项的上层视图条件需要满足

未开启 WITH [CASCADED | LOCAL] CHECK OPTION
-- 创建视图CREATE OR REPLACE VIEW user_view_1 ASSELECT *FROM tb_userWHERE profession = &#x27;软件工程&#x27;;-- 查看视图数据SELECT *FROM user_view_1;-- 向视图中插入数据，实际是插入到表中INSERT INTO user_view_1(id, name, phone, email, profession, age, gender, status, create_time)VALUES (25, &#x27;诸葛亮&#x27;, 17799990024, &#x27;zhuge666@sina.com&#x27;, &#x27;软件工程&#x27;, 22, 2, 0, &#x27;2025-11-26 19:32:30&#x27;);-- 插入成功，但是只添加到了 tb_user 中，在视图 user_view_1 中不存在，因为在创建视图时指定了条件 profession = &#x27;软件工程&#x27;INSERT INTO user_view_1(id, name, phone, email, profession, age, gender, status, create_time)VALUES (26, &#x27;哪吒&#x27;, 17799990025, &#x27;nezha666@sina.com&#x27;, &#x27;计算机科学&#x27;, 22, 2, 0, &#x27;2025-11-26 19:32:30&#x27;);

开启 WITH [CASCADED | LOCAL] CHECK OPTION
-- 创建视图CREATE OR REPLACE VIEW user_view_1 ASSELECT *FROM tb_userWHERE profession = &#x27;软件工程&#x27;WITH LOCAL CHECK OPTION ;-- 查看视图数据SELECT *FROM user_view_1;-- 向视图中插入数据，实际是插入到表中，并且满足视图的条件，同时插入到视图中INSERT INTO user_view_1(id, name, phone, email, profession, age, gender, status, create_time)VALUES (25, &#x27;诸葛亮&#x27;, 17799990024, &#x27;zhuge666@sina.com&#x27;, &#x27;软件工程&#x27;, 22, 2, 0, &#x27;2025-11-26 19:32:30&#x27;);-- 插入失败，因为开启了 WITH LOCAL CHECK OPTION，因为在创建视图时指定了条件 profession = &#x27;软件工程&#x27;INSERT INTO user_view_1(id, name, phone, email, profession, age, gender, status, create_time)VALUES (26, &#x27;哪吒&#x27;, 17799990025, &#x27;nezha666@sina.com&#x27;, &#x27;计算机科学&#x27;, 22, 2, 0, &#x27;2025-11-26 19:32:30&#x27;);-- 报错：[HY000][1369] CHECK OPTION failed &#x27;mysql_study.user_view_1&#x27;

更新及作用对视图做更新（INSERT &#x2F; UPDATE &#x2F; DELETE）实际上更新的是它对应的基础表。但并不是所有视图都能更新：只有视图与基础表结构基本一致、且视图中没有聚合函数、DISTINCT、GROUP BY、HAVING、子查询等复杂内容时，才能安全更新（带 WITH CHECK OPTION 的视图更新时还会做条件检查）

简单：用户可以将常用的查询语句封装成视图，简化查询操作
安全：MySQL 中通过授权只能限制用户访问表，而不能限制用户访问表中的某列，通过将表中的可见列封装成视图，然后再访问视图，这样子用户只能看到可见列，从而提高数据的安全性
独立：视图对外暴露的结构与基础表相互独立。基础表增加列不会影响视图（新列不会自动出现在视图里）；想调整对外暴露的字段时，只需更新视图定义，无需改动上层应用

视图案例为保证数据安全，用户在访问 tb_user 表时，只能看到基本字段，不能看到 phone 和 email 字段
CREATE VIEW tb_user_view ASSELECT id, name, profession, age, gender, status, create_timeFROM tb_user;SELECT * FROM tb_user_view;-- 1,吕布,软件工程,23,1,6,2001-02-02 00:00:00-- 2,曹操,通讯工程,33,1,0,2001-03-05 00:00:00-- 3,赵云,英语,34,1,2,2002-03-02 00:00:00-- 4,孙悟空,工程造价,54,1,0,2001-07-02 00:00:00-- 5,花木兰,软件工程,23,2,1,2001-04-22 00:00:00-- 6,大桥,舞蹈,22,2,0,2001-02-07 00:00:00-- 7,露娜,应用数学,24,2,0,2001-02-08 00:00:00-- 8,程咬金,化工,38,1,5,2001-05-23 00:00:00-- 9,项羽,金属材料,43,1,0,2001-09-18 00:00:00-- 10,白起,机械工程及其自动化,27,1,2,2001-08-16 00:00:00-- 11,韩信,无机非金属材料工程,27,1,0,2001-06-12 00:00:00-- 12,荆轲,会计,29,1,0,2001-05-11 00:00:00-- 13,兰陵王,工程造价,44,1,1,2001-04-09 00:00:00-- 14,狂铁,应用数学,43,1,2,2001-04-10 00:00:00-- 15,貂蝉,软件工程,40,2,3,2001-02-12 00:00:00-- 16,妲己,软件工程,31,2,0,2001-01-30 00:00:00-- 17,芈月,工业经济,35,2,0,2000-05-03 00:00:00-- 18,嬴政,化工,38,1,1,2001-08-08 00:00:00-- 19,狄仁杰,国际贸易,30,1,0,2007-03-12 00:00:00-- 20,安琪拉,城市规划,51,2,0,2001-08-15 00:00:00-- 21,典韦,城市规划,52,1,2,2000-04-12 00:00:00-- 22,廉颇,土木工程,19,1,3,2002-07-18 00:00:00-- 23,后裔,城市园林,20,1,0,2002-03-10 00:00:00-- 24,姜子牙,工程造价,29,1,4,2003-05-26 00:00:00-- 25,诸葛亮,软件工程,22,2,0,2025-11-26 19:32:30

存储过程存储过程介绍存储过程（Stored Procedure）是一组事先定义好、存储在数据库中的 SQL 语句集合。把频繁使用的复杂操作封装成存储过程，之后只需 CALL 调用，可以简化操作、减少客户端与服务器的交互次数、提升效率
存储过程特点
封装、复用
可以接收参数、并返回结果
减少交互次数，提升效率

存储过程基本使用
创建存储过程

CREATE PROCEDURE 存储过程名 ([参数列表]) BEGIN SQL语句; END;


调用存储过程

CALL 存储过程名([参数列表]);


查看存储过程

SELECT * FROM INFORMATION_SCHEMA.ROUTINES WHERE ROUTINE_TYPE &#x3D; ‘PROCEDURE’;


删除存储过程

DROP PROCEDURE 存储过程名;



-- 创建存储过程CREATE PROCEDURE p1()BEGIN    SELECT COUNT(tb_user.id) FROM tb_user;END;-- 调用存储过程CALL p1();-- 查看全部存储过程SELECT *FROM INFORMATION_SCHEMA.ROUTINESWHERE ROUTINE_TYPE = &#x27;PROCEDURE&#x27;  AND ROUTINE_SCHEMA = &#x27;mysql_study&#x27;;SHOW CREATE PROCEDURE p1;-- 删除存储过程DROP PROCEDURE IF EXISTS p1;

变量在存储过程中，可以使用变量来存储数据、传递结果。变量一共分三类：系统变量、用户变量、局部变量
系统变量系统变量是 MySQL 提供的变量，用于保存 MySQL 服务器的状态信息，如当前时间、当前用户、当前数据库等，属于服务器层面，系统变量又分为全局变量(GLOBAL)和会话变量(SESSION)两种

查看系统变量

SHOW [GLOBAL | SESSION] VARIABLES [LIKE ‘变量名’];


SELECT @@[GLOBAL | SESSION] 变量名;


修改系统变量

SET [@@][GLOBAL | SESSION] 变量名 &#x3D; 值;



-- 查看全部系统变量，默认是 SESSION 级别SHOW VARIABLES;-- 查看全局系统变量SHOW GLOBAL VARIABLES;-- 使用模糊查询SHOW GLOBAL VARIABLES LIKE &#x27;auto%&#x27;;-- 查看指定系统变量SELECT @@global.autocommit;-- 设置系统变量SET SESSION AUTOCOMMIT = 0;SELECT @@session.autocommit;SET @@session.autocommit = 1;

用户变量用户变量是定义在会话（当前连接）上的变量，用于保存临时数据，当前会话内都可以使用。用户变量以 @ 符号开头，例如 @my_name，可以在 SQL 语句中直接使用

创建用户变量

SET @变量名 :&#x3D; 值;


SELECT 字段名 INTO @变量名 FROM 表名 WHERE 条件;


使用用户变量

SELECT @变量名;



-- 创建用户变量SET @my_name = &#x27;lasyc&#x27;;SET @my_age := 20;SET @my_gender := &#x27;男&#x27;, @my_hobby := &#x27;Java&#x27;;-- 使用 SELECT 赋值SELECT @my_profession := &#x27;软件工程&#x27;;SELECT COUNT(tb_user.id) INTO @tb_user_count FROM tb_user;-- 查看用户变量SELECT @my_name, @my_age, @my_gender, @my_hobby, @my_profession, @tb_user_count;

局部变量局部变量是在存储过程内部定义、只在本次调用中生效的变量，用 DECLARE 关键字声明，只能在存储过程（函数）中使用。声明格式为：DECLARE 变量名 数据类型 [DEFAULT 默认值];

定义局部变量

DECLARE 变量名 数据类型 [DEFAULT 值];


赋值

SET 变量名 :&#x3D; 值;


SELECT 字段名 INTO 变量名 FROM 表名 WHERE 条件;


使用局部变量

SELECT 变量名;



CREATE PROCEDURE p2()BEGIN    DECLARE user_count INT DEFAULT 0;    SET user_count := 10;    SELECT user_count;    SELECT COUNT(tb_user.id) INTO user_count FROM tb_user;    SELECT user_count;END;CALL p2();

数组与集合属性注入数组属性注入背景：当需要注入的属性是数组类型时，可以使用 &lt;array&gt; 标签来注入。
public class Employee &#123;    private String name;    private Integer age;    private String[] hobbies;    // 员工属于某个部门    private Department department;    public void work() &#123;        System.out.println(this.name + &quot;正在工作，今年&quot; + this.age + &quot;岁了，他的爱好有&quot; + Arrays.toString(this.hobbies));        this.getDepartment().info();    &#125;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;    public Integer getAge() &#123;        return age;    &#125;    public void setAge(Integer age) &#123;        this.age = age;    &#125;    public String[] getHobbies() &#123;        return hobbies;    &#125;    public void setHobbies(String[] hobbies) &#123;        this.hobbies = hobbies;    &#125;    public Department getDepartment() &#123;        return department;    &#125;    public void setDepartment(Department department) &#123;        this.department = department;    &#125;&#125;

&lt;!-- 数组属性注入 --&gt;&lt;bean id=&quot;department&quot; class=&quot;com.lasyc.entity.Department&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;部门01&quot;/&gt;&lt;/bean&gt;&lt;bean id=&quot;employee&quot; class=&quot;com.lasyc.entity.Employee&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;张三&quot;/&gt;    &lt;property name=&quot;age&quot; value=&quot;20&quot;/&gt;    &lt;property name=&quot;department&quot; ref=&quot;department&quot;/&gt;    &lt;property name=&quot;hobbies&quot;&gt;        &lt;array&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;Java&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;C++&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;Python&lt;/value&gt;        &lt;/array&gt;    &lt;/property&gt;&lt;/bean&gt;

@Testpublic void getBeanWithArrayField() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    Employee employee = context.getBean(&quot;employee&quot;, Employee.class);    employee.work();    // 张三正在工作，今年20岁了，他的爱好有[Java, C++, Python]    // 部门名是部门01&#125;

集合属性注入背景：当需要注入的属性是集合类型时，可以使用 &lt;list&gt; 标签来注入。
public class Department &#123;    private String name;    private List&lt;Employee&gt; employeeList;    public void info() &#123;        System.out.println(&quot;部门名是&quot; + this.name + &quot;，员工有：&quot; + Arrays.toString(employeeList.stream().map(Employee::getName).toArray()));    &#125;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;    public List&lt;Employee&gt; getEmployeeList() &#123;        return employeeList;    &#125;    public void setEmployeeList(List&lt;Employee&gt; employeeList) &#123;        this.employeeList = employeeList;    &#125;&#125;

&lt;bean id=&quot;employee1&quot; class=&quot;com.lasyc.entity.Employee&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;张三&quot;/&gt;    &lt;property name=&quot;age&quot; value=&quot;20&quot;/&gt;    &lt;property name=&quot;department&quot; ref=&quot;department&quot;/&gt;    &lt;property name=&quot;hobbies&quot;&gt;        &lt;array&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;Java&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;C++&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;Python&lt;/value&gt;        &lt;/array&gt;    &lt;/property&gt;&lt;/bean&gt;&lt;bean id=&quot;department&quot; class=&quot;com.lasyc.entity.Department&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;部门01&quot;/&gt;    &lt;property name=&quot;employeeList&quot;&gt;        &lt;list&gt;            &lt;!-- 可以引用外部类 --&gt;            &lt;ref bean=&quot;employee1&quot;/&gt;            &lt;!-- 也可以引用内部类 --&gt;            &lt;bean class=&quot;com.lasyc.entity.Employee&quot;&gt;                &lt;property name=&quot;name&quot; value=&quot;李四&quot;/&gt;                &lt;property name=&quot;age&quot; value=&quot;21&quot;/&gt;                &lt;property name=&quot;department&quot; ref=&quot;department&quot;/&gt;                &lt;property name=&quot;hobbies&quot;&gt;                    &lt;array&gt;                        &lt;value type=&quot;java.lang.String&quot;&gt;JavaScript&lt;/value&gt;                        &lt;value type=&quot;java.lang.String&quot;&gt;HTML&lt;/value&gt;                        &lt;value type=&quot;java.lang.String&quot;&gt;CSS&lt;/value&gt;                    &lt;/array&gt;                &lt;/property&gt;            &lt;/bean&gt;        &lt;/list&gt;    &lt;/property&gt;&lt;/bean&gt;

@Testpublic void getBeanWithListField() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    Department department = context.getBean(&quot;department&quot;, Department.class);    department.info(); // 部门名是部门01，员工有：[张三, 李四]&#125;

Map 属性注入背景：当需要注入的属性是 Map 类型时，可以使用 &lt;map&gt; 标签来注入。
public class Department &#123;    private String name;    private List&lt;Employee&gt; employeeList;    private Map&lt;String, Employee&gt; employeeMap;    public void info() &#123;        System.out.println(&quot;部门名是&quot; + this.name + &quot;，员工有：&quot; + Arrays.toString(employeeList.stream().map(Employee::getName).toArray()));    &#125;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;    public List&lt;Employee&gt; getEmployeeList() &#123;        return employeeList;    &#125;    public void setEmployeeList(List&lt;Employee&gt; employeeList) &#123;        this.employeeList = employeeList;    &#125;    public Map&lt;String, Employee&gt; getEmployeeMap() &#123;        return employeeMap;    &#125;    public void setEmployeeMap(Map&lt;String, Employee&gt; employeeMap) &#123;        this.employeeMap = employeeMap;    &#125;&#125;

&lt;!-- Map 属性注入--&gt;&lt;bean id=&quot;employee1&quot; class=&quot;com.lasyc.entity.Employee&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;张三&quot;/&gt;    &lt;property name=&quot;age&quot; value=&quot;20&quot;/&gt;    &lt;property name=&quot;department&quot; ref=&quot;department&quot;/&gt;    &lt;property name=&quot;hobbies&quot;&gt;        &lt;array&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;Java&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;C++&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;Python&lt;/value&gt;        &lt;/array&gt;    &lt;/property&gt;&lt;/bean&gt;&lt;bean id=&quot;employee2&quot; class=&quot;com.lasyc.entity.Employee&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;李四&quot;/&gt;    &lt;property name=&quot;age&quot; value=&quot;21&quot;/&gt;    &lt;property name=&quot;department&quot; ref=&quot;department&quot;/&gt;    &lt;property name=&quot;hobbies&quot;&gt;        &lt;array&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;JavaScript&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;HTML&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;CSS&lt;/value&gt;        &lt;/array&gt;    &lt;/property&gt;&lt;/bean&gt;&lt;bean id=&quot;department&quot; class=&quot;com.lasyc.entity.Department&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;部门01&quot;/&gt;    &lt;property name=&quot;employeeList&quot;&gt;        &lt;list&gt;            &lt;ref bean=&quot;employee1&quot;/&gt;            &lt;ref bean=&quot;employee2&quot;/&gt;        &lt;/list&gt;    &lt;/property&gt;    &lt;property name=&quot;employeeMap&quot;&gt;        &lt;map&gt;            &lt;entry key=&quot;张三&quot; value-ref=&quot;employee1&quot;/&gt;            &lt;entry key=&quot;李四&quot; value-ref=&quot;employee2&quot;/&gt;        &lt;/map&gt;    &lt;/property&gt;&lt;/bean&gt;

@Testpublic void getBeanWithMapField() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    Department department = context.getBean(&quot;department&quot;, Department.class);    Map&lt;String, Employee&gt; employeeMap = department.getEmployeeMap();    employeeMap.forEach((key, value) -&gt; &#123;        System.out.println(key);        value.work();    &#125;);    // 张三    // 张三正在工作，今年20岁了，他的爱好有[Java, C++, Python]    // 部门名是部门01，员工有：[张三, 李四]    // 李四    // 李四正在工作，今年21岁了，他的爱好有[JavaScript, HTML, CSS]    // 部门名是部门01，员工有：[张三, 李四]&#125;

引用集合注入在原有的 List 和 Map 注入基础上，可以先用 &lt;util:list&gt;、&lt;util:map&gt; 标签把集合封装成独立的 Bean，再在需要注入时一次性引用。

如果想在 xml 文件中使用 &lt;util:list&gt; 和 &lt;util:map&gt; 标签，需要在 xml 文件头引入对应的库

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xmlns:util=&quot;http://www.springframework.org/schema/util&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans                            http://www.springframework.org/schema/beans/spring-beans.xsd                            http://www.springframework.org/schema/util                            http://www.springframework.org/schema/util/spring-util.xsd&quot;&gt;&lt;!-- 引入：xmlns:util=&quot;http://www.springframework.org/schema/util&quot; --&gt;&lt;!-- 引入：http://www.springframework.org/schema/util --&gt;&lt;!-- 引入：http://www.springframework.org/schema/util/spring-util.xsd --&gt;&lt;/beans&gt;&lt;bean id=&quot;employee1&quot; class=&quot;com.lasyc.entity.Employee&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;张三&quot;/&gt;    &lt;property name=&quot;age&quot; value=&quot;20&quot;/&gt;    &lt;property name=&quot;department&quot; ref=&quot;department&quot;/&gt;    &lt;property name=&quot;hobbies&quot;&gt;        &lt;array&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;Java&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;C++&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;Python&lt;/value&gt;        &lt;/array&gt;    &lt;/property&gt;&lt;/bean&gt;&lt;bean id=&quot;employee2&quot; class=&quot;com.lasyc.entity.Employee&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;李四&quot;/&gt;    &lt;property name=&quot;age&quot; value=&quot;21&quot;/&gt;    &lt;property name=&quot;department&quot; ref=&quot;department&quot;/&gt;    &lt;property name=&quot;hobbies&quot;&gt;        &lt;array&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;JavaScript&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;HTML&lt;/value&gt;            &lt;value type=&quot;java.lang.String&quot;&gt;CSS&lt;/value&gt;        &lt;/array&gt;    &lt;/property&gt;&lt;/bean&gt;&lt;util:list id=&quot;employeeList&quot;&gt;    &lt;ref bean=&quot;employee1&quot;/&gt;    &lt;ref bean=&quot;employee2&quot;/&gt;&lt;/util:list&gt;&lt;util:map id=&quot;employeeMap&quot;&gt;        &lt;entry key=&quot;张三&quot; value-ref=&quot;employee1&quot; /&gt;        &lt;entry key=&quot;李四&quot; value-ref=&quot;employee2&quot; /&gt;&lt;/util:map&gt;&lt;bean id=&quot;department&quot; class=&quot;com.lasyc.entity.Department&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;部门01&quot;/&gt;    &lt;property name=&quot;employeeList&quot; ref=&quot;employeeList&quot; /&gt;    &lt;property name=&quot;employeeMap&quot; ref=&quot;employeeMap&quot; /&gt;&lt;/bean&gt;

IoCIoC 是 Inversion of Control 的缩写，中文翻译为“控制反转”。它是一种设计原则，指的是将对象的创建和依赖关系的管理交给一个容器来处理，而不是由对象自己来管理。
Spring 框架中的 IoC 容器负责创建、配置和管理应用程序中的对象。通过使用 IoC，开发者可以实现松耦合的代码结构，提高代码的可维护性和可测试性。
简单来说，当我想使用一个类时，以往需要自己 new 出这个类的实例，并手动管理它的生命周期。而在 IoC 中，我们将这个责任交给了 Spring 容器：只需要在配置文件中声明这个类，Spring 就会帮我们创建它的实例并管理它的生命周期。我们只需要在使用的时候从容器中获取这个实例即可。
XML 配置在 Spring 的早期版本中，IoC 的配置通常是通过 XML 文件来完成的：我们可以在 XML 文件中定义 bean（即对象），并指定它们的属性和依赖关系。
除了 XML 配置，还有很多配置方式，它们都通过 BeanDefinitionReader 接口来读取并注册 Bean 定义。常用的实现类有三个，分别是：XMLBeanDefinitionReader、PropertiesBeanDefinitionReader 和 AnnotatedBeanDefinitionReader。其中，XMLBeanDefinitionReader 通过 XML 文件来配置 bean，AnnotatedBeanDefinitionReader 则通过注解来配置 bean。
XML 配置文件（BeanDefinition）    ↓XMLBeanDefinitionReader（读取 XML 并注册 BeanDefinition）    ↓BeanFactory（反射）    ↓Spring Bean    ↓context.getBean(id)

依赖注入依赖注入（Dependency Injection，简称 DI）是 IoC 的一种实现方式。它指的是将对象的依赖关系通过外部配置的方式注入到对象中，而不是由对象自己来创建和管理。
常见的依赖注入方式有三种：构造器注入、Setter 注入和字段注入。
BeanFactoryBeanFactory 是 Spring 框架中的一个核心接口，它是 IoC 容器的基础。BeanFactory 负责创建和管理应用程序中的 bean（即对象），它提供了一个统一的接口来获取和管理 bean 的实例。
ApplicationContextApplicationContext 是 BeanFactory 的一个子接口，在 BeanFactory 提供的基本功能之外，还支持国际化、事件传播、资源加载等功能。常见的有以下几种：



实现类
描述



