在 XML 配置文件中配置 Bean 信息

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd&quot;&gt;    &lt;!-- 配置 User 类--&gt;    &lt;bean id=&quot;user&quot; class=&quot;com.lasyc.entity.User&quot;/&gt;&lt;/beans&gt;


编写测试类，分三种方式分别获取 Bean

@Testpublic void getBean() &#123;    // 加载配置文件    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    // 根据 ID 获取    User userById = (User) context.getBean(&quot;user&quot;);    System.out.println(&quot;根据 ID 获取 Bean &quot; + userById);    // 根据 ID 获取 Bean com.lasyc.entity.User@4565a70a    // 根据类型获取    User userByType = context.getBean(User.class);    System.out.println(&quot;根据 Type 获取 Bean &quot; + userByType);    // 根据 Type 获取 Bean com.lasyc.entity.User@4565a70a    // 根据 ID 和类型获取    User userByIdAndType = context.getBean(&quot;user&quot;, User.class);    System.out.println(&quot;根据 ID 和 Type 获取 &quot; + userByIdAndType);    // 根据 ID 和 Type 获取 com.lasyc.entity.User@4565a70a&#125;


注意：若想通过类型获取 Bean，那么在 XML 文件中，相同类型的 Bean 有且只能有一个。

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd&quot;&gt;    &lt;!-- 配置 User 类--&gt;    &lt;bean id=&quot;user&quot; class=&quot;com.lasyc.entity.User&quot;/&gt;    &lt;!-- 存在重复类型的对象 --&gt;    &lt;bean id=&quot;userTemp&quot; class=&quot;com.lasyc.entity.User&quot;/&gt;&lt;/beans&gt;

@Testpublic void getBean() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    // 根据类型获取    User userByType = context.getBean(User.class);    System.out.println(&quot;根据 Type 获取 Bean &quot; + userByType);    // org.springframework.beans.factory.NoUniqueBeanDefinitionException: No qualifying bean of type &#x27;com.lasyc.entity.User&#x27; available: expected single matching bean but found 2: user,userTemp&#125;

获取 Bean （接口）背景：一个接口只有一个实现类时，能否通过接口类型获取实现类对象？如果有多个实现类，又该如何获取？
public interface UserDao &#123;&#125;

public class UserDaoImpl1 implements UserDao &#123;&#125;

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd&quot;&gt;    &lt;!-- 配置实现类对象--&gt;    &lt;bean id=&quot;userDaoImpl1&quot; class=&quot;com.lasyc.dao.impl.UserDaoImpl1&quot; /&gt;&lt;/beans&gt;

@Testpublic void getBeanInterface() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    // 通过 ID 获取    UserDao userDaoImpl1 = (UserDao) context.getBean(&quot;userDaoImpl1&quot;);    System.out.println(userDaoImpl1);    // com.lasyc.dao.impl.UserDaoImpl1@710d7aff    // 通过接口类型获取实现类对象    UserDao userDao = context.getBean(UserDao.class);    System.out.println(userDao);    // com.lasyc.dao.impl.UserDaoImpl1@710d7aff&#125;

由此可见，可以通过接口类型获取实现类对象。但是如果存在多个实现类对象呢？
public class UserDaoImpl2 implements UserDao &#123;&#125;

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd&quot;&gt;    &lt;!-- 配置实现类对象--&gt;    &lt;bean id=&quot;userDaoImpl1&quot; class=&quot;com.lasyc.dao.impl.UserDaoImpl1&quot; /&gt;    &lt;bean id=&quot;userDaoImpl2&quot; class=&quot;com.lasyc.dao.impl.UserDaoImpl2&quot; /&gt;&lt;/beans&gt;

@Testpublic void getBeanInterfaceDoubleClass() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    // 通过 ID 获取    UserDao userDaoImpl1 = (UserDao) context.getBean(&quot;userDaoImpl1&quot;);    System.out.println(userDaoImpl1);    // com.lasyc.dao.impl.UserDaoImpl1@6b68cb27    // 通过 ID 获取    UserDao userDaoImpl2 = (UserDao) context.getBean(&quot;userDaoImpl2&quot;);    System.out.println(userDaoImpl2);    // com.lasyc.dao.impl.UserDaoImpl2@1e6cc850    // 通过接口类型获取实现类对象    UserDao userDao = context.getBean(UserDao.class);    System.out.println(userDao);    // org.springframework.beans.factory.NoUniqueBeanDefinitionException: No qualifying bean of type &#x27;com.lasyc.dao.UserDao&#x27; available: expected single matching bean but found 2: userDaoImpl1,userDaoImpl2&#125;

当一个接口有多个实现类时，无法通过接口类型获取实现类对象
基于 setter 依赖注入public class Book &#123;    private String bookName;    private String author;    public Book() &#123;    &#125;    public Book(String bookName, String author) &#123;        this.bookName = bookName;        this.author = author;    &#125;    public String getBookName() &#123;        return bookName;    &#125;    public void setBookName(String bookName) &#123;        this.bookName = bookName;    &#125;    public String getAuthor() &#123;        return author;    &#125;    public void setAuthor(String author) &#123;        this.author = author;    &#125;    @Override    public String toString() &#123;        return &quot;Book&#123;&quot; +                &quot;bookName=&#x27;&quot; + bookName + &#x27;\&#x27;&#x27; +                &quot;, author=&#x27;&quot; + author + &#x27;\&#x27;&#x27; +                &#x27;&#125;&#x27;;    &#125;&#125;

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd&quot;&gt;    &lt;!-- 配置 Book 类，通过 setter 方法给属性注入值--&gt;    &lt;bean id=&quot;book&quot; class=&quot;com.lasyc.entity.Book&quot;&gt;        &lt;!-- 通过 property 标签来调用 set 方法赋值 --&gt;        &lt;property name=&quot;bookName&quot; value=&quot;Java&quot; /&gt;        &lt;property name=&quot;author&quot; value=&quot;James Gosling&quot; /&gt;    &lt;/bean&gt;&lt;/beans&gt;

基于构造器注入&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd&quot;&gt;    &lt;!-- 配置 Book 类，通过 setter 方法给属性注入值--&gt;    &lt;!--&lt;bean id=&quot;book&quot; class=&quot;com.lasyc.entity.Book&quot;&gt;        &lt;property name=&quot;bookName&quot; value=&quot;Java&quot; /&gt;        &lt;property name=&quot;author&quot; value=&quot;James Gosling&quot; /&gt;    &lt;/bean&gt;--&gt;    &lt;!-- 配置 Book 类，通过有参构造方法给属性注入值--&gt;    &lt;bean id=&quot;book&quot; class=&quot;com.lasyc.entity.Book&quot;&gt;        &lt;constructor-arg name=&quot;bookName&quot; value=&quot;Java&quot; type=&quot;java.lang.String&quot; /&gt;        &lt;constructor-arg name=&quot;author&quot; value=&quot;James Gosling&quot; type=&quot;java.lang.String&quot; /&gt;    &lt;/bean&gt;&lt;/beans&gt;

@Testpublic void getBeanWithInjectionByConstructor() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    Book book = context.getBean(&quot;book&quot;, Book.class);    System.out.println(book);   // Book&#123;bookName=&#x27;Java&#x27;, author=&#x27;James Gosling&#x27;&#125;&#125;

特殊值处理前面学习了通过依赖注入在 Bean 被创建时就完成属性赋值。除了上述普通的值以外，还有很多特殊的值需要处理，比如：null、对象、特殊符号 等。
&lt;!-- 配置 Book 类，通过 setter 方法给属性注入值--&gt;&lt;bean id=&quot;book&quot; class=&quot;com.lasyc.entity.Book&quot;&gt;    &lt;!-- null --&gt;    &lt;property name=&quot;bookName&quot;&gt;&lt;null /&gt;&lt;/property&gt;    &lt;!-- 特殊符号，如 &lt; &gt;，用字符实体 &amp;lt; &amp;gt; 替换--&gt;    &lt;!--&lt;property name=&quot;author&quot; value=&quot;&amp;lt;James Gosling&amp;gt;&quot; /&gt;--&gt;    &lt;!-- 特殊符号，如 &lt; &gt;，或者使用 CDATA 包围--&gt;    &lt;property name=&quot;author&quot;&gt;        &lt;value&gt;&lt;![CDATA[&lt;James Gosling&gt;]]&gt;&lt;/value&gt;    &lt;/property&gt;&lt;/bean&gt;

@Testpublic void getBeanWithSpecialSign() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    Book book = context.getBean(&quot;book&quot;, Book.class);    System.out.println(book);   // Book&#123;bookName=&#x27;null&#x27;, author=&#x27;&lt;James Gosling&gt;&#x27;&#125;&#125;

对象属性注入背景：当需要注入的属性是对象类型（引用类型）时，有三种注入方式：引用外部 Bean、内部 Bean、级联属性赋值。
引用外部 Beanpublic class Employee &#123;    private String name;    private Integer age;    // 员工属于某个部门    private Department department;    public void work() &#123;        System.out.println(this.name + &quot;正在工作，今年&quot; + this.age + &quot;岁了&quot;);        this.getDepartment().info();    &#125;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;    public Integer getAge() &#123;        return age;    &#125;    public void setAge(Integer age) &#123;        this.age = age;    &#125;    public Department getDepartment() &#123;        return department;    &#125;    public void setDepartment(Department department) &#123;        this.department = department;    &#125;&#125;

public class Department &#123;    private String name;    public void info() &#123;        System.out.println(&quot;部门名是&quot; + this.name);    &#125;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;&#125;

&lt;bean id=&quot;department&quot; class=&quot;com.lasyc.entity.Department&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;部门01&quot;/&gt;&lt;/bean&gt;&lt;bean id=&quot;employee&quot; class=&quot;com.lasyc.entity.Employee&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;张三&quot;/&gt;    &lt;property name=&quot;age&quot; value=&quot;20&quot;/&gt;    &lt;!-- 引用外部 Bean，通过 ref 属性引用上面定义的 department 对象 --&gt;    &lt;property name=&quot;department&quot; ref=&quot;department&quot;/&gt;&lt;/bean&gt;

@Testpublic void getBeanWithObjectField() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    Employee employee = context.getBean(&quot;employee&quot;, Employee.class);    employee.work();    // 张三正在工作，今年20岁了    // 部门名是部门01&#125;

引用内部 Bean&lt;bean id=&quot;employee&quot; class=&quot;com.lasyc.entity.Employee&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;张三&quot;/&gt;    &lt;property name=&quot;age&quot; value=&quot;20&quot;/&gt;    &lt;!-- 引用内部 Bean --&gt;    &lt;property name=&quot;department&quot;&gt;        &lt;bean class=&quot;com.lasyc.entity.Department&quot;&gt;            &lt;property name=&quot;name&quot; value=&quot;部门01&quot;/&gt;        &lt;/bean&gt;    &lt;/property&gt;&lt;/bean&gt;

级联属性赋值&lt;bean id=&quot;department&quot; class=&quot;com.lasyc.entity.Department&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;部门01&quot;/&gt;&lt;/bean&gt;&lt;bean id=&quot;employee&quot; class=&quot;com.lasyc.entity.Employee&quot;&gt;    &lt;property name=&quot;name&quot; value=&quot;张三&quot;/&gt;    &lt;property name=&quot;age&quot; value=&quot;20&quot;/&gt;    &lt;!-- 引用外部 Bean --&gt;    &lt;property name=&quot;department&quot; ref=&quot;department&quot; /&gt;    &lt;!-- 级联赋值，覆盖之前的值 --&gt;    &lt;property name=&quot;department.name&quot; value=&quot;部门02&quot; /&gt;&lt;/bean&gt;

@Testpublic void getBeanWithObjectField() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    Employee employee = context.getBean(&quot;employee&quot;, Employee.class);    employee.work();    // 张三正在工作，今年20岁了    // 部门名是部门02&#125;

基于注解进行 Bean 管理除了 @Component 注解，还有其他注解也可以将类标记为 Spring Bean 交给 IoC 容器管理，只不过注解的名字不同，标注的位置也不同。



注解
作用



@Controller
Controller 类，控制器层


@Service
Service 类，业务层


@Repository
Mapper 类，持久层


@Component
普通 Bean


&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xmlns:context=&quot;http://www.springframework.org/schema/context&quot;       xsi:schemaLocation=&quot;       http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd       http://www.springframework.org/schema/context http://www.springframework.org/schema/context/spring-context.xsd&quot;&gt;    &lt;!-- 开启组件扫描，扫描到对应的组件，就会实现自动注入 --&gt;    &lt;context:component-scan base-package=&quot;com.lasyc&quot; &gt;        &lt;!-- 根据设置的规则过滤不扫描 --&gt;        &lt;!--&lt;context:exclude-filter type=&quot;annotation&quot; expression=&quot;org.springframework.stereotype.Component&quot;/&gt;--&gt;        &lt;!-- 根据设置的规则扫描 --&gt;        &lt;!--&lt;context:include-filter type=&quot;annotation&quot; expression=&quot;org.springframework.stereotype.Component&quot;/&gt;--&gt;    &lt;/context:component-scan&gt;&lt;/beans&gt;

// 添加注解，可以让 IoC 容器扫描到@Componentpublic class User &#123;&#125;

@Testpublic void getBeanByAnnotation() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    User user = context.getBean(&quot;user&quot;, User.class);    System.out.println(user);   // com.lasyc.bean.User@3104351d&#125;

@Autowired 属性注入@Autowired 默认按照类型自动注入，该注解可以标注在：构造方法、方法、形参、属性上。不过 Spring 官方并不建议使用字段注入，而是推荐通过构造器注入。
@Controllerpublic class UserController &#123;    // 字段注入不推荐，建议使用构造器注入    @Autowired    private UserService userService;    public void controllerMethod() &#123;        System.out.println(&quot;Controller Method&quot;);        userService.serviceMethod();    &#125;&#125;

public interface UserService &#123;    void serviceMethod();&#125;

@Servicepublic class UserServiceImpl implements UserService &#123;    @Autowired    private UserMapper userMapper;    @Override    public void serviceMethod() &#123;        System.out.println(&quot;Service Method&quot;);        userMapper.mapperMethod();    &#125;&#125;

public interface UserMapper &#123;    void mapperMethod();&#125;

@Repositorypublic class UserMapperImpl implements UserMapper &#123;    @Override    public void mapperMethod() &#123;        System.out.println(&quot;Mapper Method&quot;);    &#125;&#125;

@Testpublic void getBeanByAnnotation() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean.xml&quot;);    UserController userController = context.getBean(&quot;userController&quot;, UserController.class);    userController.controllerMethod();    // Controller Method    // Service Method    // Mapper Method&#125;

@Autowired setter 注入将 @Autowired 注解标注到 setter 方法上
@Controllerpublic class UserController &#123;    private UserService userService;    public UserService getUserService() &#123;        return userService;    &#125;    @Autowired    public void setUserService(UserService userService) &#123;        this.userService = userService;    &#125;    public void controllerMethod() &#123;        System.out.println(&quot;Controller Method&quot;);        userService.serviceMethod();    &#125;&#125;

@Servicepublic class UserServiceImpl implements UserService &#123;    private UserMapper userMapper;    public UserMapper getUserMapper() &#123;        return userMapper;    &#125;    @Autowired    public void setUserMapper(UserMapper userMapper) &#123;        this.userMapper = userMapper;    &#125;    @Override    public void serviceMethod() &#123;        System.out.println(&quot;Service Method&quot;);        userMapper.mapperMethod();    &#125;&#125;

@Autowired 构造方法注入
