public class User &#123;    private String name;    public User() &#123;        System.out.println(&quot;1. 无参构造方法执行&quot;);    &#125;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        System.out.println(&quot;2. 依赖注入 set 方法执行&quot;);        this.name = name;    &#125;    // 自定义初始化方法    public void init() &#123;        System.out.println(&quot;4. 指定初始化方法执行&quot;);    &#125;    // 自定义销毁方法    public void destroy() &#123;        System.out.println(&quot;7. 指定销毁方法执行&quot;);    &#125;&#125;

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd&quot;&gt;    &lt;!-- 配置 Bean，并且指定初始化方法和销毁方法 --&gt;    &lt;bean id=&quot;user&quot; class=&quot;com.lasyc.life.User&quot; init-method=&quot;init&quot; destroy-method=&quot;destroy&quot;&gt;        &lt;property name=&quot;name&quot; value=&quot;Tom&quot; /&gt;    &lt;/bean&gt;&lt;/beans&gt;

@Testpublic void getBean() &#123;    // 因为要销毁 Bean，但是 ApplicationContext 中没有 close 方法，所以这里使用 ClassPathXmlApplicationContext    ClassPathXmlApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean-life.xml&quot;);    User user = context.getBean(&quot;user&quot;, User.class);    System.out.println(&quot;6. 对象创建完成 =&gt; &quot; + user);    // 关闭容器，销毁 Bean    context.close();&#125;// 1. 无参构造方法执行// 2. 依赖注入 set 方法执行// 4. 指定初始化方法执行// 6. 对象创建完成 =&gt; com.lasyc.life.User@2f879bab// 7. 指定销毁方法执行


