FactoryBeanFactoryBean 是 Spring 提供的一种用于整合第三方框架的常用机制。与普通 Bean 不同，通过 FactoryBean 获取对象时，实际拿到的是其 getObject() 方法返回的对象。
public class CustomFactoryBean implements FactoryBean&lt;User&gt; &#123;    @Override    public @Nullable User getObject() throws Exception &#123;        // 实际返回对象        return new User();    &#125;    @Override    public @Nullable Class&lt;?&gt; getObjectType() &#123;        // 对象类型        return User.class;    &#125;    @Override    public boolean isSingleton() &#123;        return FactoryBean.super.isSingleton();    &#125;&#125;

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd&quot;&gt;    &lt;!-- 这里配置的是 CustomFactoryBean，并不是 User --&gt;    &lt;bean id=&quot;user&quot; class=&quot;com.lasyc.factorybean.CustomFactoryBean&quot; /&gt;&lt;/beans&gt;

@Testpublic void getObject() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean-factorybean.xml&quot;);    User user = context.getBean(&quot;user&quot;, User.class);    // 但是取得的类型是 User    System.out.println(user);   // com.lasyc.factorybean.User@2e3a5237&#125;

