public interface UserMapper &#123;    void mapperMethod();&#125;

public class UserMapperImpl implements UserMapper &#123;    @Override    public void mapperMethod() &#123;        System.out.println(&quot;Mapper Method&quot;);    &#125;&#125;

&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;       xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;       xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd&quot;&gt;    &lt;!-- 分别定义三个 Bean --&gt;    &lt;bean id=&quot;userMapper&quot; class=&quot;com.lasyc.autoinject.mapper.impl.UserMapperImpl&quot; /&gt;    &lt;!-- 使用 autowire 属性实现自动装配 --&gt;    &lt;bean id=&quot;userServiceImpl&quot; class=&quot;com.lasyc.autoinject.service.impl.UserServiceImpl&quot; autowire=&quot;byType&quot; /&gt;    &lt;bean id=&quot;userController&quot; class=&quot;com.lasyc.autoinject.controller.UserController&quot; autowire=&quot;byType&quot; /&gt;&lt;/beans&gt;

@Testpublic void autoInject() &#123;    ApplicationContext context = new ClassPathXmlApplicationContext(&quot;bean-autoinject.xml&quot;);    UserController userController = context.getBean(&quot;userController&quot;, UserController.class);    userController.controllerMethod();    // Controller Method    // Service Method    // Mapper Method&#125;

Java 反射反射（Reflection）是 Java 提供的一种运行时机制：程序在运行期间可以获取类的完整结构信息（构造方法、属性、方法等），并动态地创建对象、调用方法、访问属性。Spring 的 IoC 容器正是基于反射来实现 Bean 的创建和依赖注入的，所以先来回顾一下反射的用法。
获取 Class 对象public class Person &#123;    private String name;    private Integer age;    private String gender;    private String phone;    public Person() &#123;    &#125;    private Person(String name, Integer age, String gender) &#123;        this.name = name;        this.age = age;        this.gender = gender;    &#125;    public Person(String name, Integer age, String gender, String phone) &#123;        this.name = name;        this.age = age;        this.gender = gender;        this.phone = phone;    &#125;    private void method() &#123;        System.out.println(&quot;private method&quot;);    &#125;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;    public Integer getAge() &#123;        return age;    &#125;    public void setAge(Integer age) &#123;        this.age = age;    &#125;    public String getGender() &#123;        return gender;    &#125;    public void setGender(String gender) &#123;        this.gender = gender;    &#125;    public String getPhone() &#123;        return phone;    &#125;    public void setPhone(String phone) &#123;        this.phone = phone;    &#125;    @Override    public String toString() &#123;        return &quot;Person&#123;&quot; +                &quot;name=&#x27;&quot; + name + &#x27;\&#x27;&#x27; +                &quot;, age=&quot; + age +                &quot;, gender=&#x27;&quot; + gender + &#x27;\&#x27;&#x27; +                &quot;, phone=&#x27;&quot; + phone + &#x27;\&#x27;&#x27; +                &#x27;&#125;&#x27;;    &#125;&#125;

// 使用反射获取 Class 对象@Testpublic void getObject() throws ClassNotFoundException, NoSuchMethodException, InvocationTargetException, InstantiationException, IllegalAccessException &#123;    // 1.    Class&lt;Person&gt; clazz1 = Person.class;    // 2.    Person person = new Person();    Class&lt;? extends Person&gt; clazz2 = person.getClass();    // 3.    Class&lt;?&gt; clazz3 = Class.forName(&quot;com.lasyc.reflect.Person&quot;);    // 获取 Class 对象后就可以实例化对象了    Person personObj = clazz1.getDeclaredConstructor().newInstance();    System.out.println(personObj);  //  Person&#123;name=&#x27;null&#x27;, age=null, gender=&#x27;null&#x27;, phone=&#x27;null&#x27;&#125;&#125;

