加载类public interface CustomContext &#123;    Object getBean(Class clazz);&#125;

public class CustomApplicationContext implements CustomContext &#123;    private final Map&lt;Class, Object&gt; beanMap = new HashMap&lt;&gt;();    private int basePackageStartIndex;    @Override    public Object getBean(Class clazz) &#123;        return beanMap.get(clazz);    &#125;    // 扫描包，找到含有 @CustomBean 注解的类    public CustomApplicationContext(String basePackage) &#123;        // 转换成文件路径        String basePath = basePackage.replace(&quot;.&quot;, File.separator);        // 获取绝对路径        ClassLoader classLoader = getClass().getClassLoader();        URL resourcePath = classLoader.getResource(basePath);        // 获取成功        if (resourcePath != null) &#123;            // 转换编码格式            String encodePath = URLDecoder.decode(resourcePath.getFile(), StandardCharsets.UTF_8);            // 记录基本包起始位置，方便后面做截取            basePackageStartIndex = encodePath.indexOf(basePath) - 1;            // 加载包            loadCustomBean(new File(encodePath));        &#125;    &#125;    private void loadCustomBean(File file) &#123;        // 判断文件是否有效且存在        if (file == null || !file.exists()) return;        // 判断文件是否是文件        if (file.isFile() &amp;&amp; !file.isDirectory()) &#123;            // 获取绝对路径            String absolutePath = file.getAbsolutePath();            // 从包开始的位置截取，去掉前面多余的文件系统路径            String classPath = absolutePath.substring(basePackageStartIndex);            // 根据 . 分割，获取文件后缀            String[] split = classPath.split(&quot;\\.&quot;);            // 判断是否是 class 文件            if (!&quot;class&quot;.equals(split[1])) return;            // 分割后的第一部分就是完整类名（包名.类名），把路径分隔符 \ 替换成 .            String className = split[0].replace(&quot;\\&quot;, &quot;.&quot;);            try &#123;                // 加载类                Class&lt;?&gt; aClass = Class.forName(className);                // 判断是否是接口                if (aClass.isInterface()) return;                // 获取注解                CustomBean annotation = aClass.getAnnotation(CustomBean.class);                if (annotation == null) return;                // 实例化                Object obj = aClass.getDeclaredConstructor().newInstance();                // 判断当前类有没有实现接口                Class&lt;?&gt;[] interfaces = aClass.getInterfaces();                // 如果有接口，默认使用第一个接口类型作为 key                if (interfaces.length &gt; 0) &#123;                    beanMap.put(aClass.getInterfaces()[0], obj);                &#125; else &#123;                    beanMap.put(obj.getClass(), obj);                &#125;            &#125; catch (Exception e) &#123;                e.printStackTrace();            &#125;            return;        &#125;        // 如果是文件夹，则遍历子文件进行递归        File[] files = file.listFiles();        if (files == null) return;        for (File targetFile : files) &#123;            loadCustomBean(targetFile);        &#125;    &#125;&#125;

属性注入public class CustomApplicationContext implements CustomContext &#123;    private final Map&lt;Class, Object&gt; beanMap = new HashMap&lt;&gt;();    private int basePackageStartIndex;    @Override    public Object getBean(Class clazz) &#123;        return beanMap.get(clazz);    &#125;    // 扫描包，找到含有 @CustomBean 注解的类    public CustomApplicationContext(String basePackage) &#123;        // 转换成文件路径        String basePath = basePackage.replace(&quot;.&quot;, File.separator);        // 获取绝对路径        ClassLoader classLoader = getClass().getClassLoader();        URL resourcePath = classLoader.getResource(basePath);        // 获取成功        if (resourcePath != null) &#123;            // 转换编码格式            String encodePath = URLDecoder.decode(resourcePath.getFile(), StandardCharsets.UTF_8);            // 记录基本包起始位置，方便后面做截取            basePackageStartIndex = encodePath.indexOf(basePath) - 1;            // 加载 Bean            loadCustomBean(new File(encodePath));            // 属性注入            fieldInject();        &#125;    &#125;    private void fieldInject() &#123;        // 遍历所有已经加载的 Bean        Collection&lt;Object&gt; beans = beanMap.values();        for (Object bean : beans) &#123;            // 获取每个 Bean 的属性            Field[] declaredFields = bean.getClass().getDeclaredFields();            // 遍历所有属性            for (Field declaredField : declaredFields) &#123;                // 判断当前属性是否含有注解                CustomAutowired annotation = declaredField.getAnnotation(CustomAutowired.class);                if (annotation == null) continue;                // 根据属性的类型去容器中查找对应的 Bean                Object o = beanMap.get(declaredField.getType());                // 容器中没有该类型的 Bean，跳过这个属性，继续处理下一个                if (o == null) continue;                // 注入                declaredField.setAccessible(true);                try &#123;                    declaredField.set(bean, o);                &#125; catch (Exception e) &#123;                    e.printStackTrace();                &#125;            &#125;        &#125;    &#125;    private void loadCustomBean(File file) &#123;        // ......    &#125;&#125;

