@Repositorypublic class BookMapperImpl implements BookMapper &#123;    @Autowired    private JdbcTemplate jdbcTemplate;    @Override    public Integer getStock(String bookId) &#123;        String sql = &quot;SELECT stock FROM t_book WHERE id = ?&quot;;        return jdbcTemplate.queryForObject(sql, Integer.class, bookId);    &#125;    @Override    public Integer getPrice(String bookId) &#123;        String sql = &quot;SELECT price FROM t_book WHERE id = ?&quot;;        return jdbcTemplate.queryForObject(sql, Integer.class, bookId);    &#125;    @Override    public Integer updateStock(String bookId) &#123;        String sql = &quot;UPDATE t_book SET stock = stock - 1 WHERE id = ?&quot;;        return jdbcTemplate.update(sql, bookId);    &#125;&#125;

@Repositorypublic class UserMapperImpl implements UserMapper &#123;    @Autowired    private JdbcTemplate jdbcTemplate;    @Override    public Integer getBalance(String userId) &#123;        String sql = &quot;SELECT balance FROM t_user WHERE id = ?&quot;;        return jdbcTemplate.queryForObject(sql, Integer.class, userId);    &#125;    @Override    public Integer updateBalance(String userId, Integer price) &#123;        String sql = &quot;UPDATE t_user SET balance = balance - ? WHERE id = ?&quot;;        return jdbcTemplate.update(sql, price, userId);    &#125;&#125;

@Servicepublic class BookServiceImpl implements BookService &#123;    @Autowired    private BookMapper bookMapper;    @Autowired    private UserMapper userMapper;    @Override    public void buyBook(String userId, String bookId) &#123;        // 查询图书是否有库存        Integer stock = bookMapper.getStock(bookId);        if (Objects.equals(stock, 0)) &#123;            System.out.println(&quot;没有库存&quot;);            return;        &#125;        // 查询图书价格        Integer price = bookMapper.getPrice(bookId);        // 查询用户余额        Integer balance = userMapper.getBalance(userId);        if (balance.compareTo(price) &lt; 0) &#123;            System.out.println(&quot;余额不足&quot;);            return;        &#125;        // 扣款        Integer count = userMapper.updateBalance(userId, price);        if (count &gt; 0) &#123;            System.out.println(&quot;扣款成功&quot;);        &#125;        // 库存 -1        count = bookMapper.updateStock(bookId);        if (count &gt; 0) &#123;            System.out.println(&quot;库存 -1 成功&quot;);        &#125;    &#125;&#125;

在正常情况下，上述代码执行是没有任何问题的，余额可以正常扣除，库存也可以正常减 1。但是如果在扣款和库存减 1 之间发生异常，导致程序中断，就会出现问题。
// 扣款Integer count = userMapper.updateBalance(userId, price);if (count &gt; 0) &#123;    System.out.println(&quot;扣款成功&quot;);&#125;// 模拟异常int a = 1 / 0;// 库存 -1count = bookMapper.updateStock(bookId);if (count &gt; 0) &#123;    System.out.println(&quot;库存 -1 成功&quot;);&#125;

在这种情况下，扣款结束后发生异常，钱虽然扣了，但库存并没有减 1。因此必须要使用事务来保证操作的原子性，即要么都成功，要么都失败。
基于注解的声明式事务
在配置文件中追加如下配置

&lt;!-- 创建事务管理器 --&gt;&lt;bean id=&quot;transactionManager&quot; class=&quot;org.springframework.jdbc.datasource.DataSourceTransactionManager&quot;&gt;    &lt;property name=&quot;dataSource&quot; ref=&quot;druidDataSource&quot;/&gt;&lt;/bean&gt;&lt;!-- 开启事务的注解驱动 --&gt;&lt;tx:annotation-driven transaction-manager=&quot;transactionManager&quot;/&gt;


提示：使用 &lt;tx:annotation-driven&gt; 前，需要先在 &lt;beans&gt; 根标签中引入 xmlns:tx 命名空间及对应 xsd（可参考本文末尾基于 XML 的配置文件）。


使用 @Transactional 来开启事务

@Service// 放到类上，对类中的所有方法都生效@Transactionalpublic class BookServiceImpl implements BookService &#123;    @Autowired    private BookMapper bookMapper;    @Autowired    private UserMapper userMapper;    @Override    // 放到方法上，只对当前方法生效    @Transactional    public void buyBook(String userId, String bookId) &#123;        // 查询图书是否有库存        Integer stock = bookMapper.getStock(bookId);        if (Objects.equals(stock, 0)) &#123;            System.out.println(&quot;没有库存&quot;);            return;        &#125;        // 查询图书价格        Integer price = bookMapper.getPrice(bookId);        // 查询用户余额        Integer balance = userMapper.getBalance(userId);        if (balance.compareTo(price) &lt; 0) &#123;            System.out.println(&quot;余额不足&quot;);            return;        &#125;        // 扣款        Integer count = userMapper.updateBalance(userId, price);        if (count &gt; 0) &#123;            System.out.println(&quot;扣款成功&quot;);        &#125;        // 模拟异常        int a = 1 / 0;        // 库存 -1        count = bookMapper.updateStock(bookId);        if (count &gt; 0) &#123;            System.out.println(&quot;库存 -1 成功&quot;);        &#125;    &#125;&#125;

再次执行代码就会发现，虽然控制台打印了“扣款成功”，但是余额和库存并没有变化，也就是说，虽然余额被修改了，但是发生异常后，数据回滚了

ValidationValidation 是 Spring 中提供的一种可以通过注解来进行参数校验的接口。
实现 Validator 接口
引入依赖

&lt;dependency&gt;    &lt;groupId&gt;org.hibernate.validator&lt;/groupId&gt;    &lt;artifactId&gt;hibernate-validator&lt;/artifactId&gt;    &lt;version&gt;9.0.1.Final&lt;/version&gt;&lt;/dependency&gt;&lt;dependency&gt;    &lt;groupId&gt;jakarta.validation&lt;/groupId&gt;    &lt;artifactId&gt;jakarta.validation-api&lt;/artifactId&gt;    &lt;version&gt;3.1.1&lt;/version&gt;&lt;/dependency&gt;&lt;!-- 如果 message 中涉及占位符替换，则需要引入该依赖 --&gt;&lt;!-- 比如：@Min(value = 1, message = &quot;年龄不能小于 &#123;value&#125;&quot;) --&gt;&lt;dependency&gt;    &lt;groupId&gt;org.glassfish.expressly&lt;/groupId&gt;    &lt;artifactId&gt;expressly&lt;/artifactId&gt;    &lt;version&gt;6.0.0&lt;/version&gt;&lt;/dependency&gt;


创建测试类

public class Person &#123;    private String name;    private int age;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;    public int getAge() &#123;        return age;    &#125;    public void setAge(int age) &#123;        this.age = age;    &#125;&#125;


自定义校验类，实现 Validator 接口

public class CustomValidation implements Validator &#123;    @Override    public boolean supports(Class&lt;?&gt; clazz) &#123;        // 用于判断是否支持当前类做参数校验        // 设置只支持 Person 类        return Person.class.equals(clazz);    &#125;    @Override    public void validate(Object target, Errors errors) &#123;        Person p = (Person) target;        // 用于设置校验规则        // name 不能为空        ValidationUtils.rejectIfEmpty(errors, &quot;name&quot;, &quot;name.error&quot;, &quot;Name is null or empty&quot;);        // age 不能小于 0，不能大于 100        Integer age = p.getAge();        if (age &lt; 0) &#123;            errors.rejectValue(&quot;age&quot;, &quot;age.error&quot;, &quot;Age is less than 0&quot;);        &#125; else if (age &gt; 100) &#123;            errors.rejectValue(&quot;age&quot;, &quot;age.error&quot;, &quot;Older than 100&quot;);        &#125;    &#125;    @Override    public Errors validateObject(Object target) &#123;        return Validator.super.validateObject(target);    &#125;&#125;


测试

public static void main(String[] args) &#123;    // 创建 Person 对象    Person person = new Person();    person.setAge(-100);    // 注入到 DataBinder 中    DataBinder dataBinder = new DataBinder(person);    // 并且设置校验器    dataBinder.setValidator(new CustomValidation());    // 开始校验    dataBinder.validate();    // 获取校验结果    BindingResult bindingResult = dataBinder.getBindingResult();    System.out.println(bindingResult.getAllErrors());    // [Field error in object &#x27;target&#x27; on field &#x27;name&#x27;: rejected value [null]; codes [name.error.target.name,name.error.name,name.error.java.lang.String,name.error]; arguments []; default message [Name is null or empty],    // Field error in object &#x27;target&#x27; on field &#x27;age&#x27;: rejected value [-100]; codes [age.error.target.age,age.error.age,age.error.int,age.error]; arguments []; default message [Age is less than 0]]&#125;

