测试类，使用注解

// 注意包路径，Validation 2.x 和 3.x 不一致import jakarta.validation.constraints.Max;import jakarta.validation.constraints.Min;import jakarta.validation.constraints.NotNull;public class User &#123;    @NotNull    private String name;    @Min(0)    @Max(100)    private int age;    public String getName() &#123;        return name;    &#125;    public void setName(String name) &#123;        this.name = name;    &#125;    public int getAge() &#123;        return age;    &#125;    public void setAge(int age) &#123;        this.age = age;    &#125;&#125;


Validation 的实现方式有两种，分别是原生写法和基于 Spring 写法。

@Componentpublic class Validation1 &#123;    // 使用原生的 Validator    // jakarta.validation.Validator;    @Autowired    private Validator v;    public boolean validator(User user) &#123;        Set&lt;ConstraintViolation&lt;User&gt;&gt; validate = v.validate(user);        return validate.isEmpty();    &#125;&#125;

@Componentpublic class Validation2 &#123;    // 使用 Spring 的 Validator    // org.springframework.validation.Validator    @Autowired    private Validator v;    public boolean validator(User user) &#123;        BindException bindException = new BindException(user, user.getName());        v.validate(user, bindException);        return bindException.hasErrors();    &#125;&#125;


测试

public static void main(String[] args) &#123;    ApplicationContext context = new AnnotationConfigApplicationContext(ValidationConfig.class);    Validation1 validation1 = context.getBean(Validation1.class);    User user1 = new User();    boolean validator1 = validation1.validator(user1);    System.out.println(validator1);  // false    User user2 = new User();    user2.setName(&quot;Tom&quot;);    user2.setAge(20);    boolean validator2 = validation1.validator(user2);    System.out.println(validator2); // true    Validation2 validation2 = context.getBean(Validation2.class);    User user3 = new User();    // 这里会报异常：Exception in thread &quot;main&quot; java.lang.IllegalArgumentException: Object name must not be null    // 这并不是 Validation 校验的结果    // 而是因为 BindException bindException = new BindException(user, user.getName());    // 在创建 BindException 时，第二个参数（对象名）为 null，所以才抛出异常    // boolean validator3 = validation2.validator(user3);    // System.out.println(validator3);    // 需要设置一下名字    user3.setName(&quot;&quot;);    boolean validator4 = validation2.validator(user3);    System.out.println(validator4); // false    User user4 = new User();    user4.setName(&quot;Tom&quot;);    user4.setAge(-1);    boolean validator5 = validation1.validator(user4);    System.out.println(validator5); // false&#125;

