代码示例@PathVariable@ResponseBody@GetMapping(&quot;/pathVariable/&#123;username&#125;/&#123;password&#125;&quot;)public Map&lt;String, Object&gt; pathVariable(@PathVariable(&quot;username&quot;) String username,                                        @PathVariable(&quot;password&quot;) String password,                                        @PathVariable Map&lt;String, Object&gt; params) &#123;    Map&lt;String, Object&gt; result = new HashMap&lt;&gt;();    result.put(&quot;username&quot;, username);    result.put(&quot;password&quot;, password);    result.put(&quot;params&quot;, params);    // &#123;    //   &quot;password&quot;: &quot;123456&quot;,    //   &quot;params&quot;: &#123;    //     &quot;password&quot;: &quot;123456&quot;,    //     &quot;username&quot;: &quot;admin&quot;    //   &#125;,    //   &quot;username&quot;: &quot;admin&quot;    // &#125;    return result;&#125;

@RequestHeader@ResponseBody@GetMapping(&quot;/requestHeader&quot;)public Map&lt;String, Object&gt; requestHeader(@RequestHeader(&quot;User-Agent&quot;) String userAgent,                                         @RequestHeader Map&lt;String, Object&gt; headers,                                         @RequestHeader HttpHeaders httpHeaders) &#123;    Map&lt;String, Object&gt; result = new HashMap&lt;&gt;();    result.put(&quot;userAgent&quot;, userAgent);    result.put(&quot;headers&quot;, headers);    result.put(&quot;httpHeaders&quot;, httpHeaders);    // @RequestHeader(&quot;User-Agent&quot;) 获取指定 header    // @RequestHeader + Map 获取全部请求头（真实的请求头）    // @RequestHeader + HttpHeaders 获取全部请求头    return result;&#125;

@RequestParam@ResponseBody@GetMapping(&quot;/requestParam&quot;)public Map&lt;String, Object&gt; requestParam(@RequestParam(&quot;username&quot;) String username,                                        @RequestParam(&quot;hobbies&quot;) List&lt;String&gt; hobbies,                                        @RequestParam Map&lt;String, Object&gt; params) &#123;    Map&lt;String, Object&gt; result = new HashMap&lt;&gt;();    result.put(&quot;username&quot;, username);    result.put(&quot;hobbies&quot;, hobbies);    result.put(&quot;params&quot;, params);    // &#123;    //  &quot;hobbies&quot;: [    //     &quot;java&quot;,    //     &quot;c  &quot;    //   ],    //   &quot;params&quot;: &#123;    //     &quot;username&quot;: &quot;admin&quot;,    //     &quot;hobbies&quot;: &quot;java&quot;    //   &#125;,    //   &quot;username&quot;: &quot;admin&quot;    // &#125;    return result;&#125;

