文件上传Spring Boot 默认使用 StandardServletMultipartResolver 处理文件上传，无需任何额外配置（对比 SpringMVC 需要配置解析器，Spring Boot 已经自动配置好了）
spring:  servlet:    multipart:      max-file-size: 10MB # 单个文件大小上限，默认 1MB      max-request-size: 100MB # 一次请求总大小上限，默认 10MB

@ResponseBody@PostMapping(&quot;/upload&quot;)public Map&lt;String, Object&gt; upload(@RequestPart(&quot;file&quot;) MultipartFile file,                                  @RequestParam(&quot;username&quot;) String username) throws IOException &#123;    Map&lt;String, Object&gt; result = new HashMap&lt;&gt;();    result.put(&quot;username&quot;, username);    result.put(&quot;fileName&quot;, file.getOriginalFilename());    result.put(&quot;fileSize&quot;, file.getSize());    // 保存文件到指定目录（示例）    file.transferTo(new File(&quot;d:/upload/&quot; + file.getOriginalFilename()));    // &#123;    //   &quot;fileSize&quot;: 1024,    //   &quot;fileName&quot;: &quot;test.txt&quot;,    //   &quot;username&quot;: &quot;admin&quot;    // &#125;    return result;&#125;

&lt;!-- 前端 form 表单：enctype 必须为 multipart/form-data --&gt;&lt;form th:action=&quot;@&#123;/upload&#125;&quot; method=&quot;post&quot; enctype=&quot;multipart/form-data&quot;&gt;  &lt;input type=&quot;text&quot; name=&quot;username&quot; value=&quot;admin&quot; /&gt;  &lt;input type=&quot;file&quot; name=&quot;file&quot; /&gt;  &lt;input type=&quot;submit&quot; value=&quot;上传&quot; /&gt;&lt;/form&gt;


多文件上传时，只需将参数类型改为 MultipartFile[] 或 List&lt;MultipartFile&gt;，前端表单中多个 name=&quot;file&quot; 的 input 即可

参数处理原理
从 HandlerMapping 中找到对应的 Handler
为当前 Handler 找到对应的 HandlerAdapter（适配器）
HandlerAdapter 执行对应的 Handler
调用 setHandlerMethodArgumentResolvers 设置参数解析器

protected @Nullable ModelAndView invokeHandlerMethod(HttpServletRequest request,        HttpServletResponse response, HandlerMethod handlerMethod) throws Exception &#123;    WebAsyncManager asyncManager = WebAsyncUtils.getAsyncManager(request);    AsyncWebRequest asyncWebRequest = WebAsyncUtils.createAsyncWebRequest(request, response);    asyncWebRequest.setTimeout(this.asyncRequestTimeout);    asyncManager.setTaskExecutor(this.taskExecutor);    asyncManager.setAsyncWebRequest(asyncWebRequest);    asyncManager.registerCallableInterceptors(this.callableInterceptors);    asyncManager.registerDeferredResultInterceptors(this.deferredResultInterceptors);    // Obtain wrapped response to enforce lifecycle rule from Servlet spec, section 2.3.3.4    response = asyncWebRequest.getNativeResponse(HttpServletResponse.class);    ServletWebRequest webRequest = (asyncWebRequest instanceof ServletWebRequest ?            (ServletWebRequest) asyncWebRequest : new ServletWebRequest(request, response));    WebDataBinderFactory binderFactory = getDataBinderFactory(handlerMethod);    ModelFactory modelFactory = getModelFactory(handlerMethod, binderFactory);    ServletInvocableHandlerMethod invocableMethod = createInvocableHandlerMethod(handlerMethod);    // 设置参数处理器    if (this.argumentResolvers != null) &#123;        invocableMethod.setHandlerMethodArgumentResolvers(this.argumentResolvers);    &#125;    // 设置返回值处理器    if (this.returnValueHandlers != null) &#123;        invocableMethod.setHandlerMethodReturnValueHandlers(this.returnValueHandlers);    &#125;    invocableMethod.setDataBinderFactory(binderFactory);    invocableMethod.setParameterNameDiscoverer(this.parameterNameDiscoverer);    invocableMethod.setMethodValidator(this.methodValidator);    ModelAndViewContainer mavContainer = new ModelAndViewContainer();    mavContainer.addAllAttributes(RequestContextUtils.getInputFlashMap(request));    modelFactory.initModel(webRequest, mavContainer, invocableMethod);    if (asyncManager.hasConcurrentResult()) &#123;        Object result = asyncManager.getConcurrentResult();        Object[] resultContext = asyncManager.getConcurrentResultContext();        Assert.state(resultContext != null &amp;&amp; resultContext.length &gt; 0, &quot;Missing result context&quot;);        mavContainer = (ModelAndViewContainer) resultContext[0];        asyncManager.clearConcurrentResult();        LogFormatUtils.traceDebug(logger, traceOn -&gt; &#123;            String formatted = LogFormatUtils.formatValue(result, !traceOn);            return &quot;Resume with async result [&quot; + formatted + &quot;]&quot;;        &#125;);        invocableMethod = invocableMethod.wrapConcurrentResult(result);    &#125;    // 执行目标方法    invocableMethod.invokeAndHandle(webRequest, mavContainer);    if (asyncManager.isConcurrentHandlingStarted()) &#123;        return null;    &#125;    return getModelAndView(mavContainer, modelFactory, webRequest);&#125;

我们知道 Spring 通过各种的参数解析器来解析参数，那么对于 Servlet 原生的一些参数，也有对应的解析器 ServletRequestMethodArgumentResolver
public class ServletRequestMethodArgumentResolver implements HandlerMethodArgumentResolver &#123;    // 判断支持哪些参数    @Override    @SuppressWarnings(&quot;deprecation&quot;)    public boolean supportsParameter(MethodParameter parameter) &#123;        Class&lt;?&gt; paramType = parameter.getParameterType();        return (WebRequest.class.isAssignableFrom(paramType) ||                ServletRequest.class.isAssignableFrom(paramType) ||                MultipartRequest.class.isAssignableFrom(paramType) ||                HttpSession.class.isAssignableFrom(paramType) ||                PushBuilder.class.isAssignableFrom(paramType) ||                (Principal.class.isAssignableFrom(paramType) &amp;&amp; !parameter.hasParameterAnnotations()) ||                InputStream.class.isAssignableFrom(paramType) ||                Reader.class.isAssignableFrom(paramType) ||                HttpMethod.class == paramType ||                Locale.class == paramType ||                TimeZone.class == paramType ||                ZoneId.class == paramType);    &#125;    // ......&#125;

因此，我们可以直接在 handler 方法中，使用对应的参数，不需要任何注解，Spring 会帮我们自动注入
@ResponseBody@GetMapping(&quot;/servletApi&quot;)public Map&lt;String, Object&gt; servletApi(HttpServletRequest request,                                      HttpServletResponse response,                                      HttpSession session,                                      Locale locale) &#123;    Map&lt;String, Object&gt; result = new HashMap&lt;&gt;();    result.put(&quot;request&quot;, request.getRequestURI());    result.put(&quot;locale&quot;, locale);    // &#123;    //   &quot;locale&quot;: &quot;zh_CN&quot;,    //   &quot;request&quot;: &quot;/servletApi&quot;    // &#125;    return result;&#125;

