package com.lasyc.mapper;import com.lasyc.entity.User;import org.springframework.stereotype.Repository;import java.util.HashMap;import java.util.List;import java.util.Map;@Repositorypublic class UserMapper &#123;    private static final Map&lt;String, User&gt; userMap = new HashMap&lt;&gt;();    static &#123;        for (int i = 0; i &lt; 20; i++) &#123;            User user = new User();            user.setId(String.format(&quot;%03d&quot;, i));            user.setName(&quot;姓名&quot; + String.format(&quot;%02d&quot;, i));            user.setAge(18 + i % 5);            userMap.put(user.getId(), user);        &#125;    &#125;    public User select(String id) &#123;        return userMap.get(id);    &#125;    public List&lt;User&gt; select() &#123;        // 这种写法返回的 list 是不可变的，不能进行 add、remove、sort 等操作        return userMap.values().stream().toList();        // 可以使用这种写法        // return new ArrayList&lt;&gt;(userMap.values());    &#125;    public Boolean insert(User user) &#123;        int size = userMap.size();        String id = String.format(&quot;%03d&quot;, size + 1);        user.setId(id);        userMap.put(id, user);        return Boolean.TRUE;    &#125;    public Boolean update(User user) &#123;        if (userMap.containsKey(user.getId())) &#123;            userMap.put(user.getId(), user);            return Boolean.TRUE;        &#125;        return Boolean.FALSE;    &#125;    public Boolean delete(String id) &#123;        if (userMap.containsKey(id)) &#123;            userMap.remove(id);            return Boolean.TRUE;        &#125;        return Boolean.FALSE;    &#125;&#125;

