UserControllerpackage com.lasyc.controller;import com.lasyc.entity.User;import com.lasyc.mapper.UserMapper;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import java.util.List;@Controller@RequestMapping(&quot;/user&quot;)public class UserController &#123;    @Autowired    private UserMapper mapper;    @GetMapping    public String select(Model model) &#123;        // 查询所有用户        List&lt;User&gt; list = mapper.select();        // 添加到 request 域        model.addAttribute(&quot;userList&quot;, list);        // 返回页面        return &quot;user/list&quot;;    &#125;    @GetMapping(&quot;/&#123;id&#125;&quot;)    public String select(@PathVariable String id, Model model) &#123;        // 查询指定用户        User user = mapper.select(id);        // 添加到 request 域        model.addAttribute(&quot;user&quot;, user);        // 返回页面        return &quot;user/detail&quot;;    &#125;    @PostMapping    public String insert(User user, Model model) &#123;        // 插入用户信息        Boolean insert = mapper.insert(user);        // 添加到 request 域        model.addAttribute(&quot;insert&quot;, insert);        // 返回页面，如果添加成功，需要重新获取用户信息        return Boolean.TRUE.equals(insert) ? &quot;redirect:/user&quot; : &quot;user/list&quot;;    &#125;    @PutMapping(&quot;/&#123;id&#125;&quot;)    public String update(@PathVariable String id, User user, Model model) &#123;        user.setId(id);        // 更新用户信息        Boolean update = mapper.update(user);        // 添加到 request 域        model.addAttribute(&quot;update&quot;, update);        // 返回页面，如果更新成功，需要重新获取用户信息        return Boolean.TRUE.equals(update) ? &quot;redirect:/user&quot; : &quot;user/list&quot;;    &#125;    @DeleteMapping(&quot;/&#123;id&#125;&quot;)    public String delete(@PathVariable String id, Model model) &#123;        // 删除用户信息        Boolean delete = mapper.delete(id);        // 添加到 request 域        model.addAttribute(&quot;delete&quot;, delete);        // 返回页面，如果删除成功，需要重新获取用户信息        return Boolean.TRUE.equals(delete) ? &quot;redirect:/user&quot; : &quot;user/list&quot;;    &#125;&#125;

