protected void doDispatch(HttpServletRequest request, HttpServletResponse response) throws Exception &#123;    HttpServletRequest processedRequest = request;    HandlerExecutionChain mappedHandler = null;    boolean multipartRequestParsed = false;    WebAsyncManager asyncManager = WebAsyncUtils.getAsyncManager(request);    try &#123;        try &#123;            ModelAndView mv = null;            Exception dispatchException = null;            try &#123;                processedRequest = this.checkMultipart(request);                multipartRequestParsed = processedRequest != request;                mappedHandler = this.getHandler(processedRequest);                if (mappedHandler == null) &#123;                    this.noHandlerFound(processedRequest, response);                    return;                &#125;                // 执行所有拦截器的 preHandle 方法，如果有返回 false 结束请求                if (!mappedHandler.applyPreHandle(processedRequest, response)) &#123;                    return;                &#125;                HandlerAdapter ha = this.getHandlerAdapter(mappedHandler.getHandler());                // 执行匹配的 Controller 方法                mv = ha.handle(processedRequest, response, mappedHandler.getHandler());                if (asyncManager.isConcurrentHandlingStarted()) &#123;                    return;                &#125;                this.applyDefaultViewName(processedRequest, mv);                // 执行所有拦截器的 postHandle 方法                mappedHandler.applyPostHandle(processedRequest, response, mv);            &#125; catch (Exception ex) &#123;                dispatchException = ex;            &#125; catch (Throwable err) &#123;                dispatchException = new ServletException(&quot;Handler dispatch failed: &quot; + String.valueOf(err), err);            &#125;            this.processDispatchResult(processedRequest, response, mappedHandler, mv, dispatchException);        &#125; catch (Exception ex) &#123;            triggerAfterCompletion(processedRequest, response, mappedHandler, ex);        &#125; catch (Throwable err) &#123;            triggerAfterCompletion(processedRequest, response, mappedHandler, new ServletException(&quot;Handler processing failed: &quot; + String.valueOf(err), err));        &#125;    &#125; finally &#123;        if (asyncManager.isConcurrentHandlingStarted()) &#123;            if (mappedHandler != null) &#123;                mappedHandler.applyAfterConcurrentHandlingStarted(processedRequest, response);            &#125;            asyncManager.setMultipartRequestParsed(multipartRequestParsed);        &#125; else if (multipartRequestParsed || asyncManager.isMultipartRequestParsed()) &#123;            this.cleanupMultipart(processedRequest);        &#125;    &#125;&#125;

boolean applyPreHandle(HttpServletRequest request, HttpServletResponse response) throws Exception &#123;    // 遍历所有的拦截器    for(int i = 0; i &lt; this.interceptorList.size(); this.interceptorIndex = i++) &#123;        HandlerInterceptor interceptor = (HandlerInterceptor)this.interceptorList.get(i);        // 如果有任意拦截器的 preHandle 返回 false，直接返回 false        if (!interceptor.preHandle(request, response, this.handler)) &#123;            // 如果 preHandle 返回 false，直接执行 afterCompletion，跳过 postHandle            this.triggerAfterCompletion(request, response, (Exception)null);            return false;        &#125;    &#125;    return true;&#125;

多个拦截器的执行顺序当有多个拦截器时，三个方法的执行顺序如下：

preHandle：顺序执行
postHandle：逆序执行
afterCompletion：逆序执行

boolean applyPreHandle(HttpServletRequest request, HttpServletResponse response) throws Exception &#123;    // i++ 所以 preHandle 是顺序的    for(int i = 0; i &lt; this.interceptorList.size(); this.interceptorIndex = i++) &#123;        HandlerInterceptor interceptor = (HandlerInterceptor)this.interceptorList.get(i);        if (!interceptor.preHandle(request, response, this.handler)) &#123;            // 如果 preHandle 返回 false，直接执行 afterCompletion，跳过 postHandle            this.triggerAfterCompletion(request, response, (Exception)null);            return false;        &#125;    &#125;    return true;&#125;void applyPostHandle(HttpServletRequest request, HttpServletResponse response, @Nullable ModelAndView mv) throws Exception &#123;    // --i 所以 postHandle 是逆序的    for(int i = this.interceptorList.size() - 1; i &gt;= 0; --i) &#123;        HandlerInterceptor interceptor = (HandlerInterceptor)this.interceptorList.get(i);        interceptor.postHandle(request, response, this.handler, mv);    &#125;&#125;void triggerAfterCompletion(HttpServletRequest request, HttpServletResponse response, @Nullable Exception ex) &#123;    // --i 所以 afterCompletion 是逆序的    // 并不会遍历全部拦截器执行 afterCompletion    // 而是根据 preHandle 的执行个数来执行对应的 afterCompletion    // 如果现在存在 1 ~ 5 五个拦截器，当 3 返回 false    // 那么 afterCompletion 只会执行 1、2    for(int i = this.interceptorIndex; i &gt;= 0; --i) &#123;        HandlerInterceptor interceptor = (HandlerInterceptor)this.interceptorList.get(i);        try &#123;            interceptor.afterCompletion(request, response, this.handler, ex);        &#125; catch (Throwable ex2) &#123;            logger.error(&quot;HandlerInterceptor.afterCompletion threw exception in interceptor [&quot; + String.valueOf(interceptor) + &quot;]&quot;, ex2);        &#125;    &#125;&#125;

HttpMessageConverterHttpMessageConverter 是 Spring MVC 中用于将 HTTP 请求和响应的消息体进行转换的接口。它可以将请求体中的数据转换为 Java 对象，也可以将 Java 对象转换为响应体中的数据。
Spring MVC 提供了两个注解用于处理请求和响应的消息体：@RequestBody 和 @ResponseBody。也提供了两个实体类用于接收和返回数据：RequestEntity 和 ResponseEntity。
请求报文@RequestBody@RequestBody 注解用于将 请求体中的数据绑定到方法指定参数上。它通常用于处理 POST 请求中的 JSON、XML 或其他格式的数据。
@PostMappingpublic String insert(@RequestBody String requestBody) &#123;    System.out.println(requestBody);    // name=Tom&amp;age=20    return &quot;success&quot;;&#125;

RequestEntityRequestEntity 是 Spring MVC 提供的一个实体类，用于封装 HTTP 请求的相关信息，包括请求头、请求体和请求方法等。它可以用于接收请求体中的数据，并提供了更多的功能和灵活性。
@PostMappingpublic String insert(RequestEntity&lt;String&gt; entity) &#123;    // 全部信息    System.out.println(entity.toString());      // 略    // 请求方式    System.out.println(entity.getMethod());     // POST    // 请求类型    System.out.println(entity.getType());       // class java.lang.String    // 请求路径    System.out.println(entity.getUrl());        // http://localhost:8080/springmvc03/user    // 请求体    System.out.println(entity.getBody());       // name=Tom&amp;age=20    // 请求头    System.out.println(entity.getHeaders());    // 略    return &quot;success&quot;;&#125;

响应报文在 Java Web 阶段学习中，响应报文是通过 HttpServletResponse 对象来返回数据的。而 Spring MVC 中，默认的返回值会被解析为视图名称，返回给客户端的是视图页面。如果想要返回数据而不是视图页面，可以使用 @ResponseBody 注解。
@PostMappingpublic void insert(HttpServletResponse response) throws IOException &#123;    User user = new User();    user.setName(&quot;Tom&quot;);    user.setAge(20);    response.getWriter().write(user.toString());    // User&#123;id=&#x27;null&#x27;, name=&#x27;Tom&#x27;, age=20&#125;&#125;

@ResponseBody@ResponseBody 注解用于将方法的返回值作为响应体返回给客户端。在 Spring MVC 中，如果使用该注解，那么返回值就不会再作为视图名称进行解析，而是作为数据返回给客户端。
@PostMapping@ResponseBodypublic String insert() &#123;    return &quot;success&quot;;&#125;

发送请求后，页面并没有进行跳转，而是在空白页面上显示 success 文字。
@PostMapping@ResponseBodypublic User insert()  &#123;    User user = new User();    user.setName(&quot;Tom&quot;);    user.setAge(20);    return user;&#125;

如果直接返回对象，Spring MVC 会尝试将对象转换为 JSON 格式的数据返回给客户端，但此时会报错，需要引入 JSON 转换的依赖包。
&lt;dependency&gt;    &lt;groupId&gt;com.fasterxml.jackson.core&lt;/groupId&gt;    &lt;artifactId&gt;jackson-databind&lt;/artifactId&gt;    &lt;version&gt;2.21.4&lt;/version&gt;&lt;/dependency&gt;

无需任何配置，只需要添加依赖即可。再次发送请求，页面会显示 &#123;&quot;id&quot;:null,&quot;name&quot;:&quot;Tom&quot;,&quot;age&quot;:20&#125;，说明 Spring MVC 已经将对象转换为 JSON 格式的数据返回给客户端。
&#123; &quot;id&quot;: null, &quot;name&quot;: &quot;Tom&quot;, &quot;age&quot;: 20 &#125;

如果还未生效的话看一下 springmvc-config.xml 中是否配置了 &lt;mvc:annotation-driven /&gt;，如果没有配置的话，需要添加该配置。
