&lt;body&gt;  &lt;a th:href=&quot;@&#123;/test&#125;&quot; onclick=&quot;test(event)&quot;&gt;Test&lt;/a&gt;&lt;/body&gt;&lt;!-- 引入 Axios --&gt;&lt;script src=&quot;https://unpkg.com.cn/axios/dist/axios.min.js&quot;&gt;&lt;/script&gt;&lt;script&gt;  function test(event) &#123;    // 阻止默认事件    event.preventDefault();    // 发送 post 请求    axios      .post(event.target.href, &#123;        username: &quot;admin&quot;,        password: &quot;123456&quot;,      &#125;)      .then((res) =&gt; &#123;        console.log(res.data);        // &#123;        //     &quot;id&quot;: null,        //     &quot;name&quot;: &quot;Tom&quot;,        //     &quot;age&quot;: 20        // &#125;      &#125;);  &#125;&lt;/script&gt;

@PostMapping(&quot;/test&quot;)@ResponseBodypublic User test(@RequestBody String requestBody)  &#123;    // 因为是请求头中的 Content-Type: application/json 所以是 JSON 结构    System.out.println(requestBody);    // &#123;&quot;username&quot;:&quot;admin&quot;,&quot;password&quot;:&quot;123456&quot;&#125;    User user = new User();    user.setName(&quot;Tom&quot;);    user.setAge(20);    return user;&#125;

@RestController在实际开发中，包括各服务之间的数据交互，都是以 JSON 为主，因此 @ResponseBody 注解经常会用到。但是如果给每个方法都添加该注解，很浪费时间，因此 Spring MVC 将 @Controller 和 @ResponseBody 两个注解结合为 @RestController。在 Controller 上使用该注解，则所有方法的返回值都会被转为 JSON。
ResponseEntityResponseEntity 可以作为控制器方法的返回值类型，将 ResponseEntity 返回给客户端。
在没有 ResponseEntity 之前，我们只能控制响应的响应体，也就是返回的数据；而 ResponseEntity 中提供了一系列的方法来设置状态码、响应头、响应体。
@PostMapping(&quot;/test&quot;)@ResponseBodypublic ResponseEntity&lt;User&gt; test(@RequestBody String requestBody) &#123;    System.out.println(requestBody);    User user = new User();    user.setName(&quot;Tom&quot;);    user.setAge(20);    // 设置状态码 200、响应头 custom-header: hello、响应体 user    return ResponseEntity.status(200).header(&quot;custom-header&quot;, &quot;hello&quot;).body(user);&#125;

不过，ResponseEntity 最重要的用途是用于文件下载。
@GetMapping(&quot;/download&quot;)@ResponseBodypublic ResponseEntity&lt;byte[]&gt; download(HttpSession session) throws IOException &#123;    // 获取 ServletContext    ServletContext servletContext = session.getServletContext();    // 获取文件地址    String realPath = servletContext.getRealPath(&quot;/static/img/test-img.png&quot;);    // 加载文件    InputStream inputStream = new FileInputStream(realPath);    // 读取文件内容    byte[] bytes = inputStream.readAllBytes();    inputStream.close();    return ResponseEntity.status(HttpStatus.OK)            .header(HttpHeaders.CONTENT_DISPOSITION, &quot;attachment;filename=test-img.png&quot;)            .body(bytes);&#125;

ResponseEntity将文件以 byte[] 一次性读入内存，再通过 ResponseEntity 设置响应头和响应体返回给浏览器，适合小文件下载。
@GetMapping(&quot;/download1&quot;)public ResponseEntity&lt;byte[]&gt; download() throws IOException &#123;    byte[] bytes = Files.readAllBytes(Path.of(&quot;/path/to/test-img.png&quot;));    return ResponseEntity.ok()            .header(HttpHeaders.CONTENT_DISPOSITION, &quot;attachment;filename=test-img.png&quot;)            // &quot;通用的二进制流&quot; 浏览器收到这个类型时，不会尝试解析或渲染，而是直接触发下载。            .contentType(MediaType.APPLICATION_OCTET_STREAM)            .body(bytes);&#125;

HttpServletResponse 直接写流绕过了 Spring 的返回值处理机制，直接操作原生 Servlet 响应对象。
@GetMapping(&quot;/download2&quot;)public void download(HttpServletResponse response) throws IOException &#123;    // 设置响应头    response.setContentType(&quot;application/octet-stream&quot;);    response.setHeader(&quot;Content-Disposition&quot;, &quot;attachment;filename=test-img.png&quot;);    // 获取文件流并写出    byte[] bytes = Files.readAllBytes(Path.of(&quot;/path/to/test-img.png&quot;));    OutputStream os = response.getOutputStream();    os.write(bytes);    os.flush();&#125;

ResponseEntity + InputStreamResource（大文件推荐）不把整个文件读进内存，而是一边读一边写，适合大文件。
@GetMapping(&quot;/download3&quot;)public ResponseEntity&lt;Resource&gt; download() throws IOException &#123;    File file = new File(&quot;/path/to/test-img.png&quot;);    InputStreamResource resource = new InputStreamResource(new FileInputStream(file));    return ResponseEntity.ok()            .header(HttpHeaders.CONTENT_DISPOSITION, &quot;attachment;filename=test-img.png&quot;)            .contentLength(file.length())            // &quot;通用的二进制流&quot; 浏览器收到这个类型时，不会尝试解析或渲染，而是直接触发下载。            .contentType(MediaType.APPLICATION_OCTET_STREAM)            .body(resource);&#125;

StreamingResponseBody（超大文件 &#x2F; 异步流式）StreamingResponseBody 会在响应提交后由容器异步写出内容，边读边写，不占用 Web 容器线程，适合超大文件下载。
@GetMapping(&quot;/download4&quot;)public ResponseEntity&lt;StreamingResponseBody&gt; download() &#123;    StreamingResponseBody stream = outputStream -&gt; &#123;        try (InputStream is = new FileInputStream(&quot;/path/to/large-file.zip&quot;)) &#123;            byte[] buffer = new byte[8192];            int bytesRead;            while ((bytesRead = is.read(buffer)) != -1) &#123;                outputStream.write(buffer, 0, bytesRead);            &#125;        &#125;    &#125;;    return ResponseEntity.ok()            .header(HttpHeaders.CONTENT_DISPOSITION, &quot;attachment;filename=large-file.zip&quot;)            // &quot;通用的二进制流&quot; 浏览器收到这个类型时，不会尝试解析或渲染，而是直接触发下载。            .contentType(MediaType.APPLICATION_OCTET_STREAM)            .body(stream);&#125;

