public class UsernamePasswordAuthenticationFilter extends AbstractAuthenticationProcessingFilter &#123;    public static final String SPRING_SECURITY_FORM_USERNAME_KEY = &quot;username&quot;;    public static final String SPRING_SECURITY_FORM_PASSWORD_KEY = &quot;password&quot;;    private static final RequestMatcher DEFAULT_PATH_REQUEST_MATCHER = PathPatternRequestMatcher.withDefaults()        .matcher(HttpMethod.POST, &quot;/login&quot;);    private String usernameParameter = SPRING_SECURITY_FORM_USERNAME_KEY;    private String passwordParameter = SPRING_SECURITY_FORM_PASSWORD_KEY;    private boolean postOnly = true;    public UsernamePasswordAuthenticationFilter() &#123;        super(DEFAULT_PATH_REQUEST_MATCHER);    &#125;    public UsernamePasswordAuthenticationFilter(AuthenticationManager authenticationManager) &#123;        super(DEFAULT_PATH_REQUEST_MATCHER, authenticationManager);    &#125;    @Override    public Authentication attemptAuthentication(HttpServletRequest request, HttpServletResponse response)            throws AuthenticationException &#123;        if (this.postOnly &amp;&amp; !request.getMethod().equals(&quot;POST&quot;)) &#123;            throw new AuthenticationServiceException(&quot;Authentication method not supported: &quot; + request.getMethod());        &#125;        String username = obtainUsername(request);        username = (username != null) ? username.trim() : &quot;&quot;;        String password = obtainPassword(request);        password = (password != null) ? password : &quot;&quot;;        UsernamePasswordAuthenticationToken authRequest = UsernamePasswordAuthenticationToken.unauthenticated(username,                password);        // Allow subclasses to set the &quot;details&quot; property        setDetails(request, authRequest);        // 进入到 ProviderManager 的 authenticate 方法        return this.getAuthenticationManager().authenticate(authRequest);    &#125;    // .....&#125;

public class ProviderManager implements AuthenticationManager, MessageSourceAware, InitializingBean &#123;    // ......    @Override    public Authentication authenticate(Authentication authentication) throws AuthenticationException &#123;        Class&lt;? extends Authentication&gt; toTest = authentication.getClass();        AuthenticationException lastException = null;        AuthenticationException parentException = null;        Authentication result = null;        Authentication parentResult = null;        int currentPosition = 0;        int size = this.providers.size();        // getProviders 获取所有的 AuthenticationProvider        for (AuthenticationProvider provider : getProviders()) &#123;            // 判断当前 AuthenticationProvider 是否支持，遍历直到遇到 DaoAuthenticationProvider            if (!provider.supports(toTest)) &#123;                continue;            &#125;            if (logger.isTraceEnabled()) &#123;                logger.trace(LogMessage.format(&quot;Authenticating request with %s (%d/%d)&quot;,                        provider.getClass().getSimpleName(), ++currentPosition, size));            &#125;            try &#123;                // 调用 DaoAuthenticationProvider 的 authenticate 方法                // 进入 AbstractUserDetailsAuthenticationProvider                result = provider.authenticate(authentication);                if (result != null) &#123;                    copyDetails(authentication, result);                    break;                &#125;            &#125;            catch (AccountStatusException ex) &#123;                prepareException(ex, authentication);                logger.debug(LogMessage.format(&quot;Authentication failed for user &#x27;%s&#x27; since their account status is %s&quot;,                        authentication.getName(), ex.getMessage()), ex);                // SEC-546: Avoid polling additional providers if auth failure is due to                // invalid account status                throw ex;            &#125;           