public abstract class AbstractUserDetailsAuthenticationProvider        implements AuthenticationProvider, InitializingBean, MessageSourceAware &#123;    // ......    @Override    public Authentication authenticate(Authentication authentication) throws AuthenticationException &#123;        Assert.isInstanceOf(UsernamePasswordAuthenticationToken.class, authentication,                () -&gt; this.messages.getMessage(&quot;AbstractUserDetailsAuthenticationProvider.onlySupports&quot;,                        &quot;Only UsernamePasswordAuthenticationToken is supported&quot;));        String username = determineUsername(authentication);        boolean cacheWasUsed = true;        UserDetails user = this.userCache.getUserFromCache(username);        if (user == null) &#123;            cacheWasUsed = false;            try &#123;                // 用户校验                // 进入 DaoAuthenticationProvider 的 retrieveUser 方法                user = retrieveUser(username, (UsernamePasswordAuthenticationToken) authentication);            &#125;            catch (UsernameNotFoundException ex) &#123;                this.logger.debug(LogMessage.format(&quot;Failed to find user &#x27;%s&#x27;&quot;, username));                String message = this.messages.getMessage(&quot;AbstractUserDetailsAuthenticationProvider.badCredentials&quot;,                        &quot;Bad credentials&quot;);                if (!this.hideUserNotFoundExceptions) &#123;                    throw ex;                &#125;                throw new BadCredentialsException(message, ex);            &#125;            Assert.notNull(user, &quot;retrieveUser returned null - a violation of the interface contract&quot;);        &#125;        try &#123;            // 拿到用户信息后检查用户状态            performPreCheck(user, (UsernamePasswordAuthenticationToken) authentication);        &#125;        catch (AuthenticationException ex) &#123;            if (!cacheWasUsed) &#123;                throw ex;            &#125;            // There was a problem, so try again after checking            // we&#x27;re using latest data (i.e. not from the cache)            cacheWasUsed = false;            user = retrieveUser(username, (UsernamePasswordAuthenticationToken) authentication);            performPreCheck(user, (UsernamePasswordAuthenticationToken) authentication);        &#125;        this.postAuthenticationChecks.check(user);        if (!cacheWasUsed) &#123;            this.userCache.putUserInCache(user);        &#125;        Object principalToReturn = user;        if (this.forcePrincipalAsString) &#123;            principalToReturn = user.getUsername();        &#125;        return createSuccessAuthentication(principalToReturn, authentication, user);    &#125;    private void performPreCheck(UserDetails user, UsernamePasswordAuthenticationToken authentication) &#123;        try &#123;            // 进入下面的 check 方法            this.preAuthenticationChecks.check(user);        &#125;        catch (AuthenticationException ex) &#123;            if (!this.alwaysPerformAdditionalChecksOnUser) &#123;                throw ex;            &#125;            try &#123;                additionalAuthenticationChecks(user, authentication);            &#125;            catch (AuthenticationException ignored) &#123;                // preserve the original failed check            &#125;            throw ex;        &#125;        additionalAuthenticationChecks(user, authentication);    &#125;    private class DefaultPreAuthenticationChecks implements UserDetailsChecker &#123;        @Override        public void check(UserDetails user) &#123;            // 账号是否被锁定            if (!user.isAccountNonLocked()) &#123;                AbstractUserDetailsAuthenticationProvider.this.logger                    .debug(&quot;Failed to authenticate since user account is locked&quot;);                throw new LockedException(AbstractUserDetailsAuthenticationProvider.this.messages                    .getMessage(&quot;AbstractUserDetailsAuthenticationProvider.locked&quot;, &quot;User account is locked&quot;));            &#125;            // 账号是否可用            if (!user.isEnabled()) &#123;                AbstractUserDetailsAuthenticationProvider.this.logger                    .debug(&quot;Failed to authenticate since user account is disabled&quot;);                throw new DisabledException(AbstractUserDetailsAuthenticationProvider.this.messages                    .getMessage(&quot;AbstractUserDetailsAuthenticationProvider.disabled&quot;, &quot;User is disabled&quot;));            &#125;            // 账号是否过期            if (!user.isAccountNonExpired()) &#123;                AbstractUserDetailsAuthenticationProvider.this.logger                    .debug(&quot;Failed to authenticate since user account has expired&quot;);                throw new AccountExpiredException(AbstractUserDetailsAuthenticationProvider.this.messages                    .getMessage(&quot;AbstractUserDetailsAuthenticationProvider.expired&quot;, &quot;User account has expired&quot;));            &#125;        &#125;    &#125;    // ......&#125;

public class DaoAuthenticationProvider extends AbstractUserDetailsAuthenticationProvider &#123;    // .....    @Override    protected final UserDetails retrieveUser(String username, UsernamePasswordAuthenticationToken authentication)            throws AuthenticationException &#123;        prepareTimingAttackProtection();        try &#123;            // 通过 UserDetailService 的 loadUserByUsername 方法加载用户信息，如果用户信息为 null，则认证失败            // 进入 InMemoryUserDetailsManager 的 loadUserByUsername 方法            UserDetails loadedUser = this.getUserDetailsService().loadUserByUsername(username);            if (loadedUser == null) &#123;                throw new InternalAuthenticationServiceException(                        &quot;UserDetailsService returned null, which is an interface contract violation&quot;);            &#125;            return loadedUser;        &#125;        catch (UsernameNotFoundException ex) &#123;            mitigateAgainstTimingAttack(authentication);            throw ex;        &#125;        catch (InternalAuthenticationServiceException ex) &#123;            throw ex;        &#125;        catch (Exception ex) &#123;            throw new InternalAuthenticationServiceException(ex.getMessage(), ex);        &#125;    &#125;    // ......&#125;

public class InMemoryUserDetailsManager implements UserDetailsManager, UserDetailsPasswordService &#123;    // .....    @Override    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException &#123;        UserDetails user = this.users.get(username.toLowerCase(Locale.ROOT));        if (user == null) &#123;            throw UsernameNotFoundException.fromUsername(username);        &#125;        if (user instanceof CredentialsContainer) &#123;            return user;        &#125;        // 返回 User 信息        // 用户名、已加密的密码、账号是否启用、账号是否未过期、密码是否未过期、账号是否未锁定、权限/角色集合        return new User(user.getUsername(), user.getPassword(), user.isEnabled(), user.isAccountNonExpired(),                user.isCredentialsNonExpired(), user.isAccountNonLocked(), user.getAuthorities());    &#125;&#125;

UserDetailsService 接口根据上面的源码，一切认证的基础都是基于 loadUserByUsername 方法构建出的 User 信息，因此如果想自定义认证逻辑，就需要实现 UserDetailsService 接口的 loadUserByUsername 方法
public interface UserDetailsService &#123;    UserDetails loadUserByUsername(String username) throws UsernameNotFoundException;&#125;

这里的 loadUserByUsername 方法需要返回一个 UserDetails 对象，但是源码中返回的是 User 对象，这是因为 User 是 UserDetails 的实现类
public class User implements UserDetails, CredentialsContainer &#123;    private static final long serialVersionUID = 620L;    private static final Log logger = LogFactory.getLog(User.class);    // 密码    private @Nullable String password;    // 用户名    private final String username;    // 权限    private final Set&lt;GrantedAuthority&gt; authorities;    // 是否过期    private final boolean accountNonExpired;    // 是否锁定    private final boolean accountNonLocked;    // 密码是否过期    private final boolean credentialsNonExpired;    // 是否可用    private final boolean enabled;&#125;

