@Beanpublic SecurityFilterChain securityFilterChain(HttpSecurity httpSecurity) &#123;    httpSecurity.authorizeHttpRequests(auth -&gt; auth                    // 放行 /login                    .requestMatchers(&quot;/login&quot;).permitAll()                    // 拦截其他请求                    .anyRequest().authenticated())            .formLogin(form -&gt; form                    // 登录页面                    .loginPage(&quot;/login&quot;)                    // 登录请求路径                    .loginProcessingUrl(&quot;/auth/login&quot;)                    // 登录成功跳转至该页面                    .defaultSuccessUrl(&quot;/success&quot;)                    // 登录失败跳转至该页面                    .failureUrl(&quot;/error&quot;)                    // 修改表单参数                    .usernameParameter(&quot;username&quot;)                    .passwordParameter(&quot;password&quot;)            )            .logout(logout -&gt; logout                    // 修改退出登录的请求路径                    .logoutUrl(&quot;/auth/logout&quot;))            .csrf(CsrfConfigurer::disable);    return httpSecurity.build();&#125;

