原理负责退出登录的过滤器为 LogoutFilter
public class LogoutFilter extends GenericFilterBean &#123;    @Override    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)            throws IOException, ServletException &#123;        doFilter((HttpServletRequest) request, (HttpServletResponse) response, chain);    &#125;    private void doFilter(HttpServletRequest request, HttpServletResponse response, FilterChain chain)            throws IOException, ServletException &#123;        // 拦截请求判断请求路径是不是退出登录的请求        // 默认是 /logout        if (requiresLogout(request, response)) &#123;            // 从容器中取出认证信息            Authentication auth = this.securityContextHolderStrategy.getContext().getAuthentication();            if (this.logger.isDebugEnabled()) &#123;                this.logger.debug(LogMessage.format(&quot;Logging out [%s]&quot;, auth));            &#125;            // 退出登录流程            // 进入 CompositeLogoutHandler 的 logout 方法            this.handler.logout(request, response, auth);            this.logoutSuccessHandler.onLogoutSuccess(request, response, auth);            return;        &#125;        chain.doFilter(request, response);    &#125;    //......&#125;

public final class CompositeLogoutHandler implements LogoutHandler &#123;    private final List&lt;LogoutHandler&gt; logoutHandlers;    public CompositeLogoutHandler(LogoutHandler... logoutHandlers) &#123;        Assert.notEmpty(logoutHandlers, &quot;LogoutHandlers are required&quot;);        this.logoutHandlers = Arrays.asList(logoutHandlers);    &#125;    public CompositeLogoutHandler(List&lt;LogoutHandler&gt; logoutHandlers) &#123;        Assert.notEmpty(logoutHandlers, &quot;LogoutHandlers are required&quot;);        this.logoutHandlers = logoutHandlers;    &#125;    @Override    public void logout(HttpServletRequest request, HttpServletResponse response,            @Nullable Authentication authentication) &#123;        // 遍历所有处理器        // 进入 SecurityContextLogoutHandler 的 logout 方法        for (LogoutHandler handler : this.logoutHandlers) &#123;            handler.logout(request, response, authentication);        &#125;    &#125;&#125;

public class SecurityContextLogoutHandler implements LogoutHandler &#123;    protected final Log logger = LogFactory.getLog(this.getClass());    private SecurityContextHolderStrategy securityContextHolderStrategy = SecurityContextHolder        .getContextHolderStrategy();    private boolean invalidateHttpSession = true;    private boolean clearAuthentication = true;    private SecurityContextRepository securityContextRepository = new HttpSessionSecurityContextRepository();    @Override    public void logout(HttpServletRequest request, HttpServletResponse response,            @Nullable Authentication authentication) &#123;        Assert.notNull(request, &quot;HttpServletRequest required&quot;);        if (this.invalidateHttpSession) &#123;            // 获取 session            HttpSession session = request.getSession(false);            if (session != null) &#123;                // 让 session 立刻失效                session.invalidate();                if (this.logger.isDebugEnabled()) &#123;                    this.logger.debug(LogMessage.format(&quot;Invalidated session %s&quot;, session.getId()));                &#125;            &#125;        &#125;        // 清空容器        SecurityContext context = this.securityContextHolderStrategy.getContext();        this.securityContextHolderStrategy.clearContext();        // 清空认证信息        if (this.clearAuthentication) &#123;            context.setAuthentication(null);        &#125;        // 设置空的容器        SecurityContext emptyContext = this.securityContextHolderStrategy.createEmptyContext();        this.securityContextRepository.saveContext(emptyContext, request, response);    &#125;    public boolean isInvalidateHttpSession() &#123;        return this.invalidateHttpSession;    &#125;    public void setSecurityContextHolderStrategy(SecurityContextHolderStrategy securityContextHolderStrategy) &#123;        Assert.notNull(securityContextHolderStrategy, &quot;securityContextHolderStrategy cannot be null&quot;);        this.securityContextHolderStrategy = securityContextHolderStrategy;    &#125;    public void setInvalidateHttpSession(boolean invalidateHttpSession) &#123;        this.invalidateHttpSession = invalidateHttpSession;    &#125;    public void setClearAuthentication(boolean clearAuthentication) &#123;        this.clearAuthentication = clearAuthentication;    &#125;    public void setSecurityContextRepository(SecurityContextRepository securityContextRepository) &#123;        Assert.notNull(securityContextRepository, &quot;securityContextRepository cannot be null&quot;);        this.securityContextRepository = securityContextRepository;    &#125;&#125;

