&lt;div class=&quot;form-group remember-row&quot;&gt;  &lt;input type=&quot;checkbox&quot; id=&quot;remember-me&quot; name=&quot;remember-me&quot; value=&quot;true&quot; /&gt;  &lt;label for=&quot;remember-me&quot; style=&quot;margin: 0;&quot;&gt;记住我&lt;/label&gt;&lt;/div&gt;

既然需要数据库存储，那么就需要建表
CREATE TABLE persistent_logins (    username  VARCHAR(64) NOT NULL,    series    VARCHAR(64) PRIMARY KEY,    token     VARCHAR(64) NOT NULL,    last_used TIMESTAMP   NOT NULL);

添加配置类6.x// 6.x 可以这么写（JdbcTokenRepositoryImpl 底层基于 JdbcDaoSupport，自 7.0 起已弃用并标记为移除）@Beanpublic PersistentTokenRepository persistentTokenRepository(DataSource dataSource) &#123;    JdbcTokenRepositoryImpl jdbcTokenRepository = new JdbcTokenRepositoryImpl();    jdbcTokenRepository.setDataSource(dataSource);    return jdbcTokenRepository;&#125;

7.x// 7.x 只能自己通过 JdbcTemplate 手动实现@Component@AllArgsConstructorpublic class CustomPersistentTokenRepository implements PersistentTokenRepository &#123;    private JdbcTemplate jdbcTemplate;    @Override    public void createNewToken(PersistentRememberMeToken token) &#123;        String sql = &quot;INSERT INTO persistent_logins (username, series, token, last_used) VALUES (?, ?, ?, ?)&quot;;        jdbcTemplate.update(sql, token.getUsername(), token.getSeries(), token.getTokenValue(), token.getDate());    &#125;    @Override    public void updateToken(@NonNull String series, @NonNull String tokenValue, @NonNull Date lastUsed) &#123;        String sql = &quot;UPDATE persistent_logins SET token = ?, last_used = ? WHERE series = ?&quot;;        jdbcTemplate.update(sql, tokenValue, lastUsed, series);    &#125;    @Override    public PersistentRememberMeToken getTokenForSeries(@NonNull String seriesId) &#123;        String sql = &quot;SELECT username, series, token, last_used FROM persistent_logins WHERE series = ?&quot;;        try &#123;            return jdbcTemplate.queryForObject(sql, (rs, rowNum) -&gt;                    new PersistentRememberMeToken(                            rs.getString(&quot;username&quot;),                            rs.getString(&quot;series&quot;),                            rs.getString(&quot;token&quot;),                            rs.getTimestamp(&quot;last_used&quot;)                    ), seriesId            );        &#125; catch (EmptyResultDataAccessException e) &#123;            return null;        &#125;    &#125;    @Override    public void removeUserTokens(@NonNull String username) &#123;        String sql = &quot;DELETE FROM persistent_logins WHERE username = ?&quot;;        jdbcTemplate.update(sql, username);    &#125;&#125;

@Bean// 这里需要注入自定义的 PersistentTokenRepository 和 UserDetailsServicepublic SecurityFilterChain securityFilterChain(HttpSecurity httpSecurity,                                                PersistentTokenRepository persistentTokenRepository,                                                UserDetailsService userDetailsService) &#123;    httpSecurity.authorizeHttpRequests(auth -&gt; auth                    // 放行 /login                    .requestMatchers(&quot;/login&quot;).permitAll()                    // 拦截其他请求                    .anyRequest().authenticated())            .formLogin(form -&gt; form                    // 登录页面                    .loginPage(&quot;/login&quot;)                    // 登录请求路径                    .loginProcessingUrl(&quot;/auth/login&quot;)                    // 登录成功跳转至该页面                    .defaultSuccessUrl(&quot;/success&quot;)                    // 登录失败跳转至该页面                    .failureUrl(&quot;/error&quot;)                    // 修改表单参数                    .usernameParameter(&quot;username&quot;)                    .passwordParameter(&quot;password&quot;)            )            .logout(logout -&gt; logout                    // 修改退出登录的请求路径                    .logoutUrl(&quot;/auth/logout&quot;))            .rememberMe(remember -&gt; remember                    // 过期时间                    .tokenValiditySeconds(7 * 24 * 3600)                    // 设置域信息                    // .rememberMeCookieDomain()                    // 设置令牌仓库                    .tokenRepository(persistentTokenRepository)                    // 设置 userDetailsService                    .userDetailsService(userDetailsService)                    // 设置密钥                    .key(&quot;my_security_key&quot;)            )            .csrf(CsrfConfigurer::disable);    return httpSecurity.build();&#125;

