@Override@NullMarkedpublic UserDetails loadUserByUsername(String username) throws UsernameNotFoundException &#123;    LambdaQueryWrapper&lt;User&gt; queryWrapper = new LambdaQueryWrapper&lt;&gt;();    queryWrapper.eq(User::getUsername, username);    User user = userMapper.selectOne(queryWrapper);    // 用户不存在，抛出 UsernameNotFoundException（抛 RuntimeException 会被当成系统内部错误）    if (Objects.isNull(user)) &#123;        throw new UsernameNotFoundException(&quot;user &#x27;&quot; + username + &quot;&#x27; does not exist&quot;);    &#125;    // 用户存在，构建用户信息    return user;&#125;

